# Expression Node - Core building block for mathematical expressions
# Represents nodes in the expression tree

class ExpressionNode
  attr_accessor :isleaf, :data, :left, :right, :parent, :type
  
  def initialize(is_leaf, value)
    @isleaf = is_leaf
    # Numbers (Integer, Float) cannot be cloned, only dup them or copy directly
    @data = value.is_a?(Numeric) ? value : value.clone
    @left = nil
    @right = nil
    @parent = nil
    @type = nil
  end
  
  # Deep clone of node and its subtree
  def deep_clone
    new_node = ExpressionNode.new(@isleaf, @data)
    new_node.type = @type
    
    if @left
      new_node.left = @left.deep_clone
      new_node.left.parent = new_node
    end
    
    if @right
      new_node.right = @right.deep_clone
      new_node.right.parent = new_node
    end
    
    new_node
  end
  
  # Connect a child node
  def connect(node, direction)
    case direction.upcase
    when "L", "LEFT"
      @left = node
      node.parent = self if node
    when "R", "RIGHT"
      @right = node
      node.parent = self if node
    end
  end
  
  # Evaluate the expression with given variable values
  def evaluate(var_values)
    return 0 unless self
    
    if @isleaf
      case @data
      when Numeric
        return @data.to_f
      when String
        return var_values[@data].to_f if var_values[@data]
        return 0.0
      end
    end
    
    # Operator evaluation
    case @data
    when '+'
      return @left.evaluate(var_values) + @right.evaluate(var_values)
    when '-'
      return @left.evaluate(var_values) - @right.evaluate(var_values)
    when '*'
      return @left.evaluate(var_values) * @right.evaluate(var_values)
    when '/'
      right_val = @right.evaluate(var_values)
      return right_val != 0 ? @left.evaluate(var_values) / right_val : Float::INFINITY
    when '^'
      return @left.evaluate(var_values) ** @right.evaluate(var_values)
    when 'sin'
      return Math.sin(@right.evaluate(var_values))
    when 'cos'
      return Math.cos(@right.evaluate(var_values))
    when 'tan'
      return Math.tan(@right.evaluate(var_values))
    when 'cot'
      val = Math.tan(@right.evaluate(var_values))
      return val != 0 ? 1.0 / val : Float::INFINITY
    when 'sec'
      val = Math.cos(@right.evaluate(var_values))
      return val != 0 ? 1.0 / val : Float::INFINITY
    when 'csc'
      val = Math.sin(@right.evaluate(var_values))
      return val != 0 ? 1.0 / val : Float::INFINITY
    when 'sinh'
      return Math.sinh(@right.evaluate(var_values))
    when 'cosh'
      return Math.cosh(@right.evaluate(var_values))
    when 'tanh'
      return Math.tanh(@right.evaluate(var_values))
    when 'sech'
      arg = @right.evaluate(var_values)
      if arg.abs > 20
        # cosh can overflow while its reciprocal is still representable.
        tail = Math.exp(-arg.abs)
        return 2.0 * tail / (1.0 + tail * tail)
      end
      return 1.0 / Math.cosh(arg)
    when 'csch'
      arg = @right.evaluate(var_values)
      if arg.abs > 20
        tail = Math.exp(-arg.abs)
        return (arg.negative? ? -2.0 : 2.0) * tail / (1.0 - tail * tail)
      end
      # Keep the direct path near zero to avoid subtractive cancellation.
      return 1.0 / Math.sinh(arg)
    when 'coth'
      # 1/tanh avoids the Inf/Inf produced by cosh/sinh for large arguments.
      return 1.0 / Math.tanh(@right.evaluate(var_values))
    when 'asinh', 'arcsinh'
      return Math.asinh(@right.evaluate(var_values))
    when 'acosh', 'arccosh'
      arg = @right.evaluate(var_values)
      return arg >= 1 ? Math.acosh(arg) : Float::NAN
    when 'atanh', 'arctanh'
      arg = @right.evaluate(var_values)
      return arg.abs <= 1 ? Math.atanh(arg) : Float::NAN
    when 'ln'
      arg = @right.evaluate(var_values)
      return arg > 0 ? Math.log(arg) : Float::NAN
    when 'exp'
      return Math.exp(@right.evaluate(var_values))
    when 'abs'
      return (@right.evaluate(var_values)).abs
    when 'sqrt'
      arg = @right.evaluate(var_values)
      return arg >= 0 ? Math.sqrt(arg) : Float::NAN
    when 'arctan'
      return Math.atan(@right.evaluate(var_values))
    when 'arcsin'
      arg = @right.evaluate(var_values)
      return arg.abs <= 1 ? Math.asin(arg) : Float::NAN
    when 'arccos'
      arg = @right.evaluate(var_values)
      return arg.abs <= 1 ? Math.acos(arg) : Float::NAN
    when 'erf'
      return Math.erf(@right.evaluate(var_values))
    when 'Si'
      x = @right.evaluate(var_values)
