      return Float::NAN unless x > 0
      return SF_EULER_GAMMA + Math.log(x) + sf_quad(x) { |t| t.zero? ? 0.0 : (Math.cos(t) - 1.0) / t }
    when 'Ei'
      x = @right.evaluate(var_values)
      return Float::NAN if x.zero?
      return SF_EULER_GAMMA + Math.log(x.abs) + sf_quad(x) { |t| t.zero? ? 1.0 : (Math.exp(t) - 1.0) / t }
    when 'li'
      x = @right.evaluate(var_values)
      return Float::NAN unless x > 0 && x != 1.0
      lx = Math.log(x)
      return SF_EULER_GAMMA + Math.log(lx.abs) + sf_quad(lx) { |t| t.zero? ? 1.0 : (Math.exp(t) - 1.0) / t }
    when 'FresnelS'
