    when 'FresnelC'
      return sf_quad(@right.evaluate(var_values)) { |t| Math.cos(t * t) }
    else
      return 0.0
    end
  end

  SF_EULER_GAMMA = 0.5772156649015329

  # Composite Simpson quadrature of the block over [0, x] (handles x < 0).
  def sf_quad(x, n = 600)
    return Float::NAN unless x.is_a?(Numeric) && x.finite?
    return 0.0 if x.zero?
    h = x / n.to_f
    s = yield(0.0) + yield(x)
    (1...n).each { |i| s += yield(i * h) * (i.odd? ? 4 : 2) }
    s * h / 3.0
  end
  
  # Check if subtree is constant with respect to a variable
  def constant_wrt?(variable)
    return false unless self
    
    if @isleaf
      return @data != variable
    end
    
    left_const = @left ? @left.constant_wrt?(variable) : true
    right_const = @right ? @right.constant_wrt?(variable) : true
    
    return left_const && right_const
  end
  
  # Convert decimal to rational string if possible
  def to_rational(num)
    return nil unless num.is_a?(Numeric)
    
    # Use Ruby's Rational class to find the fraction
    rational = num.rationalize(1e-10)
    
    numerator = rational.numerator
    denominator = rational.denominator
    
    # Only show as fraction if denominator is reasonable and it's actually a fraction
    if denominator != 1 && denominator <= 1000
      if numerator < 0
        return "(#{numerator}/#{denominator})"
      else
        return "(#{numerator}/#{denominator})"
      end
    end
    
    nil
  end
  
  # Convert to infix string representation
  def to_infix
    if @isleaf
      # Clean up numeric display
      if @data.is_a?(Numeric)
        # If it's a whole number, display without decimals
        if @data.to_f == @data.to_i.to_f
          return @data.to_i.to_s
        else
          # Try to convert to rational
          rational = to_rational(@data)
          return rational if rational
          return @data.to_s
        end
      else
        return @data.to_s
      end
    end
    
    case @data
    when '+', '-', '*', '/', '^'
      left_str = @left ? @left.to_infix : ""
      right_str = @right ? @right.to_infix : ""
      return "(#{left_str} #{@data} #{right_str})"
    when 'sin', 'cos', 'tan', 'cot', 'sec', 'csc', 'sinh', 'cosh', 'tanh', 'sech', 'csch', 'coth', 'asinh', 'arcsinh', 'acosh', 'arccosh', 'atanh', 'arctanh', 'ln', 'exp', 'abs', 'sqrt', 'arctan', 'arcsin', 'arccos', 'erf', 'Si', 'Ci', 'Ei', 'li', 'FresnelS', 'FresnelC'
      arg_str = @right ? @right.to_infix : ""
      return "#{@data}(#{arg_str})"
    else
      return @data.to_s
    end
  end
