  # Apply reduction formula for higher powers
  # For sin: ∫sin^n(x)dx = -(sin^(n-1)(x)cos(x))/n + (n-1)/n * ∫sin^(n-2)(x)dx
  # For cos: ∫cos^n(x)dx = (cos^(n-1)(x)sin(x))/n + (n-1)/n * ∫cos^(n-2)(x)dx
  def apply_trig_reduction_formula(node, trig_func, n, variable, steps)
    return nil if n <= 4  # Only handle n > 4
    return nil if n > 6   # Limit complexity
    
    # Build sin^(n-2) or cos^(n-2)
    func_node = ExpressionNode.new(false, trig_func)
    func_node.connect(ExpressionNode.new(true, variable), "R")
    
    reduced_power = ExpressionNode.new(false, "^")
    reduced_power.connect(func_node, "L")
    reduced_power.connect(ExpressionNode.new(true, n - 2), "R")
    
    # Recursively integrate the reduced power
    reduced_integral = attempt_trig_power_reduction(reduced_power, variable, nil)
    
    if reduced_integral
      # Reduction formula (WITH the boundary term -- previously dropped, which made
      # n>=5 answers wrong):
      #   sin: ∫sin^n = -(sin^(n-1)·cos)/n + (n-1)/n·∫sin^(n-2)
      #   cos: ∫cos^n =  (cos^(n-1)·sin)/n + (n-1)/n·∫cos^(n-2)
      base = ExpressionNode.new(false, trig_func)
      base.connect(ExpressionNode.new(true, variable), "R")
      pow = ExpressionNode.new(false, "^")
      pow.connect(base, "L")
      pow.connect(ExpressionNode.new(true, n - 1), "R")
      other = ExpressionNode.new(false, (trig_func == 'sin' ? 'cos' : 'sin'))
      other.connect(ExpressionNode.new(true, variable), "R")
      prod = ExpressionNode.new(false, "*")
      prod.connect(pow, "L")
      prod.connect(other, "R")
      boundary = ExpressionNode.new(false, "*")
      boundary.connect(create_rational_fraction((trig_func == 'sin' ? -1 : 1), n), "L")
      boundary.connect(prod, "R")

      recur = ExpressionNode.new(false, "*")
      recur.connect(create_rational_fraction(n - 1, n), "L")
      recur.connect(reduced_integral, "R")

      result = ExpressionNode.new(false, "+")
      result.connect(boundary, "L")
      result.connect(recur, "R")

      return result
    end

    nil
  end
  
  # Integrate tan^n(x)
  def attempt_tan_power_integration(n, variable, steps)
    puts "      [Tan] Integrating tan^#{n}(x)"
    
    if n == 2
      # ∫tan²(x)dx = ∫(sec²(x) - 1)dx = tan(x) - x
      tan_x = ExpressionNode.new(false, "tan")
      tan_x.connect(ExpressionNode.new(true, variable), "R")
      
      result = ExpressionNode.new(false, "-")
      result.connect(tan_x, "L")
      result.connect(ExpressionNode.new(true, variable), "R")
      
      steps << {operation: "integration", rule: "∫tan²(x)dx = tan(x) - x", from: "tan²(x)", to: result.to_infix} if steps
      return result
    elsif n == 3
      # ∫tan³(x)dx = (1/2)tan²(x) + ln|cos(x)|
      tan_x = ExpressionNode.new(false, "tan")
      tan_x.connect(ExpressionNode.new(true, variable), "R")
      
      tan_squared = ExpressionNode.new(false, "^")
      tan_squared.connect(tan_x, "L")
      tan_squared.connect(ExpressionNode.new(true, 2), "R")
      
      half_tan_sq = ExpressionNode.new(false, "*")
      half_tan_sq.connect(create_rational_fraction(1, 2), "L")
      half_tan_sq.connect(tan_squared, "R")
      
      cos_x = ExpressionNode.new(false, "cos")
      cos_x.connect(ExpressionNode.new(true, variable), "R")
      
      abs_cos = ExpressionNode.new(false, "abs")
      abs_cos.connect(cos_x, "R")
      
      ln_cos = ExpressionNode.new(false, "ln")
      ln_cos.connect(abs_cos, "R")
      
      result = ExpressionNode.new(false, "+")
      result.connect(half_tan_sq, "L")
      result.connect(ln_cos, "R")
      
      steps << {operation: "integration", rule: "∫tan³(x)dx = tan²(x)/2 + ln|cos(x)|", from: "tan³(x)", to: result.to_infix} if steps
      return result
    elsif n == 4
      # ∫tan⁴(x)dx = ∫tan²(x)·tan²(x)dx = ∫tan²(x)·(sec²(x)-1)dx
      # = ∫tan²(x)sec²(x)dx - ∫tan²(x)dx
      # = tan³(x)/3 - (tan(x) - x)
      # = tan³(x)/3 - tan(x) + x
      
      tan_x = ExpressionNode.new(false, "tan")
      tan_x.connect(ExpressionNode.new(true, variable), "R")
      
      # tan³(x)
      tan_cubed = ExpressionNode.new(false, "^")
      tan_cubed.connect(tan_x.deep_clone, "L")
      tan_cubed.connect(ExpressionNode.new(true, 3), "R")
      
      # tan³(x)/3
      third_tan_cubed = ExpressionNode.new(false, "*")
      third_tan_cubed.connect(create_rational_fraction(1, 3), "L")
      third_tan_cubed.connect(tan_cubed, "R")
      
      # tan³(x)/3 - tan(x)
      temp = ExpressionNode.new(false, "-")
      temp.connect(third_tan_cubed, "L")
      temp.connect(tan_x, "R")
      
      # tan³(x)/3 - tan(x) + x
      result = ExpressionNode.new(false, "+")
      result.connect(temp, "L")
      result.connect(ExpressionNode.new(true, variable), "R")
      
      steps << {operation: "integration", rule: "∫tan⁴(x)dx = tan³(x)/3 - tan(x) + x", from: "tan⁴(x)", to: result.to_infix} if steps
      return result
    end
    
    ExperimentalRisch.log_debug("      [Tan] Higher tan powers (n>4) not yet implemented", level: 2)
    nil
  end
  
  # Integrate sec^n(x)
  def attempt_sec_power_integration(n, variable, steps)
    ExperimentalRisch.log_debug("      [Sec] Integrating sec^#{n}(x)", level: 2)
    
    # sec^2 is already handled in standard mode
    if n == 2
      # ∫sec²(x)dx = tan(x)
      result = ExpressionNode.new(false, "tan")
      result.connect(ExpressionNode.new(true, variable), "R")
      steps << {operation: "integration", rule: "∫sec²(x)dx = tan(x)", from: "sec²(x)", to: result.to_infix} if steps
      return result
    elsif n == 3
      # ∫sec³(x)dx = (1/2)[sec(x)tan(x) + ln|sec(x)+tan(x)|]
      ExperimentalRisch.log_debug("      [Sec] Using reduction formula for sec³(x)", level: 2)
      
      # Build sec(x)
      sec_x = ExpressionNode.new(false, "sec")
      sec_x.connect(ExpressionNode.new(true, variable), "R")
      
      # Build tan(x)
      tan_x = ExpressionNode.new(false, "tan")
      tan_x.connect(ExpressionNode.new(true, variable), "R")
      
      # Build sec(x)·tan(x)
      sec_tan = ExpressionNode.new(false, "*")
      sec_tan.connect(sec_x.deep_clone, "L")
      sec_tan.connect(tan_x.deep_clone, "R")
      
      # Build sec(x)+tan(x)
      sec_plus_tan = ExpressionNode.new(false, "+")
      sec_plus_tan.connect(sec_x, "L")
      sec_plus_tan.connect(tan_x, "R")
      
      # Build |sec(x)+tan(x)|
      abs_expr = ExpressionNode.new(false, "abs")
      abs_expr.connect(sec_plus_tan, "R")
      
      # Build ln|sec(x)+tan(x)|
      ln_expr = ExpressionNode.new(false, "ln")
      ln_expr.connect(abs_expr, "R")
      
      # Build sec(x)tan(x) + ln|sec(x)+tan(x)|
      sum = ExpressionNode.new(false, "+")
      sum.connect(sec_tan, "L")
      sum.connect(ln_expr, "R")
      
      # Multiply by 1/2
      result = ExpressionNode.new(false, "*")
      result.connect(create_rational_fraction(1, 2), "L")
      result.connect(sum, "R")
      
      steps << {operation: "integration", rule: "∫sec³(x)dx = (1/2)[sec(x)tan(x) + ln|sec(x)+tan(x)|]", from: "sec³(x)", to: result.to_infix} if steps
      return result
    end
    
    ExperimentalRisch.log_debug("      [Sec] Higher sec powers (n>3) not yet implemented", level: 2)
    nil
  end
  
  # ========== QUADRATIC RADICALS ==========
  
  # Check if expression contains quadratic radicals
  def has_quadratic_radical?(node, variable)
    return false if node.nil? || node.isleaf
    
    # Check for sqrt(ax²+bx+c)
    if node.data == 'sqrt'
      radicand = node.right
      return is_quadratic?(radicand, variable)
    end
    
    # Check for 1/sqrt(ax²+bx+c)
    if node.data == '/'
      numerator = node.left
      denominator = node.right
      
      if numerator.isleaf && numerator.data == 1 && denominator.data == 'sqrt'
        radicand = denominator.right
        return is_quadratic?(radicand, variable)
      end
    end
    
    # Recursively check children
    has_quadratic_radical?(node.left, variable) || has_quadratic_radical?(node.right, variable)
  end
  
  # Check if expression is quadratic in variable
  def is_quadratic?(node, variable)
    return false if node.nil?
    
    # Simple check: x², x²+c, x²+x, or full ax²+bx+c
    # For now, just detect presence of x²
    has_variable_squared?(node, variable)
  end
  
  def has_variable_squared?(node, variable)
    return false if node.nil? || node.isleaf
    
    if node.data == '^'
      return node.left.isleaf && node.left.data == variable &&
             node.right.isleaf && node.right.data == 2
    end
    
    has_variable_squared?(node.left, variable) || has_variable_squared?(node.right, variable)
  end
  
  # Attempt integration of expressions with quadratic radicals
  def attempt_radical_integration(node, variable, steps = nil)
    puts "      [Radical] Attempting trig substitution"
    
    # Special case: 1/sqrt(quadratic)
    if node.data == '/' && node.left.isleaf && node.left.data == 1
      denominator = node.right
      if denominator.data == 'sqrt'
        return integrate_one_over_sqrt_quadratic(denominator.right, variable, steps)
      end
    end
    
    # Find the sqrt node
    sqrt_node = find_sqrt_node(node)
    return compute_integral(node, variable, steps) unless sqrt_node
    
    arg = sqrt_node.right
    
    # Detect pattern: a² - x²  →  x = a·sin(θ)
    if is_a_squared_minus_x_squared?(arg, variable)
      puts "      [Radical] Pattern: a² - x² (use x = a·sin(θ))"
      a_squared = extract_a_squared_from_difference(arg, variable)
      if a_squared
        a = Math.sqrt(a_squared.abs).to_f
        result = integrate_sqrt_a_squared_minus_x_squared(a, variable, steps)
        return result if result
      end
    end
    
    # Detect pattern: x² + a²  →  x = a·tan(θ)
    if is_x_squared_plus_a_squared?(arg, variable)
      puts "      [Radical] Pattern: x² + a² (use x = a·tan(θ))"
      a_squared = extract_a_squared_from_sum(arg, variable)
      if a_squared
        a = Math.sqrt(a_squared.abs).to_f
        result = integrate_sqrt_x_squared_plus_a_squared(a, variable, steps)
        return result if result
      end
    end
    
    # Detect pattern: x² - a²  →  x = a·sec(θ)
    if is_x_squared_minus_a_squared?(arg, variable)
      puts "      [Radical] Pattern: x² - a² (use x = a·sec(θ))"
      a_squared = extract_a_squared_from_x_squared_minus(arg, variable)
      if a_squared
        a = Math.sqrt(a_squared.abs).to_f
        result = integrate_sqrt_x_squared_minus_a_squared(a, variable, steps)
        return result if result
      end
    end
    
    puts "      [Radical] Pattern not recognized, using standard"
    compute_integral(node, variable, steps)
  end
  
  # Find sqrt node in expression tree
  def find_sqrt_node(node)
    return nil if node.nil?
    return node if !node.isleaf && node.data == 'sqrt'
    
    left_result = find_sqrt_node(node.left)
    return left_result if left_result
    
    find_sqrt_node(node.right)
  end
  
  # Check if expression is a² - x² (in various forms including normalized)
  def is_a_squared_minus_x_squared?(node, variable)
    # Form 1: a - x^2 (original)
    if node.data == '-'
      left = node.left
      right = node.right
      return true if left && right && left.constant_wrt?(variable) && is_x_squared?(right, variable)
    end

    # Form 2: (-1*x^2) + a (normalized form)
    if node.data == '+'
      left = node.left
      right = node.right
      if left && right
        return true if is_neg_x_squared_expr?(left, variable) && right.constant_wrt?(variable)
        return true if is_neg_x_squared_expr?(right, variable) && left.constant_wrt?(variable)
      end
    end

    false
  end

  # Check if node is -x^2 or (-1)*x^2
  def is_neg_x_squared_expr?(node, variable)
    return false unless node.data == '*'
    if node.left && node.left.isleaf && node.left.data.is_a?(Numeric) && node.left.data.to_f == -1.0
      return is_x_squared?(node.right, variable)
    end
    if node.right && node.right.isleaf && node.right.data.is_a?(Numeric) && node.right.data.to_f == -1.0
      return is_x_squared?(node.left, variable)
    end
    false
  end
  
  # Check if expression is x² + a²
  def is_x_squared_plus_a_squared?(node, variable)
    return false unless node.data == '+'
    
    left = node.left
    right = node.right
    
    # One should be x², the other should be constant
    (is_x_squared?(left, variable) && right.constant_wrt?(variable)) ||
    (is_x_squared?(right, variable) && left.constant_wrt?(variable))
  end
  
  # Check if expression is x² - a²
  def is_x_squared_minus_a_squared?(node, variable)
    return false unless node.data == '-'
    
    left = node.left
    right = node.right
    
    # Left should be x², right should be constant
    is_x_squared?(left, variable) && right.constant_wrt?(variable)
  end
  
  # Check if node is x²
  def is_x_squared?(node, variable)
    return false unless node.data == '^'
    node.left.isleaf && node.left.data == variable &&
    node.right.isleaf && node.right.data == 2
  end
  
  # Extract a² from (a² - x²) in various forms
  def extract_a_squared_from_difference(node, variable)
    # Form 1: a - x^2
    if node.data == '-' && node.left && node.left.isleaf && node.left.data.is_a?(Numeric)
      return node.left.data
    end

    # Form 2: (-1*x^2) + a (normalized)
    if node.data == '+'
      if node.right && node.right.constant_wrt?(variable) && node.right.isleaf && node.right.data.is_a?(Numeric)
        return node.right.data
      end
      if node.left && node.left.constant_wrt?(variable) && node.left.isleaf && node.left.data.is_a?(Numeric)
        return node.left.data
      end
    end

    nil
  end
  
  # Extract a² from (x² + a²)
  def extract_a_squared_from_sum(node, variable)
    left = node.left
    right = node.right
    
    if is_x_squared?(left, variable) && right.constant_wrt?(variable)
      return right.data if right.isleaf && right.data.is_a?(Numeric)
    elsif is_x_squared?(right, variable) && left.constant_wrt?(variable)
      return left.data if left.isleaf && left.data.is_a?(Numeric)
    end
    
    nil
  end
  
  # Extract a² from (x² - a²)
  def extract_a_squared_from_x_squared_minus(node, variable)
    return node.right.data if node.right.isleaf && node.right.data.is_a?(Numeric)
    nil
  end
  
  # Integrate 1/sqrt(ax²+bx+c) by completing the square
  # ∫1/√(x²+bx+c)dx = ln|x + b/2 + √(x²+bx+c)|
  def integrate_one_over_sqrt_quadratic(quad, variable, steps)
    puts "      [Radical] Integrating 1/√(quadratic) - completing square"
    
    # For simplicity, handle x²+bx+c where leading coeff is 1
    # Extract b and c from x²+bx+c
    if quad.data == '+'
      left = quad.left
      right = quad.right
      
      # Check if left is x² + bx or just x²
      if left.data == '+'
        # x² + bx is on left, c is on right
        x_squared_plus_bx = left
        c = right.data if right.constant_wrt?(variable)
        
        # Extract b from bx
        if x_squared_plus_bx.right.data == '*'
          b_term = x_squared_plus_bx.right
          if b_term.left.constant_wrt?(variable)
            b = b_term.left.data
          elsif b_term.right.constant_wrt?(variable)
            b = b_term.right.data
          end
        end
      elsif left.data == '^' && left.left.data == variable
        # Just x² on left, need to check right for bx+c
        b = 0
        c = right.data if right.constant_wrt?(variable)
        
        if right.data == '+'
          # bx + c
          bx_term = right.left
          c_term = right.right
          if bx_term.data == '*'
            if bx_term.left.constant_wrt?(variable)
              b = bx_term.left.data
            elsif bx_term.right.constant_wrt?(variable)
              b = bx_term.right.data
            end
          end
          c = c_term.data if c_term.constant_wrt?(variable)
        end
      end
      
      # Handle x²+(bx+c) pattern
      if left.data == '^' && left.left.data == variable && left.right.data == 2 &&
         right.data == '+'
        # Pattern: x²+(bx+c)
        x_squared = left
        bx_plus_c = right
        
        # Extract b and c
        bx_term = bx_plus_c.left
        c_term = bx_plus_c.right
        
        b_val = nil
        c_val = nil
        
        if bx_term.data == '*'
          if bx_term.left.constant_wrt?(variable) && bx_term.right.data == variable
            b_val = bx_term.left.data
          elsif bx_term.right.constant_wrt?(variable) && bx_term.left.data == variable
            b_val = bx_term.right.data
          end
        end
        
        c_val = c_term.data if c_term.constant_wrt?(variable)
        
        if b_val && c_val
          # Complete the square: x²+bx+c = (x+b/2)²+(c-b²/4)
          h = b_val / 2.0
          k = c_val - (b_val * b_val / 4.0)
          
          puts "      [Radical] Completing square: x²+#{b_val}x+#{c_val} = (x+#{h})²+#{k}"
          puts "      [Radical] ∫1/√((x+h)²+k) = ln|(x+h)+√((x+h)²+k)|"
          
          # Build (x+h)
          x_plus_h = ExpressionNode.new(false, "+")
          x_plus_h.connect(ExpressionNode.new(true, variable), "L")
          x_plus_h.connect(ExpressionNode.new(true, h), "R")
          
          # Build √(x²+bx+c) (use original)
          sqrt_orig = ExpressionNode.new(false, "sqrt")
          sqrt_orig.connect(quad.deep_clone, "R")
          
          # Build (x+h)+√(x²+bx+c)
          sum = ExpressionNode.new(false, "+")
          sum.connect(x_plus_h, "L")
          sum.connect(sqrt_orig, "R")
          
          abs_expr = ExpressionNode.new(false, "abs")
          abs_expr.connect(sum, "R")
          
          result = ExpressionNode.new(false, "ln")
          result.connect(abs_expr, "R")
          
          steps << {operation: "integration", rule: "Complete square: ∫1/√(x²+bx+c)dx = ln|(x+b/2)+√(x²+bx+c)|", from: "1/√(x²+#{b_val}x+#{c_val})", to: result.to_infix} if steps
          return result
        end
      end
      
      # Handle x²+2bx+c by completing the square: x²+2bx+c = (x+b)²+(c-b²)
      if left.data == '+' && left.left.data == '^' && left.left.left.data == variable
        # Pattern: (x²+bx)+c
        x_sq_plus_bx = left
        c_val = right.data if right.constant_wrt?(variable)
        
        # Extract b from bx
        bx_term = x_sq_plus_bx.right
        b_val = nil
        if bx_term.data == '*'
          if bx_term.left.constant_wrt?(variable) && bx_term.right.data == variable
            b_val = bx_term.left.data
          elsif bx_term.right.constant_wrt?(variable) && bx_term.left.data == variable
            b_val = bx_term.right.data
          end
        end
        
        if b_val && c_val
          # Complete the square: x²+bx+c = (x+b/2)²+(c-b²/4)
          h = b_val / 2.0
          k = c_val - (b_val * b_val / 4.0)
          
          puts "      [Radical] Completing square: x²+#{b_val}x+#{c_val} = (x+#{h})²+#{k}"
          puts "      [Radical] ∫1/√((x+h)²+k) = ln|(x+h)+√((x+h)²+k)|"
          
          # Build (x+h)
          x_plus_h = ExpressionNode.new(false, "+")
          x_plus_h.connect(ExpressionNode.new(true, variable), "L")
          x_plus_h.connect(ExpressionNode.new(true, h), "R")
          
          # Build √(x²+bx+c) (use original)
          sqrt_orig = ExpressionNode.new(false, "sqrt")
          sqrt_orig.connect(quad.deep_clone, "R")
          
          # Build (x+h)+√(x²+bx+c)
          sum = ExpressionNode.new(false, "+")
          sum.connect(x_plus_h, "L")
          sum.connect(sqrt_orig, "R")
          
          abs_expr = ExpressionNode.new(false, "abs")
          abs_expr.connect(sum, "R")
          
          result = ExpressionNode.new(false, "ln")
          result.connect(abs_expr, "R")
          
          steps << {operation: "integration", rule: "Complete square: ∫1/√(x²+bx+c)dx = ln|(x+b/2)+√(x²+bx+c)|", from: "1/√(x²+#{b_val}x+#{c_val})", to: result.to_infix} if steps
          return result
        end
      end
      
      # Simple case: x²+a² (b=0)
      if left.data == '^' && left.left.data == variable && right.constant_wrt?(variable)
        a_squared = right.data
        a = Math.sqrt(a_squared)
        puts "      [Radical] Recognized x²+#{a_squared}: ∫1/√(x²+a²) = arcsinh(x/a) = ln|x+√(x²+a²)|"
        
        # Build x + √(x²+a²)
        x_node = ExpressionNode.new(true, variable)
        
        x_squared = ExpressionNode.new(false, "^")
        x_squared.connect(ExpressionNode.new(true, variable), "L")
        x_squared.connect(ExpressionNode.new(true, 2), "R")
        
        x_sq_plus_a_sq = ExpressionNode.new(false, "+")
        x_sq_plus_a_sq.connect(x_squared, "L")
        x_sq_plus_a_sq.connect(ExpressionNode.new(true, a_squared), "R")
        
        sqrt_expr = ExpressionNode.new(false, "sqrt")
        sqrt_expr.connect(x_sq_plus_a_sq, "R")
        
        x_plus_sqrt = ExpressionNode.new(false, "+")
        x_plus_sqrt.connect(x_node, "L")
        x_plus_sqrt.connect(sqrt_expr, "R")
        
        abs_expr = ExpressionNode.new(false, "abs")
        abs_expr.connect(x_plus_sqrt, "R")
        
        result = ExpressionNode.new(false, "ln")
        result.connect(abs_expr, "R")
        
        steps << {operation: "integration", rule: "∫1/√(x²+a²)dx = ln|x+√(x²+a²)|", from: "1/√(x²+#{a_squared})", to: result.to_infix} if steps
        return result
      end
    end
    
    puts "      [Radical] Complex quadratic - not yet implemented"
    compute_integral(ExpressionNode.new(false, "/").tap { |n|
      n.connect(ExpressionNode.new(true, 1), "L")
      sqrt_node = ExpressionNode.new(false, "sqrt")
      sqrt_node.connect(quad, "R")
      n.connect(sqrt_node, "R")
    }, variable, steps)
  end
  
  # ∫√(a² - x²) dx = (x/2)√(a²-x²) + (a²/2)arcsin(x/a)
  def integrate_sqrt_a_squared_minus_x_squared(a, variable, steps)
    puts "      [Radical] Building result for ∫√(a²-x²)dx"
    
    # Build x
    x_node = ExpressionNode.new(true, variable)
    
    # Build √(a²-x²)
    a_squared = ExpressionNode.new(true, a * a)
    
    x_squared = ExpressionNode.new(false, "^")
    x_squared.connect(ExpressionNode.new(true, variable), "L")
    x_squared.connect(ExpressionNode.new(true, 2), "R")
    
    a_sq_minus_x_sq = ExpressionNode.new(false, "-")
    a_sq_minus_x_sq.connect(a_squared, "L")
    a_sq_minus_x_sq.connect(x_squared, "R")
    
    sqrt_expr = ExpressionNode.new(false, "sqrt")
    sqrt_expr.connect(a_sq_minus_x_sq, "R")
    
    # Build (x/2)√(a²-x²)
    term1 = ExpressionNode.new(false, "*")
    term1.connect(x_node.deep_clone, "L")
    term1.connect(sqrt_expr, "R")
    
    term1_half = ExpressionNode.new(false, "*")
    term1_half.connect(create_rational_fraction(1, 2), "L")
    term1_half.connect(term1, "R")
    
    # Build arcsin(x/a)
    x_over_a = ExpressionNode.new(false, "/")
    x_over_a.connect(ExpressionNode.new(true, variable), "L")
    x_over_a.connect(ExpressionNode.new(true, a), "R")
    
    arcsin_expr = ExpressionNode.new(false, "arcsin")
    arcsin_expr.connect(x_over_a, "R")
    
    # Build (a²/2)arcsin(x/a)
    term2 = ExpressionNode.new(false, "*")
    term2.connect(create_rational_fraction(a * a, 2), "L")
    term2.connect(arcsin_expr, "R")
    
    # Combine: (x/2)√(a²-x²) + (a²/2)arcsin(x/a)
    result = ExpressionNode.new(false, "+")
    result.connect(term1_half, "L")
    result.connect(term2, "R")
    
    if steps
      steps << {
        operation: "integration",
        rule: "Trig Substitution: ∫√(a²-x²)dx = (x/2)√(a²-x²) + (a²/2)arcsin(x/a)",
        from: "√(#{a}²-x²)",
        to: result.to_infix
      }
    end
    
    result
  end
  
  # ∫√(x² + a²) dx = (x/2)√(x²+a²) + (a²/2)ln|x + √(x²+a²)|
  def integrate_sqrt_x_squared_plus_a_squared(a, variable, steps)
    puts "      [Radical] Building result for ∫√(x²+a²)dx"
    
    # Build √(x²+a²)
    x_squared = ExpressionNode.new(false, "^")
    x_squared.connect(ExpressionNode.new(true, variable), "L")
    x_squared.connect(ExpressionNode.new(true, 2), "R")
    
    a_squared = ExpressionNode.new(true, a * a)
    
    x_sq_plus_a_sq = ExpressionNode.new(false, "+")
    x_sq_plus_a_sq.connect(x_squared, "L")
    x_sq_plus_a_sq.connect(a_squared, "R")
    
    sqrt_expr = ExpressionNode.new(false, "sqrt")
    sqrt_expr.connect(x_sq_plus_a_sq, "R")
    
    # Build (x/2)√(x²+a²)
    term1 = ExpressionNode.new(false, "*")
