    term1_half = ExpressionNode.new(false, "*")
    term1_half.connect(create_rational_fraction(1, 2), "L")
    term1_half.connect(term1, "R")
    
    # Build ln|x + √(x²+a²)|
    x_plus_sqrt = ExpressionNode.new(false, "+")
    x_plus_sqrt.connect(ExpressionNode.new(true, variable), "L")
    x_plus_sqrt.connect(sqrt_expr, "R")
    
    abs_expr = ExpressionNode.new(false, "abs")
    abs_expr.connect(x_plus_sqrt, "R")
    
    ln_expr = ExpressionNode.new(false, "ln")
    ln_expr.connect(abs_expr, "R")
    
    # Build (a²/2)ln|x + √(x²+a²)|
    term2 = ExpressionNode.new(false, "*")
    term2.connect(create_rational_fraction(a * a, 2), "L")
    term2.connect(ln_expr, "R")
    
    # Combine
    result = ExpressionNode.new(false, "+")
    result.connect(term1_half, "L")
    result.connect(term2, "R")
    
    if steps
      steps << {
        operation: "integration",
        rule: "Trig Substitution: ∫√(x²+a²)dx = (x/2)√(x²+a²) + (a²/2)ln|x+√(x²+a²)|",
        from: "√(x²+#{a}²)",
        to: result.to_infix
      }
    end
    
    result
  end
  
  # ∫√(x² - a²) dx = (x/2)√(x²-a²) - (a²/2)ln|x + √(x²-a²)|
  def integrate_sqrt_x_squared_minus_a_squared(a, variable, steps)
    puts "      [Radical] Building result for ∫√(x²-a²)dx"
    
    # Build √(x²-a²)
    x_squared = ExpressionNode.new(false, "^")
    x_squared.connect(ExpressionNode.new(true, variable), "L")
    x_squared.connect(ExpressionNode.new(true, 2), "R")
    
    a_squared = ExpressionNode.new(true, a * a)
    
    x_sq_minus_a_sq = ExpressionNode.new(false, "-")
    x_sq_minus_a_sq.connect(x_squared, "L")
    x_sq_minus_a_sq.connect(a_squared, "R")
    
    sqrt_expr = ExpressionNode.new(false, "sqrt")
    sqrt_expr.connect(x_sq_minus_a_sq, "R")
    
    # Build (x/2)√(x²-a²)
    term1 = ExpressionNode.new(false, "*")
    term1.connect(ExpressionNode.new(true, variable), "L")
    term1.connect(sqrt_expr.deep_clone, "R")
    
    term1_half = ExpressionNode.new(false, "*")
    term1_half.connect(create_rational_fraction(1, 2), "L")
    term1_half.connect(term1, "R")
    
    # Build ln|x + √(x²-a²)|
    x_plus_sqrt = ExpressionNode.new(false, "+")
    x_plus_sqrt.connect(ExpressionNode.new(true, variable), "L")
    x_plus_sqrt.connect(sqrt_expr, "R")
    
    abs_expr = ExpressionNode.new(false, "abs")
    abs_expr.connect(x_plus_sqrt, "R")
    
    ln_expr = ExpressionNode.new(false, "ln")
    ln_expr.connect(abs_expr, "R")
    
    # Build -(a²/2)ln|x + √(x²-a²)|
    term2 = ExpressionNode.new(false, "*")
    term2.connect(create_rational_fraction(a * a, 2), "L")
    term2.connect(ln_expr, "R")
    
    # Negate term2
    neg_term2 = ExpressionNode.new(false, "*")
    neg_term2.connect(ExpressionNode.new(true, -1), "L")
    neg_term2.connect(term2, "R")
    
    # Combine
    result = ExpressionNode.new(false, "+")
    result.connect(term1_half, "L")
    result.connect(neg_term2, "R")
    
    if steps
      steps << {
        operation: "integration",
        rule: "Trig Substitution: ∫√(x²-a²)dx = (x/2)√(x²-a²) - (a²/2)ln|x+√(x²-a²)|",
        from: "√(x²-#{a}²)",
        to: result.to_infix
      }
    end
    
    result
  end
  
  # ========== SMART SUBSTITUTION ==========
  
  # Check if smart substitution might work
  def can_apply_smart_substitution?(node, variable)
    return false unless node.data == '*'
    
    left = node.left
    right = node.right
    
    # Pattern 1: x * exp(x²) - x is derivative of x²
    # Pattern 2: sin(x) * exp(cos(x)) - sin(x) is -d/dx[cos(x)]
    # Pattern 3: sin(ax) * cos(bx) - product-to-sum
    # Pattern 4: sin(ax) * sin(bx) - product-to-sum
    
    # Check if one side is x and other is exp(x^n)
    if left.isleaf && left.data == variable && right.data == 'exp'
      inner = right.right
      if inner.data == '^' && inner.left.isleaf && inner.left.data == variable
        return true
      end
    elsif right.isleaf && right.data == variable && left.data == 'exp'
      inner = left.right
      if inner.data == '^' && inner.left.isleaf && inner.left.data == variable
        return true
      end
    end
    
    # Check for x * sqrt(x²+a) or x * sqrt(x²-a)
    if left.isleaf && left.data == variable && right.data == 'sqrt'
      inner = right.right
      if inner.data == '+' || inner.data == '-'
        # Check if one term is x²
        if (inner.left.data == '^' && inner.left.left.data == variable && inner.left.right.data == 2) ||
           (inner.right.data == '^' && inner.right.left.data == variable && inner.right.right.data == 2)
          return true
        end
      end
    elsif right.isleaf && right.data == variable && left.data == 'sqrt'
      inner = left.right
      if inner.data == '+' || inner.data == '-'
        if (inner.left.data == '^' && inner.left.left.data == variable && inner.left.right.data == 2) ||
           (inner.right.data == '^' && inner.right.left.data == variable && inner.right.right.data == 2)
          return true
        end
      end
    end
    
    # Check if one side is sin(x) and other is exp(cos(x))
    if left.data == 'sin' && right.data == 'exp'
      if right.right.data == 'cos'
        return true
      end
    elsif right.data == 'sin' && left.data == 'exp'
      if left.right.data == 'cos'
        return true
      end
    end
    
    # Check for trig product: sin * cos or sin * sin
    if (left.data == 'sin' && right.data == 'cos') || 
       (left.data == 'cos' && right.data == 'sin') ||
       (left.data == 'sin' && right.data == 'sin')
      return true
    end
    
    false
  end
  
  # Attempt smart substitution
  # ∫x·e^(x²)dx = (1/2)e^(x²)
  # ∫sin(x)·e^(cos(x))dx = -e^(cos(x))
  def attempt_smart_substitution(node, variable, steps = nil)
    left = node.left
    right = node.right
    
    # Pattern: x * exp(x²)
    if left.isleaf && left.data == variable && right.data == 'exp'
      inner = right.right
      if inner.data == '^' && inner.left.isleaf && inner.left.data == variable
        n = inner.right.data
        puts "      [Smart Sub] ∫x·e^(x^#{n})dx = (1/#{n})e^(x^#{n})"
        
        # Build result: (1/n)·e^(x^n)
        result = ExpressionNode.new(false, "*")
        result.connect(create_rational_fraction(1, n), "L")
        result.connect(right.deep_clone, "R")
        
        steps << {operation: "integration", rule: "U-substitution: u=x^#{n}, du=#{n}x dx", from: node.to_infix, to: result.to_infix} if steps
        return result
      end
    elsif right.isleaf && right.data == variable && left.data == 'exp'
      inner = left.right
      if inner.data == '^' && inner.left.isleaf && inner.left.data == variable
        n = inner.right.data
        puts "      [Smart Sub] ∫x·e^(x^#{n})dx = (1/#{n})e^(x^#{n})"
        
        # Build result: (1/n)·e^(x^n)
        result = ExpressionNode.new(false, "*")
        result.connect(create_rational_fraction(1, n), "L")
        result.connect(left.deep_clone, "R")
        
        steps << {operation: "integration", rule: "U-substitution: u=x^#{n}, du=#{n}x dx", from: node.to_infix, to: result.to_infix} if steps
        return result
      end
    end
    
    # Pattern: sin(x) * exp(cos(x))
    if left.data == 'sin' && right.data == 'exp'
      if right.right.data == 'cos'
        puts "      [Smart Sub] ∫sin(x)·e^(cos(x))dx = -e^(cos(x))"
        
        # Build result: -e^(cos(x))
        result = ExpressionNode.new(false, "*")
        result.connect(ExpressionNode.new(true, -1), "L")
        result.connect(right.deep_clone, "R")
        
        steps << {operation: "integration", rule: "U-substitution: u=cos(x), du=-sin(x)dx", from: node.to_infix, to: result.to_infix} if steps
        return result
      end
    elsif right.data == 'sin' && left.data == 'exp'
      if left.right.data == 'cos'
        puts "      [Smart Sub] ∫sin(x)·e^(cos(x))dx = -e^(cos(x))"
        
        # Build result: -e^(cos(x))
        result = ExpressionNode.new(false, "*")
        result.connect(ExpressionNode.new(true, -1), "L")
        result.connect(left.deep_clone, "R")
        
        steps << {operation: "integration", rule: "U-substitution: u=cos(x), du=-sin(x)dx", from: node.to_infix, to: result.to_infix} if steps
        return result
      end
    end
    
    # Pattern: x * sqrt(x²±a) - u-substitution with u = x²±a
    if (left.isleaf && left.data == variable && right.data == 'sqrt') ||
       (right.isleaf && right.data == variable && left.data == 'sqrt')
      sqrt_node = right.data == 'sqrt' ? right : left
      inner = sqrt_node.right
      
      if inner.data == '+' || inner.data == '-'
        # Extract x² and constant
        x_sq = nil
        constant = nil
        
        if inner.left.data == '^' && inner.left.left.data == variable && inner.left.right.data == 2
          x_sq = inner.left
          constant = inner.right.data if inner.right.constant_wrt?(variable)
        elsif inner.right.data == '^' && inner.right.left.data == variable && inner.right.right.data == 2
          x_sq = inner.right
          constant = inner.left.data if inner.left.constant_wrt?(variable)
        end
        
        if x_sq && constant
          # ∫x·√(x²±a) = (1/3)(x²±a)^(3/2)
          puts "      [Smart Sub] ∫x·√(x²±a)dx = (1/3)(x²±a)^(3/2)"
          
          # Build (x²±a)^(3/2)
          power_node = ExpressionNode.new(false, "^")
          power_node.connect(inner.deep_clone, "L")
          power_node.connect(create_rational_fraction(3, 2), "R")
          
          # Build (1/3) * (x²±a)^(3/2)
          result = ExpressionNode.new(false, "*")
          result.connect(create_rational_fraction(1, 3), "L")
          result.connect(power_node, "R")
          
          steps << {operation: "integration", rule: "U-substitution: u=x²±a, x·√(x²±a) = (1/3)(x²±a)^(3/2)", from: node.to_infix, to: result.to_infix} if steps
          return result
        end
      end
    end
    
    # Pattern: trig products (product-to-sum formulas)
    # ∫sin(ax)cos(bx)dx or ∫sin(ax)sin(bx)dx
    if (left.data == 'sin' && right.data == 'cos') || 
       (left.data == 'cos' && right.data == 'sin') ||
       (left.data == 'sin' && right.data == 'sin')
      return integrate_trig_product(node, variable, steps)
    end
    
    compute_integral(node, variable, steps)
  end
  
  # Integrate trig products using product-to-sum formulas
  # ∫sin(ax)cos(bx)dx = -cos((a+b)x)/(2(a+b)) - cos((a-b)x)/(2(a-b))
  # ∫sin(ax)sin(bx)dx = sin((a-b)x)/(2(a-b)) - sin((a+b)x)/(2(a+b))
  def integrate_trig_product(node, variable, steps)
    left = node.left
    right = node.right
    
    # Extract coefficients from sin(ax) or cos(bx)
    a = extract_trig_coeff(left, variable)
    b = extract_trig_coeff(right, variable)
    
    return compute_integral(node, variable, steps) unless a && b
    
    if left.data == 'sin' && right.data == 'cos'
      # ∫sin(ax)cos(bx) = -cos((a+b)x)/(2(a+b)) - cos((a-b)x)/(2(a-b))
      puts "      [Product-Sum] ∫sin(#{a}x)cos(#{b}x)dx"
      
      sum_val = a + b
      diff_val = a - b
      
      # Build -cos((a+b)x)/(2(a+b))
      term1 = build_cos_term(sum_val, variable, -1.0 / (2 * sum_val))
      
      # Build -cos((a-b)x)/(2(a-b)) 
      term2 = build_cos_term(diff_val, variable, -1.0 / (2 * diff_val)) if diff_val != 0
      
      if diff_val == 0
        result = term1
      else
        result = ExpressionNode.new(false, "-")
        result.connect(term1, "L")
        result.connect(term2, "R")
      end
      
      steps << {operation: "integration", rule: "Product-to-sum: sin(ax)cos(bx)", from: node.to_infix, to: result.to_infix} if steps
      return result
      
    elsif left.data == 'sin' && right.data == 'sin'
      # ∫sin(ax)sin(bx) = sin((a-b)x)/(2(a-b)) - sin((a+b)x)/(2(a+b))
      puts "      [Product-Sum] ∫sin(#{a}x)sin(#{b}x)dx"
      
      sum_val = a + b
      diff_val = a - b
      
      if diff_val == 0
        # Special case: sin²(ax) - already handled by trig powers
        return compute_integral(node, variable, steps)
      end
      
      # Build sin((a-b)x)/(2(a-b))
      term1 = build_sin_term(diff_val, variable, 1.0 / (2 * diff_val))
      
      # Build sin((a+b)x)/(2(a+b))
      term2 = build_sin_term(sum_val, variable, 1.0 / (2 * sum_val))
      
      result = ExpressionNode.new(false, "-")
      result.connect(term1, "L")
      result.connect(term2, "R")
      
      steps << {operation: "integration", rule: "Product-to-sum: sin(ax)sin(bx)", from: node.to_infix, to: result.to_infix} if steps
      return result
    end
    
    compute_integral(node, variable, steps)
  end
  
  # Extract coefficient from sin(ax) or cos(ax)
  def extract_trig_coeff(node, variable)
    return nil unless node.right
    
    inner = node.right
    
    # Case 1: sin(x) or cos(x) - coefficient is 1
    if inner.isleaf && inner.data == variable
      return 1
    end
    
    # Case 2: sin(ax) or cos(ax) where inner is a*x
    if inner.data == '*'
      if inner.left.constant_wrt?(variable) && inner.right.isleaf && inner.right.data == variable
        return inner.left.data
      elsif inner.right.constant_wrt?(variable) && inner.left.isleaf && inner.left.data == variable
        return inner.right.data
      end
    end
    
    nil
  end
  
  # Build cos(ax)/b term
  def build_cos_term(a, variable, coeff)
    # Build ax
    ax = ExpressionNode.new(false, "*")
    ax.connect(ExpressionNode.new(true, a), "L")
    ax.connect(ExpressionNode.new(true, variable), "R")
    
    # Build cos(ax)
    cos_ax = ExpressionNode.new(false, "cos")
    cos_ax.connect(ax, "R")
    
    # Build coeff * cos(ax)
    result = ExpressionNode.new(false, "*")
    result.connect(ExpressionNode.new(true, coeff), "L")
    result.connect(cos_ax, "R")
    
    result
  end
  
  # Build sin(ax)/b term
  def build_sin_term(a, variable, coeff)
    # Build ax
    ax = ExpressionNode.new(false, "*")
    ax.connect(ExpressionNode.new(true, a), "L")
    ax.connect(ExpressionNode.new(true, variable), "R")
    
    # Build sin(ax)
    sin_ax = ExpressionNode.new(false, "sin")
    sin_ax.connect(ax, "R")
    
    # Build coeff * sin(ax)
    result = ExpressionNode.new(false, "*")
    result.connect(ExpressionNode.new(true, coeff), "L")
    result.connect(sin_ax, "R")
    
    result
  end
end


# ===== vector_calculus.rb =====
# Vector Calculus Operations - Gradient, Curl, Divergence, etc.
# Provides multivariable calculus capabilities

module VectorCalculus
  # Compute gradient of a scalar field
  # Returns a vector of partial derivatives
  def gradient(variables, track_steps: false)
    steps = [] if track_steps
    components = []
    
    variables.each do |var|
      deriv = derivative(var, track_steps: false)
      components << deriv
      steps << {operation: "gradient", variable: var, component: deriv.to_readable_string} if track_steps
    end
    
    {
      type: "gradient",
      variables: variables,
      components: components,
      steps: steps
    }
  end
  
  # Compute divergence of a vector field
  # Input: array of expressions (vector components)
  # Returns: scalar expression (sum of partial derivatives)
  def self.divergence(vector_components, variables, track_steps: false)
    steps = [] if track_steps
    
    unless vector_components.length == variables.length
      raise ArgumentError, "Number of components must match number of variables"
    end
    
    # Compute ∂F₁/∂x₁ + ∂F₂/∂x₂ + ...
    divergence_terms = []
    
    vector_components.each_with_index do |component, idx|
      var = variables[idx]
      partial = component.derivative(var, track_steps: false)
      divergence_terms << partial
      
      steps << {
        operation: "divergence",
        component: idx + 1,
        variable: var,
        partial_derivative: partial.to_readable_string
      } if track_steps
    end
    
    # Sum all terms
    result = divergence_terms[0]
    divergence_terms[1..-1].each do |term|
      sum_expr = result.class.new("", result.instance_variable_get(:@variables))
      sum_node = ExpressionNode.new(false, "+")
      sum_node.connect(result.root.deep_clone, "L")
      sum_node.connect(term.root.deep_clone, "R")
      sum_expr.root = sum_node
      result = sum_expr
    end
    
    result.steps = steps if track_steps
    result
  end
  
  # Compute curl of a vector field (3D only)
  # Input: array of 3 expressions [F₁, F₂, F₃]
  # Variables: [x, y, z]
  # Returns: vector with 3 components
  def self.curl(vector_components, variables, track_steps: false)
    steps = [] if track_steps
    
    unless vector_components.length == 3 && variables.length == 3
      raise ArgumentError, "Curl requires 3D vector field (3 components, 3 variables)"
    end
    
    f1, f2, f3 = vector_components
    x, y, z = variables
    
    # Curl = (∂F₃/∂y - ∂F₂/∂z, ∂F₁/∂z - ∂F₃/∂x, ∂F₂/∂x - ∂F₁/∂y)
    
    # Component 1: ∂F₃/∂y - ∂F₂/∂z
    df3_dy = f3.derivative(y, track_steps: false)
    df2_dz = f2.derivative(z, track_steps: false)
    
    comp1_expr = f1.class.new("", f1.instance_variable_get(:@variables))
    comp1_node = ExpressionNode.new(false, "-")
    comp1_node.connect(df3_dy.root.deep_clone, "L")
    comp1_node.connect(df2_dz.root.deep_clone, "R")
    comp1_expr.root = comp1_node
    
    steps << {operation: "curl", component: 1, formula: "∂F₃/∂y - ∂F₂/∂z", result: comp1_expr.to_readable_string} if track_steps
    
    # Component 2: ∂F₁/∂z - ∂F₃/∂x
    df1_dz = f1.derivative(z, track_steps: false)
    df3_dx = f3.derivative(x, track_steps: false)
    
    comp2_expr = f1.class.new("", f1.instance_variable_get(:@variables))
    comp2_node = ExpressionNode.new(false, "-")
    comp2_node.connect(df1_dz.root.deep_clone, "L")
    comp2_node.connect(df3_dx.root.deep_clone, "R")
    comp2_expr.root = comp2_node
    
    steps << {operation: "curl", component: 2, formula: "∂F₁/∂z - ∂F₃/∂x", result: comp2_expr.to_readable_string} if track_steps
    
    # Component 3: ∂F₂/∂x - ∂F₁/∂y
    df2_dx = f2.derivative(x, track_steps: false)
    df1_dy = f1.derivative(y, track_steps: false)
    
    comp3_expr = f1.class.new("", f1.instance_variable_get(:@variables))
    comp3_node = ExpressionNode.new(false, "-")
    comp3_node.connect(df2_dx.root.deep_clone, "L")
    comp3_node.connect(df1_dy.root.deep_clone, "R")
    comp3_expr.root = comp3_node
    
    steps << {operation: "curl", component: 3, formula: "∂F₂/∂x - ∂F₁/∂y", result: comp3_expr.to_readable_string} if track_steps
    
    {
      type: "curl",
      variables: variables,
      components: [comp1_expr, comp2_expr, comp3_expr],
      steps: steps
    }
  end
  
  # Compute Laplacian (∇²f = ∂²f/∂x² + ∂²f/∂y² + ...)
  def laplacian(variables, track_steps: false)
    steps = [] if track_steps
    second_derivatives = []
    
    variables.each do |var|
      # Compute ∂²f/∂var²
      first_deriv = derivative(var, track_steps: false)
      second_deriv = first_deriv.derivative(var, track_steps: false)
      second_derivatives << second_deriv
      
      steps << {
        operation: "laplacian",
        variable: var,
        second_derivative: second_deriv.to_readable_string
      } if track_steps
    end
    
    # Sum all second derivatives
    result = second_derivatives[0]
    second_derivatives[1..-1].each do |term|
      sum_expr = result.class.new("", @variables)
      sum_node = ExpressionNode.new(false, "+")
      sum_node.connect(result.root.deep_clone, "L")
      sum_node.connect(term.root.deep_clone, "R")
      sum_expr.root = sum_node
      result = sum_expr
    end
    
    result.steps = steps if track_steps
    result
  end
  
  # Compute directional derivative in direction of vector v
  # ∇f · v = (∂f/∂x₁)v₁ + (∂f/∂x₂)v₂ + ...
  def directional_derivative(variables, direction_vector, track_steps: false)
    steps = [] if track_steps
    
    unless variables.length == direction_vector.length
      raise ArgumentError, "Direction vector dimension must match number of variables"
    end
    
    # Compute gradient first
    grad = gradient(variables, track_steps: false)
    
    # Dot product with direction vector
    terms = []
    grad[:components].each_with_index do |component, idx|
      # (∂f/∂xᵢ) * vᵢ
      term_expr = component.class.new("", @variables)
      term_node = ExpressionNode.new(false, "*")
      term_node.connect(component.root.deep_clone, "L")
      term_node.connect(ExpressionNode.new(true, direction_vector[idx]), "R")
      term_expr.root = term_node
      terms << term_expr
      
      steps << {
        operation: "directional_derivative",
        variable: variables[idx],
        direction_component: direction_vector[idx],
        term: term_expr.to_readable_string
      } if track_steps
    end
    
    # Sum all terms
    result = terms[0]
    terms[1..-1].each do |term|
      sum_expr = result.class.new("", @variables)
      sum_node = ExpressionNode.new(false, "+")
      sum_node.connect(result.root.deep_clone, "L")
      sum_node.connect(term.root.deep_clone, "R")
      sum_expr.root = sum_node
      result = sum_expr
    end
    
    result.steps = steps if track_steps
    result
  end
  
  # Compute differential form: df = (∂f/∂x)dx + (∂f/∂y)dy + ...
  def differential_form(variables, track_steps: false)
    steps = [] if track_steps
    terms = []
    
    variables.each do |var|
      partial = derivative(var, track_steps: false)
      terms << {
        coefficient: partial,
        differential: "d#{var}"
      }
      
      steps << {
        operation: "differential",
        variable: var,
        partial_derivative: partial.to_readable_string,
        term: "(#{partial.to_readable_string})d#{var}"
      } if track_steps
    end
    
    {
      type: "differential_form",
      variables: variables,
      terms: terms,
      steps: steps,
      to_string: terms.map { |t| "(#{t[:coefficient].to_readable_string})#{t[:differential]}" }.join(" + ")
    }
  end
end


# ===== simplification.rb =====
# Simplification Engine - Experimental improved version
# Provides algebraic simplification with step tracking

module Simplification
  attr_accessor :use_experimental_simplification
  
  def initialize_simplification
    @use_experimental_simplification = false
  end
  
  # Simplify the expression
  def simplify(track_steps: false, max_iterations: 30)
    puts "\n========================================="
    puts "STARTING SIMPLIFICATION"
    puts "Expression: #{@root.to_infix}"
    puts "Mode: #{@use_experimental_simplification ? 'Experimental' : 'Standard'}"
    puts "=========================================\n"
    
    steps = [] if track_steps
    iteration = 0
    changed = true
    last_expr = @root.to_infix
    
    while changed && iteration < max_iterations
      iteration += 1
      current_expr = @root.to_infix
      
      puts "  [Iteration #{iteration}] Current: #{current_expr}"
      
      if @use_experimental_simplification
        changed = experimental_simplify_pass(@root, steps)
      else
        changed = standard_simplify_pass(@root, steps)
      end
      
      new_expr = @root.to_infix
      
      # Detect infinite loop: if expression is same as 2 iterations ago
      if new_expr == last_expr && changed
        puts "  ⚠️  WARNING: Expression unchanged, stopping to prevent infinite loop"
        changed = false
      end
      
      if changed
        puts "  [Iteration #{iteration}] → #{new_expr} ✓"
      else
        puts "  [Iteration #{iteration}] No changes, done."
      end
      
      last_expr = current_expr
      
      if track_steps && changed
        steps << {iteration: iteration, changed: changed, current: @root.to_infix}
      end
    end
    
    if iteration >= max_iterations
      puts "\n  ⚠️  Reached max iterations (#{max_iterations}), stopping."
    end
    
    puts "\nFINAL RESULT: #{@root.to_infix}"
    puts "=" * 70
    
    @steps = steps if track_steps
    self
  end
  
  private
  
  # Standard simplification (original approach)
  def standard_simplify_pass(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively simplify children first
    changed |= standard_simplify_pass(node.left, steps) if node.left
    changed |= standard_simplify_pass(node.right, steps) if node.right
    
    # Apply simplification rules
    case node.data
    when '+'
      # 0 + x = x
      if node.left && node.left.isleaf && node.left.data == 0
        replace_node_with(node, node.right)
        steps << {rule: "0 + x = x", simplified: true} if steps
        changed = true
      # x + 0 = x
      elsif node.right && node.right.isleaf && node.right.data == 0
        replace_node_with(node, node.left)
        steps << {rule: "x + 0 = x", simplified: true} if steps
        changed = true
      # Constant folding: a + b = c
      elsif node.left && node.right && node.left.isleaf && node.right.isleaf &&
            node.left.data.is_a?(Numeric) && node.right.data.is_a?(Numeric)
        left_val = node.left.data
        right_val = node.right.data
        result = left_val + right_val
        node.data = result
        node.isleaf = true
        node.left = nil
        node.right = nil
        steps << {rule: "constant folding: #{left_val} + #{right_val} = #{result}", simplified: true} if steps
        changed = true
      end
      
    when '-'
      # x - 0 = x
      if node.right && node.right.isleaf && node.right.data == 0
        replace_node_with(node, node.left)
        steps << {rule: "x - 0 = x", simplified: true} if steps
        changed = true
      # 0 - x = -x
      elsif node.left && node.left.isleaf && node.left.data == 0
        mult_node = ExpressionNode.new(false, "*")
        mult_node.connect(ExpressionNode.new(true, -1), "L")
        mult_node.connect(node.right.deep_clone, "R")
        replace_node_with(node, mult_node)
        steps << {rule: "0 - x = -x", simplified: true} if steps
        changed = true
      # (a + c) - c = a (cancel constant on right)
      elsif node.left && node.left.data == '+' && node.right && 
            node.right.isleaf && node.right.data.is_a?(Numeric)
        # Check if left side is (something + c) where c matches the right side
        if node.left.right && node.left.right.isleaf && 
           node.left.right.data.is_a?(Numeric) && 
           node.left.right.data == node.right.data
          # (a + c) - c = a
          replace_node_with(node, node.left.left)
          steps << {operation: "simplification", rule: "(a + c) - c = a", from: node.to_infix, to: node.to_infix} if steps
          changed = true
        elsif node.left.left && node.left.left.isleaf && 
              node.left.left.data.is_a?(Numeric) && 
              node.left.left.data == node.right.data
          # (c + a) - c = a
          replace_node_with(node, node.left.right)
          steps << {operation: "simplification", rule: "(c + a) - c = a", from: node.to_infix, to: node.to_infix} if steps
          changed = true
        # Handle nested: ((a + b) + c) - c = (a + b)
        elsif node.left.right && node.left.right.isleaf && 
              node.left.right.data.is_a?(Numeric) && 
              node.right.isleaf && node.right.data.is_a?(Numeric) &&
              node.left.right.data == node.right.data &&
              node.left.left && node.left.left.data == '+'
          # ((a + b) + c) - c = (a + b)
          replace_node_with(node, node.left.left)
          steps << {operation: "simplification", rule: "((a + b) + c) - c = (a + b)", from: node.to_infix, to: node.to_infix} if steps
          changed = true
        end
      end
      # Constant folding for subtraction.
      # The `node.data == '-'` guard is load-bearing. Unlike the '+' and '*' arms,
      # this fold sits OUTSIDE the elsif chain above, so it also runs after a rule
      # has already rewritten this very node. The "0 - x = -x" rule rewrites it in
      # place into (-1) * x, and for numeric x that leaves two fresh numeric leaves
      # under a '*' — which this block would then fold with a MINUS, turning
      # 0 - 1 into -2. Fold only while the node is still a subtraction.
      if node.data == '-' && node.left && node.right &&
         node.left.isleaf && node.right.isleaf &&
            node.left.data.is_a?(Numeric) && node.right.data.is_a?(Numeric)
        # Save values before setting to nil
        left_val = node.left.data
        right_val = node.right.data
        result = left_val - right_val
        node.data = result
        node.isleaf = true
        node.left = nil
        node.right = nil
        steps << {rule: "constant folding: #{left_val} - #{right_val} = #{result}", simplified: true} if steps
        changed = true
      end
      
    when '*'
      # 0 * x = 0 or x * 0 = 0
      if (node.left && node.left.isleaf && node.left.data == 0) ||
         (node.right && node.right.isleaf && node.right.data == 0)
        node.data = 0
        node.isleaf = true
        node.left = nil
        node.right = nil
        steps << {rule: "x * 0 = 0", simplified: true} if steps
        changed = true
      # 1 * x = x
      elsif node.left && node.left.isleaf && node.left.data == 1
        replace_node_with(node, node.right)
        steps << {rule: "1 * x = x", simplified: true} if steps
        changed = true
      # x * 1 = x
      elsif node.right && node.right.isleaf && node.right.data == 1
        replace_node_with(node, node.left)
        steps << {rule: "x * 1 = x", simplified: true} if steps
        changed = true
      # -1 * x = -x (keep as multiplication for now)
      # Constant folding: a * b = c
      elsif node.left && node.right && node.left.isleaf && node.right.isleaf &&
            node.left.data.is_a?(Numeric) && node.right.data.is_a?(Numeric)
        result = node.left.data * node.right.data
        node.data = result == result.to_i ? result.to_i : result
        node.isleaf = true
        node.left = nil
        node.right = nil
        steps << {rule: "constant folding: multiplication", simplified: true} if steps
        changed = true
      # Constant folding: (a/b) * c = (a*c)/b or simplify fully
      elsif node.left && node.right && !node.left.isleaf && node.left.data == '/' &&
            node.left.left && node.left.left.isleaf && node.left.left.data.is_a?(Numeric) &&
            node.left.right && node.left.right.isleaf && node.left.right.data.is_a?(Numeric) &&
            node.right.isleaf && node.right.data.is_a?(Numeric)
        a = node.left.left.data.to_f
        b = node.left.right.data.to_f
        c = node.right.data.to_f
        result = (a * c) / b
        if result == result.to_i
          node.data = result.to_i
          node.isleaf = true
          node.left = nil
          node.right = nil
          changed = true
        end
      # Constant folding: c * (a/b) = (c*a)/b
      elsif node.right && node.left && !node.right.isleaf && node.right.data == '/' &&
            node.right.left && node.right.left.isleaf && node.right.left.data.is_a?(Numeric) &&
            node.right.right && node.right.right.isleaf && node.right.right.data.is_a?(Numeric) &&
            node.left.isleaf && node.left.data.is_a?(Numeric)
        c = node.left.data.to_f
        a = node.right.left.data.to_f
        b = node.right.right.data.to_f
        result = (c * a) / b
        if result == result.to_i
          node.data = result.to_i
          node.isleaf = true
          node.left = nil
          node.right = nil
          changed = true
        end
      end
      
    when '/'
      # x / 1 = x
      if node.right && node.right.isleaf && node.right.data == 1
        replace_node_with(node, node.left)
        steps << {rule: "x / 1 = x", simplified: true} if steps
        changed = true
      # x / x = 1 (for matching expressions)
      elsif node.left && node.right && nodes_equal?(node.left, node.right)
        node.data = 1
        node.isleaf = true
        node.left = nil
        node.right = nil
        steps << {rule: "x / x = 1", simplified: true} if steps
        changed = true
      # 0 / x = 0 (if x ≠ 0)
      elsif node.left && node.left.isleaf && node.left.data == 0
        node.data = 0
        node.isleaf = true
        node.left = nil
        node.right = nil
        steps << {rule: "0 / x = 0", simplified: true} if steps
        changed = true
      # Constant folding: a / b = c (but only for clean decimals)
      elsif node.left && node.right && node.left.isleaf && node.right.isleaf &&
            node.left.data.is_a?(Numeric) && node.right.data.is_a?(Numeric) &&
            node.right.data != 0
        # Check if this would create a terminating decimal
        a = node.left.data
        b = node.right.data
        
        # Convert to integers if they're whole numbers
        a_int = a.to_f == a.to_i.to_f ? a.to_i : a
        b_int = b.to_f == b.to_i.to_f ? b.to_i : b
        
        # Only fold if it's a terminating decimal (denominator only has factors of 2 and 5)
        should_fold = false
        if a_int.is_a?(Integer) && b_int.is_a?(Integer)
          b_reduced = b_int.abs
          b_reduced /= 2 while b_reduced % 2 == 0
          b_reduced /= 5 while b_reduced % 5 == 0
          should_fold = (b_reduced == 1)  # Terminating decimal
        else
          should_fold = true  # Non-integer division, fold it
        end
        
        if should_fold
          result = a.to_f / b.to_f
          node.data = result
          node.isleaf = true
          node.left = nil
          node.right = nil
          steps << {rule: "constant folding: #{a} / #{b} = #{result}", simplified: true} if steps
          changed = true
        end
        # Otherwise keep as fraction to preserve exact value
      end
      
    when '^'
      # x^0 = 1
      if node.right && node.right.isleaf && node.right.data == 0
        node.data = 1
        node.isleaf = true
        node.left = nil
        node.right = nil
        steps << {rule: "x^0 = 1", simplified: true} if steps
        changed = true
      # x^1 = x
      elsif node.right && node.right.isleaf && node.right.data == 1
        replace_node_with(node, node.left)
        steps << {rule: "x^1 = x", simplified: true} if steps
        changed = true
      # 0^x = 0 (if x > 0)
      elsif node.left && node.left.isleaf && node.left.data == 0
        node.data = 0
        node.isleaf = true
        node.left = nil
        node.right = nil
        steps << {rule: "0^x = 0", simplified: true} if steps
        changed = true
      # 1^x = 1
      elsif node.left && node.left.isleaf && node.left.data == 1
        node.data = 1
        node.isleaf = true
        node.left = nil
        node.right = nil
        steps << {rule: "1^x = 1", simplified: true} if steps
        changed = true
      # Constant folding for exponentiation
      elsif node.left && node.right && 
         node.left.isleaf && node.right.isleaf &&
         node.left.data.is_a?(Numeric) && node.right.data.is_a?(Numeric)
        # Save values before setting to nil
        left_val = node.left.data
        right_val = node.right.data
        result = left_val ** right_val
        node.data = result
        node.isleaf = true
        node.left = nil
        node.right = nil
        steps << {rule: "constant folding: #{left_val}^#{right_val} = #{result}", simplified: true} if steps
        changed = true
      end
      
    when 'sin', 'cos', 'tan', 'ln', 'exp'
      # Evaluate function with constant argument
      if node.right && node.right.isleaf && node.right.data.is_a?(Numeric)
        arg = node.right.data
        result = case node.data
                when 'sin' then Math.sin(arg)
                when 'cos' then Math.cos(arg)
                when 'tan' then Math.tan(arg)
                when 'ln' then arg > 0 ? Math.log(arg) : Float::NAN
                when 'exp' then Math.exp(arg)
                end
        
        if result && !result.nan?
          node.data = result
          node.isleaf = true
          node.right = nil
          steps << {rule: "constant evaluation: #{node.data}(#{arg})", simplified: true} if steps
          changed = true
        end
      end
    end
    
    changed
  end
  
  # Experimental simplification (improved version)
  def experimental_simplify_pass(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Apply standard rules first
    changed |= standard_simplify_pass(node, steps)
    
    # Additional experimental rules
    changed |= apply_experimental_rules(node, steps)
    
    # Advanced algebraic rules
    changed |= apply_polynomial_expansion(node, steps)
    changed |= apply_distribution(node, steps)  # NEW: expand x*(y+z) to x*y + x*z
    
    # NEW: Collect and combine terms
    changed |= simplify_power_of_power(node, steps)  # (x^a)^b → x^(a*b)
    changed |= multiply_constants_in_product(node, steps)  # 2*x*2 → 4*x
    changed |= collect_constants(node, steps)  # +3-1-1 → +1
    changed |= combine_like_terms(node, steps)  # x^2-x^2 → 0
    changed |= flatten_and_collect_terms(node, steps)  # x^2+(2*x+x^2) → 2*x^2+2*x
    changed |= collect_like_polynomial_terms(node, steps)  # x^2+x^2 → 2*x^2
    changed |= convert_repeated_multiplication(node, steps)  # x*x*x → x^3
    changed |= collect_like_terms_general(node, steps)  # e^x*cos(y) + -1*e^x*cos(y) -> 0
    changed |= simplify_polynomial_division(node, steps)  # (x^2+2*x)/x → x+2
    
    # NOTE: Factoring disabled - we want polynomial form (expanded), not factored
    # changed |= apply_polynomial_factoring(node, steps)
    
    changed |= apply_rational_simplification(node, steps)

    # Apply trig identities (sin^2+cos^2=1, etc.)
    if respond_to?(:apply_trig_identities, true)
      before = node.to_infix
      new_node = apply_trig_identities(node, detect_variable(node))
      if new_node && new_node.to_infix != before
        replace_node_with(node, new_node)
        changed = true
      end
    end

    # Apply normalizer for canonical forms
    if respond_to?(:normalize_expression, true)
      before = node.to_infix
      var = detect_variable(node)
      new_node = normalize_expression(node, var)
      if new_node && new_node.to_infix != before
        replace_node_with(node, new_node)
        changed = true
      end
    end
    
    changed
  end
  
  def apply_experimental_rules(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Rule: x + x = 2*x
    if node.data == '+' && nodes_equal?(node.left, node.right)
      from_expr = "#{node.left.to_infix} + #{node.right.to_infix}"
      mult_node = ExpressionNode.new(false, "*")
      mult_node.connect(ExpressionNode.new(true, 2), "L")
      mult_node.connect(node.left.deep_clone, "R")
      replace_node_with(node, mult_node)
      steps << {operation: "simplification", rule: "Combine like terms: x + x = 2*x", from: from_expr, to: "2 * #{node.left.to_infix}"} if steps
      changed = true
    end
    
    # Rule: x - x = 0
    if node.data == '-' && nodes_equal?(node.left, node.right)
      from_expr = "#{node.left.to_infix} - #{node.right.to_infix}"
      node.data = 0
      node.isleaf = true
      node.left = nil
      node.right = nil
      steps << {operation: "simplification", rule: "Cancel terms: x - x = 0", from: from_expr, to: "0"} if steps
      changed = true
    end
    
    # Rule: x * x = x^2
    if node.data == '*' && nodes_equal?(node.left, node.right)
      pow_node = ExpressionNode.new(false, "^")
      pow_node.connect(node.left.deep_clone, "L")
      pow_node.connect(ExpressionNode.new(true, 2), "R")
      replace_node_with(node, pow_node)
      steps << {operation: "simplification", rule: "Combine factors: x * x = x^2", from: "#{node.left.to_infix} * #{node.right.to_infix}", to: "#{node.left.to_infix}^2"} if steps
      changed = true
    end
    
    # Rule: (x^n) + (x^n) = 2*x^n (same power addition)
    if node.data == '+' && 
       node.left && node.right && 
       node.left.data == '^' && node.right.data == '^' &&
       nodes_equal?(node.left.left, node.right.left) &&  # Same base
       nodes_equal?(node.left.right, node.right.right)   # Same exponent
      # Build 2*x^n
      mult_node = ExpressionNode.new(false, "*")
      mult_node.connect(ExpressionNode.new(true, 2), "L")
      mult_node.connect(node.left.deep_clone, "R")
      replace_node_with(node, mult_node)
      steps << {operation: "simplification", rule: "Combine like powers: x^n + x^n = 2*x^n", from: "#{node.left.to_infix} + #{node.right.to_infix}", to: "2 * #{node.left.to_infix}"} if steps
      changed = true
    end
    
    # Rule: (a*x^n) + (b*x^n) = (a+b)*x^n (same power with coefficients)
    if node.data == '+' && 
       node.left && node.right && 
       node.left.data == '*' && node.right.data == '*'
      # Check if both are c*x^n form
      left_coef = node.left.left
      left_pow = node.left.right
      right_coef = node.right.left
      right_pow = node.right.right
      
      if left_pow && right_pow && 
         left_pow.data == '^' && right_pow.data == '^' &&
         nodes_equal?(left_pow, right_pow) &&  # Same x^n
         left_coef.isleaf && right_coef.isleaf &&
         left_coef.data.is_a?(Numeric) && right_coef.data.is_a?(Numeric)
        # Build (a+b)*x^n
        new_coef = left_coef.data + right_coef.data
        mult_node = ExpressionNode.new(false, "*")
        mult_node.connect(ExpressionNode.new(true, new_coef), "L")
        mult_node.connect(left_pow.deep_clone, "R")
        replace_node_with(node, mult_node)
        steps << {operation: "simplification", rule: "Combine coefficients: (a*x^n) + (b*x^n) = (a+b)*x^n", from: node.to_infix, to: mult_node.to_infix} if steps
        changed = true
      end
    end
    
    # Rule: x / x = 1 (if x ≠ 0)
    if node.data == '/' && nodes_equal?(node.left, node.right)
      node.data = 1
      node.isleaf = true
      node.left = nil
      node.right = nil
      steps << {rule: "EXPERIMENTAL: x / x = 1", simplified: true} if steps
      changed = true
    end
    
    # Rule: (a*x) + (b*x) = (a+b)*x (distributive law reverse)
    if node.data == '+' && 
       node.left && node.left.data == '*' && 
       node.right && node.right.data == '*'
      # Check if they have a common factor
      if nodes_equal?(node.left.right, node.right.right)
        # (a*x) + (b*x) = (a+b)*x
        sum_node = ExpressionNode.new(false, "+")
        sum_node.connect(node.left.left.deep_clone, "L")
        sum_node.connect(node.right.left.deep_clone, "R")
        
        mult_node = ExpressionNode.new(false, "*")
        mult_node.connect(sum_node, "L")
        mult_node.connect(node.left.right.deep_clone, "R")
        
        replace_node_with(node, mult_node)
        steps << {rule: "EXPERIMENTAL: (a*x) + (b*x) = (a+b)*x", simplified: true} if steps
        changed = true
      elsif nodes_equal?(node.left.left, node.right.left)
        # (x*a) + (x*b) = x*(a+b)
        sum_node = ExpressionNode.new(false, "+")
        sum_node.connect(node.left.right.deep_clone, "L")
        sum_node.connect(node.right.right.deep_clone, "R")
        
        mult_node = ExpressionNode.new(false, "*")
        mult_node.connect(node.left.left.deep_clone, "L")
        mult_node.connect(sum_node, "R")
        
        replace_node_with(node, mult_node)
        steps << {rule: "EXPERIMENTAL: (x*a) + (x*b) = x*(a+b)", simplified: true} if steps
        changed = true
      end
    end
    
    # Recursively apply to children
    changed |= apply_experimental_rules(node.left, steps) if node.left
    changed |= apply_experimental_rules(node.right, steps) if node.right
    
    changed
  end
  

  # ==========================================================================
  # General like-term collection over a sum  (EXPERIMENTAL pass only)
  # ==========================================================================
  # The collectors above this one are polynomial-shaped: they go through
  # Polynomial.from_expression, which returns nil for anything transcendental, so
  # a sum of non-polynomial products was never collected at all. The two rules
  # that did fire (x + x = 2x, x - x = 0) require an exact node match, so any
  # explicit numeric coefficient defeated them. The visible consequence:
  #
  #     e^x·cos(y) + -1·e^x·cos(y)     stayed on screen instead of collapsing to 0
  #     2·a·b + 3·a·b                  stayed a sum instead of becoming 5·a·b
  #
  # The first of those is the Laplacian of a harmonic function, so the tool that
  # should print a clean 0 printed a sum whose terms cancel — correct, but it
  # reads like the engine failed to finish.
  #
  # This collects a whole +/- chain at once: split every term into a numeric
  # coefficient and a multiset of factors, key the term on the SORTED factor list
  # (so a·b and b·a agree), sum the coefficients, and rebuild.
  #
  # WHY THE NUMERIC GUARD IS NOT OPTIONAL
  # Two of the bugs fixed in this file and in normalizer.rb were rewrites that
  # silently changed the value of an expression. This rewrite is more aggressive
  # than either, so it refuses to apply itself unless the rebuilt tree agrees with
  # the original at several sample points. A simplification that cannot be shown
  # to preserve the value is not applied.
  SUM_OPS = ['+', '-'].freeze

  def collect_like_terms_general(node, steps = nil)
    return false unless node && !node.isleaf

    # children first, then this node — but only at the TOP of a +/- chain, so the
    # whole chain is collected in one pass rather than pairwise
    changed = false
    changed |= collect_like_terms_general(node.left, steps) if node.left
    changed |= collect_like_terms_general(node.right, steps) if node.right
    return changed unless SUM_OPS.include?(node.data)
    return changed if node.parent && SUM_OPS.include?(node.parent.data)

    terms = []
    flatten_sum_terms(node, 1, terms)
    return changed if terms.size < 2

    groups = {}
    order = []
    terms.each do |sign, term_node|
      coeff, factors = term_coefficient_and_factors(term_node)
      key = factors.map(&:to_infix).sort.join("␀")
      unless groups.key?(key)
        groups[key] = [0.0, factors]
        order << key
      end
      groups[key][0] += sign * coeff
    end

    # nothing merged means nothing to do; bail rather than churn the fixed point
    return changed if groups.size == terms.size

    rebuilt = build_collected_sum(order, groups)
    return changed unless rebuilt

    # the guard: same value, or no rewrite
    unless value_preserved?(node, rebuilt)
      return changed
    end

    before_str = node.to_infix
    replace_node_with(node, rebuilt)
    steps << { operation: 'simplification', rule: 'Collect like terms',
               from: before_str, to: node.to_infix, simplified: true } if steps
    true
  end

  # flatten a +/- chain, carrying the sign; the right operand of '-' flips
  def flatten_sum_terms(node, sign, out)
    if node && !node.isleaf && node.data == '+'
      flatten_sum_terms(node.left, sign, out)
      flatten_sum_terms(node.right, sign, out)
    elsif node && !node.isleaf && node.data == '-'
      flatten_sum_terms(node.left, sign, out)
      flatten_sum_terms(node.right, -sign, out)
    else
      out << [sign, node]
    end
  end

  # a product splits into one numeric coefficient and the remaining factors;
  # anything that is not a product is a single factor with coefficient 1
  def term_coefficient_and_factors(node)
    return [1.0, []] unless node
    if node.isleaf
      return [node.data.to_f, []] if node.data.is_a?(Numeric)
      return [1.0, [node]]
    end
    if node.data == '*'
      lc, lf = term_coefficient_and_factors(node.left)
      rc, rf = term_coefficient_and_factors(node.right)
      return [lc * rc, lf + rf]
    end
    [1.0, [node]]
  end

  def build_collected_sum(order, groups)
    parts = []
    order.each do |key|
      coeff, factors = groups[key]
      next if coeff.abs < 1e-12
      parts << [coeff, factors]
    end
    return ExpressionNode.new(true, 0) if parts.empty?

    result = nil
    parts.each_with_index do |(coeff, factors), idx|
      magnitude = idx.zero? ? coeff : coeff.abs
      term = build_term(magnitude, factors)
      if idx.zero?
        result = term
      else
        op = ExpressionNode.new(false, coeff.negative? ? '-' : '+')
        op.connect(result, 'L')
        op.connect(term, 'R')
        result = op
      end
    end
    result
  end

  def build_term(coeff, factors)
    clean = coeff == coeff.to_i ? coeff.to_i : coeff
    product = nil
    factors.each do |f|
      clone = f.deep_clone
      if product.nil?
        product = clone
      else
        mult = ExpressionNode.new(false, '*')
        mult.connect(product, 'L')
        mult.connect(clone, 'R')
        product = mult
      end
    end
    return ExpressionNode.new(true, clean) if product.nil?
    return product if (coeff - 1.0).abs < 1e-12

    mult = ExpressionNode.new(false, '*')
    mult.connect(ExpressionNode.new(true, clean), 'L')
    mult.connect(product, 'R')
    mult
  end

  # Sample both trees at several points and demand they agree. Points where either
  # side is not finite (a pole, a log of a negative) prove nothing and are skipped,
  # but at least one usable comparison is required before the rewrite is accepted.
  def value_preserved?(original, rebuilt)
    names = collect_symbol_names(original, []).uniq
    compared = 0
    5.times do |k|
      env = {}
      names.each_with_index { |n, i| env[n] = 0.83 + 0.37 * ((i + 2 * k) % 6) + 0.11 * k }
      a = begin
        original.evaluate(env)
      rescue StandardError
        nil
      end
      b = begin
        rebuilt.evaluate(env)
      rescue StandardError
        nil
      end
      return false unless a.is_a?(Numeric) && b.is_a?(Numeric)
      next unless a.finite? && b.finite?
      compared += 1
      return false if (a - b).abs > 1e-7 * [1.0, a.abs].max
    end
    compared.positive?
  end

  def collect_symbol_names(node, acc)
    return acc unless node
    if node.isleaf
      acc << node.data if node.data.is_a?(String)
    else
      collect_symbol_names(node.left, acc)
      collect_symbol_names(node.right, acc)
    end
    acc
  end

  # Check if two nodes represent the same expression
  def nodes_equal?(node1, node2)
    return false unless node1 && node2
    
    if node1.isleaf && node2.isleaf
      return node1.data == node2.data
    elsif !node1.isleaf && !node2.isleaf
      return node1.data == node2.data &&
             nodes_equal?(node1.left, node2.left) &&
             nodes_equal?(node1.right, node2.right)
    else
      return false
    end
  end
  
  # Replace a node with another node (preserving parent connections)
  # Detect the first variable in an expression tree
  def detect_variable(node)
    return nil unless node
    if node.isleaf
      return node.data if node.data.is_a?(String) && node.data =~ /^[a-z]$/
      return nil
    end
    detect_variable(node.left) || detect_variable(node.right)
  end

  def replace_node_with(old_node, new_node)
    return unless old_node && new_node
    
    old_node.data = new_node.data
    old_node.isleaf = new_node.isleaf
    old_node.left = new_node.left
    old_node.right = new_node.right
    old_node.type = new_node.type
    
    # Update parent pointers
    old_node.left.parent = old_node if old_node.left
    old_node.right.parent = old_node if old_node.right
  end
  
  # Apply polynomial expansion: (x+a)^n, etc.
  def apply_polynomial_expansion(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively process children first
    changed |= apply_polynomial_expansion(node.left, steps) if node.left
    changed |= apply_polynomial_expansion(node.right, steps) if node.right
    
    # Expand (x+a)^2 → x^2 + 2*a*x + a^2
    if node.data == '^' && node.right && node.right.isleaf && 
       node.right.data.is_a?(Numeric) && node.right.data == 2 &&
       node.left && node.left.data == '+'
      
      # (u + v)^2 = u^2 + 2*u*v + v^2
      u = node.left.left
      v = node.left.right
      
      if u && v
        from_expr = node.to_infix
        
        # Build u^2
        u_squared = ExpressionNode.new(false, "^")
        u_squared.connect(u.deep_clone, "L")
        u_squared.connect(ExpressionNode.new(true, 2), "R")
        
        # Build v^2
        v_squared = ExpressionNode.new(false, "^")
        v_squared.connect(v.deep_clone, "L")
        v_squared.connect(ExpressionNode.new(true, 2), "R")
        
        # Build 2*u*v
        two_uv = ExpressionNode.new(false, "*")
        two_uv.connect(ExpressionNode.new(true, 2), "L")
        uv_node = ExpressionNode.new(false, "*")
        uv_node.connect(u.deep_clone, "L")
        uv_node.connect(v.deep_clone, "R")
        two_uv.connect(uv_node, "R")
        
        # Build u^2 + 2*u*v
        left_sum = ExpressionNode.new(false, "+")
        left_sum.connect(u_squared, "L")
        left_sum.connect(two_uv, "R")
        
        # Build (u^2 + 2*u*v) + v^2
        result = ExpressionNode.new(false, "+")
        result.connect(left_sum, "L")
        result.connect(v_squared, "R")
        
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Expand: (u+v)^2 = u^2 + 2*u*v + v^2", from: from_expr, to: node.to_infix} if steps
        changed = true
      end
    end
    
    # Expand (x-a)^2 → x^2 - 2*a*x + a^2
    if node.data == '^' && node.right && node.right.isleaf && 
       node.right.data.is_a?(Numeric) && node.right.data == 2 &&
       node.left && node.left.data == '-'
      
      # (u - v)^2 = u^2 - 2*u*v + v^2
      u = node.left.left
      v = node.left.right
      
      if u && v
        from_expr = node.to_infix
        
        # Build u^2
        u_squared = ExpressionNode.new(false, "^")
        u_squared.connect(u.deep_clone, "L")
        u_squared.connect(ExpressionNode.new(true, 2), "R")
        
        # Build v^2
        v_squared = ExpressionNode.new(false, "^")
        v_squared.connect(v.deep_clone, "L")
        v_squared.connect(ExpressionNode.new(true, 2), "R")
        
        # Build 2*u*v
        two_uv = ExpressionNode.new(false, "*")
        two_uv.connect(ExpressionNode.new(true, 2), "L")
        uv_node = ExpressionNode.new(false, "*")
        uv_node.connect(u.deep_clone, "L")
        uv_node.connect(v.deep_clone, "R")
        two_uv.connect(uv_node, "R")
        
        # Build u^2 - 2*u*v
        left_diff = ExpressionNode.new(false, "-")
        left_diff.connect(u_squared, "L")
        left_diff.connect(two_uv, "R")
        
        # Build (u^2 - 2*u*v) + v^2
        result = ExpressionNode.new(false, "+")
        result.connect(left_diff, "L")
        result.connect(v_squared, "R")
        
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Expand: (u-v)^2 = u^2 - 2*u*v + v^2", from: from_expr, to: node.to_infix} if steps
        changed = true
      end
    end
    
    # Expand (x+a)^3 → x^3 + 3*x^2*a + 3*x*a^2 + a^3
    if node.data == '^' && node.right && node.right.isleaf && 
       node.right.data.is_a?(Numeric) && node.right.data == 3 &&
       node.left && node.left.data == '+'
      
      # (u + v)^3 = u^3 + 3*u^2*v + 3*u*v^2 + v^3
      u = node.left.left
      v = node.left.right
      
      if u && v
        from_expr = node.to_infix
        
        # Build u^3
        u_cubed = ExpressionNode.new(false, "^")
        u_cubed.connect(u.deep_clone, "L")
        u_cubed.connect(ExpressionNode.new(true, 3), "R")
        
        # Build u^2
        u_squared = ExpressionNode.new(false, "^")
        u_squared.connect(u.deep_clone, "L")
        u_squared.connect(ExpressionNode.new(true, 2), "R")
        
        # Build v^2
        v_squared = ExpressionNode.new(false, "^")
        v_squared.connect(v.deep_clone, "L")
        v_squared.connect(ExpressionNode.new(true, 2), "R")
        
        # Build v^3
        v_cubed = ExpressionNode.new(false, "^")
        v_cubed.connect(v.deep_clone, "L")
        v_cubed.connect(ExpressionNode.new(true, 3), "R")
        
        # Build 3*u^2*v
        u2v = ExpressionNode.new(false, "*")
        u2v.connect(u_squared, "L")
        u2v.connect(v.deep_clone, "R")
        three_u2v = ExpressionNode.new(false, "*")
        three_u2v.connect(ExpressionNode.new(true, 3), "L")
        three_u2v.connect(u2v, "R")
        
        # Build 3*u*v^2
        uv2 = ExpressionNode.new(false, "*")
        uv2.connect(u.deep_clone, "L")
        uv2.connect(v_squared, "R")
        three_uv2 = ExpressionNode.new(false, "*")
        three_uv2.connect(ExpressionNode.new(true, 3), "L")
        three_uv2.connect(uv2, "R")
        
        # Build u^3 + 3*u^2*v
        sum1 = ExpressionNode.new(false, "+")
        sum1.connect(u_cubed, "L")
        sum1.connect(three_u2v, "R")
        
        # Build (u^3 + 3*u^2*v) + 3*u*v^2
        sum2 = ExpressionNode.new(false, "+")
        sum2.connect(sum1, "L")
        sum2.connect(three_uv2, "R")
        
        # Build ((u^3 + 3*u^2*v) + 3*u*v^2) + v^3
        result = ExpressionNode.new(false, "+")
        result.connect(sum2, "L")
        result.connect(v_cubed, "R")
        
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Expand: (u+v)^3 = u^3 + 3*u^2*v + 3*u*v^2 + v^3", from: from_expr, to: node.to_infix} if steps
        changed = true
      end
    end
    
    # Expand (x-a)^3 → x^3 - 3*x^2*a + 3*x*a^2 - a^3
    if node.data == '^' && node.right && node.right.isleaf && 
       node.right.data.is_a?(Numeric) && node.right.data == 3 &&
       node.left && node.left.data == '-'
      
      # (u - v)^3 = u^3 - 3*u^2*v + 3*u*v^2 - v^3
      u = node.left.left
      v = node.left.right
      
      if u && v
        from_expr = node.to_infix
        
        # Build u^3
        u_cubed = ExpressionNode.new(false, "^")
        u_cubed.connect(u.deep_clone, "L")
        u_cubed.connect(ExpressionNode.new(true, 3), "R")
        
        # Build u^2
        u_squared = ExpressionNode.new(false, "^")
        u_squared.connect(u.deep_clone, "L")
        u_squared.connect(ExpressionNode.new(true, 2), "R")
        
        # Build v^2
        v_squared = ExpressionNode.new(false, "^")
        v_squared.connect(v.deep_clone, "L")
        v_squared.connect(ExpressionNode.new(true, 2), "R")
        
        # Build v^3
        v_cubed = ExpressionNode.new(false, "^")
        v_cubed.connect(v.deep_clone, "L")
        v_cubed.connect(ExpressionNode.new(true, 3), "R")
        
        # Build 3*u^2*v
        u2v = ExpressionNode.new(false, "*")
        u2v.connect(u_squared, "L")
        u2v.connect(v.deep_clone, "R")
        three_u2v = ExpressionNode.new(false, "*")
        three_u2v.connect(ExpressionNode.new(true, 3), "L")
        three_u2v.connect(u2v, "R")
        
        # Build 3*u*v^2
        uv2 = ExpressionNode.new(false, "*")
        uv2.connect(u.deep_clone, "L")
        uv2.connect(v_squared, "R")
        three_uv2 = ExpressionNode.new(false, "*")
        three_uv2.connect(ExpressionNode.new(true, 3), "L")
        three_uv2.connect(uv2, "R")
        
        # Build u^3 - 3*u^2*v
        diff1 = ExpressionNode.new(false, "-")
        diff1.connect(u_cubed, "L")
        diff1.connect(three_u2v, "R")
        
        # Build (u^3 - 3*u^2*v) + 3*u*v^2
        sum1 = ExpressionNode.new(false, "+")
        sum1.connect(diff1, "L")
        sum1.connect(three_uv2, "R")
        
        # Build ((u^3 - 3*u^2*v) + 3*u*v^2) - v^3
        result = ExpressionNode.new(false, "-")
        result.connect(sum1, "L")
        result.connect(v_cubed, "R")
        
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Expand: (u-v)^3 = u^3 - 3*u^2*v + 3*u*v^2 - v^3", from: from_expr, to: node.to_infix} if steps
        changed = true
      end
    end
    
    changed
  end
  
  # Apply distribution: a*(b+c) = a*b + a*c, (b+c)*a = b*a + c*a
  def apply_distribution(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively process children first
    changed |= apply_distribution(node.left, steps) if node.left
    changed |= apply_distribution(node.right, steps) if node.right
    
    # Pattern: a * (b + c) -> a*b + a*c
    if node.data == '*'
      left = node.left
      right = node.right
      return changed unless left && right
      
      # Case 1: a * (b + c)
      if right && !right.isleaf && (right.data == '+' || right.data == '-')
        from_expr = node.to_infix
        
        # Build a*b
        term1 = ExpressionNode.new(false, "*")
        term1.connect(left.deep_clone, "L")
        term1.connect(right.left.deep_clone, "R")
        
        # Build a*c
        term2 = ExpressionNode.new(false, "*")
        term2.connect(left.deep_clone, "L")
        term2.connect(right.right.deep_clone, "R")
        
        # Build a*b + a*c or a*b - a*c
        result = ExpressionNode.new(false, right.data)  # Keep the same operator (+ or -)
        result.connect(term1, "L")
        result.connect(term2, "R")
        
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Distribute: a*(b#{right.data}c) = a*b#{right.data}a*c", from: from_expr, to: node.to_infix} if steps
        changed = true
      # Case 2: (b + c) * a
      elsif left && right && !left.isleaf && (left.data == '+' || left.data == '-') && left.left && left.right
        from_expr = node.to_infix
        
        # Build b*a
        term1 = ExpressionNode.new(false, "*")
        term1.connect(left.left.deep_clone, "L")
        term1.connect(right.deep_clone, "R")
        
        # Build c*a
        term2 = ExpressionNode.new(false, "*")
        term2.connect(left.right.deep_clone, "L")
        term2.connect(right.deep_clone, "R")
        
        # Build b*a + c*a or b*a - c*a
        result = ExpressionNode.new(false, left.data)  # Keep the same operator (+ or -)
        result.connect(term1, "L")
        result.connect(term2, "R")
        
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Distribute: (b#{left.data}c)*a = b*a#{left.data}c*a", from: from_expr, to: node.to_infix} if steps
        changed = true
      end
    end
    
    changed
  end
  
  # Apply polynomial factoring
  def apply_polynomial_factoring(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively process children first
    changed |= apply_polynomial_factoring(node.left, steps) if node.left
    changed |= apply_polynomial_factoring(node.right, steps) if node.right
    
    # Factor x^2 + a*x → x*(x + a)
    if node.data == '+'
      left = node.left
      right = node.right
      
      # Check for x^2 + a*x pattern
      if left && right && left.data == '^' && right.data == '*'
        # left is x^2
        if left.left && left.left.isleaf && left.right && left.right.isleaf && left.right.data == 2
          x_var = left.left.data
          
          # right is a*x (or x*a)
          coef = nil
          if right.left.isleaf && right.left.data.is_a?(Numeric) && 
             right.right.isleaf && right.right.data == x_var
            coef = right.left.data
          elsif right.right.isleaf && right.right.data.is_a?(Numeric) && 
                right.left.isleaf && right.left.data == x_var
            coef = right.right.data
          end
          
          if coef
            from_expr = node.to_infix
            
            # Factor out x: x^2 + a*x = x*(x + a)
            x_node = ExpressionNode.new(true, x_var)
            
            # Build (x + a)
            inner_sum = ExpressionNode.new(false, "+")
            inner_sum.connect(ExpressionNode.new(true, x_var), "L")
            inner_sum.connect(ExpressionNode.new(true, coef), "R")
            
            # Build x * (x + a)
            result = ExpressionNode.new(false, "*")
            result.connect(x_node, "L")
            result.connect(inner_sum, "R")
            
            replace_node_with(node, result)
            steps << {operation: "simplification", rule: "Factor: x^2 + a*x = x*(x+a)", from: from_expr, to: node.to_infix} if steps
            changed = true
          end
        end
      end
      
      # Check for a*x + x^2 pattern (reversed)
      if left && right && left.data == '*' && right.data == '^'
        # right is x^2
        if right.left && right.left.isleaf && right.right && right.right.isleaf && right.right.data == 2
          x_var = right.left.data
          
          # left is a*x (or x*a)
          coef = nil
          if left.left.isleaf && left.left.data.is_a?(Numeric) && 
             left.right.isleaf && left.right.data == x_var
            coef = left.left.data
          elsif left.right.isleaf && left.right.data.is_a?(Numeric) && 
                left.left.isleaf && left.left.data == x_var
            coef = left.right.data
          end
          
          if coef
            from_expr = node.to_infix
            
            # Factor out x: x^2 + a*x = x*(x + a)
            x_node = ExpressionNode.new(true, x_var)
            
            # Build (x + a)
            inner_sum = ExpressionNode.new(false, "+")
            inner_sum.connect(ExpressionNode.new(true, x_var), "L")
            inner_sum.connect(ExpressionNode.new(true, coef), "R")
            
            # Build x * (x + a)
            result = ExpressionNode.new(false, "*")
            result.connect(x_node, "L")
            result.connect(inner_sum, "R")
            
            replace_node_with(node, result)
            steps << {operation: "simplification", rule: "Factor: x^2 + a*x = x*(x+a)", from: from_expr, to: node.to_infix} if steps
            changed = true
          end
        end
      end
    end
    
    changed
  end
  
  # Apply rational simplification: cancel common factors
  def apply_rational_simplification(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively process children first
    changed |= apply_rational_simplification(node.left, steps) if node.left
    changed |= apply_rational_simplification(node.right, steps) if node.right
    
    # Simplify division: (a*b) / (a*c) = b / c
    if node.data == '/'
      numerator = node.left
      denominator = node.right
      
      if numerator && denominator
        # Try to extract and cancel common factors
        common_factor = find_common_factor(numerator, denominator)
        
        if common_factor
          from_expr = node.to_infix
          
          # Remove common factor from numerator and denominator
          new_num = divide_by_factor(numerator, common_factor)
          new_den = divide_by_factor(denominator, common_factor)
          
          # Handle case where everything cancels
          if new_num.nil?
            new_num = ExpressionNode.new(true, 1)
          end
          if new_den.nil?
            new_den = ExpressionNode.new(true, 1)
          end
          
          # Build new division
          if new_den.isleaf && new_den.data == 1
            # Denominator is 1, just return numerator
            replace_node_with(node, new_num)
          else
            new_div = ExpressionNode.new(false, "/")
            new_div.connect(new_num, "L")
            new_div.connect(new_den, "R")
            replace_node_with(node, new_div)
          end
          
          steps << {operation: "simplification", rule: "Cancel common factor: #{common_factor.to_infix}", from: from_expr, to: node.to_infix} if steps
          changed = true
        end
      end
    end
    
    changed
  end
  
  # Find common factor between two expressions
  def find_common_factor(expr1, expr2)
    return nil unless expr1 && expr2
    
    # Case 1: Both are the same (not constants)
    if nodes_equal?(expr1, expr2) && !(expr1.isleaf && expr1.data.is_a?(Numeric))
      return expr1.deep_clone
    end
    
    # Case 2: Check for power vs base (e.g., x^2 and x share x)
    # expr1 is x^n and expr2 is x → common factor is x
    if expr1.data == '^' && expr1.left && nodes_equal?(expr1.left, expr2)
      return expr2.deep_clone
    end
    
    # expr2 is x^n and expr1 is x → common factor is x
    if expr2.data == '^' && expr2.left && nodes_equal?(expr2.left, expr1)
      return expr1.deep_clone
    end
    
    # Case 3: Both are multiplications - find common factors
    if expr1.data == '*' && expr2.data == '*'
      # Check left factors
      if nodes_equal?(expr1.left, expr2.left)
        return expr1.left.deep_clone
      elsif nodes_equal?(expr1.left, expr2.right)
        return expr1.left.deep_clone
      elsif nodes_equal?(expr1.right, expr2.left)
        return expr1.right.deep_clone
      elsif nodes_equal?(expr1.right, expr2.right)
        return expr1.right.deep_clone
      end
      
      # Check if one factor is a power and the other is its base
      # e.g., (2 * x^2) and (x * (x+2)) share x
      if expr1.right.data == '^' && nodes_equal?(expr1.right.left, expr2.left)
        return expr2.left.deep_clone
      elsif expr1.right.data == '^' && nodes_equal?(expr1.right.left, expr2.right)
        return expr2.right.deep_clone
      elsif expr2.right.data == '^' && nodes_equal?(expr2.right.left, expr1.left)
        return expr1.left.deep_clone
      elsif expr2.right.data == '^' && nodes_equal?(expr2.right.left, expr1.right)
        return expr1.right.deep_clone
      end
    end
    
    # Case 4: One is multiplication, check if other is a factor
    if expr1.data == '*'
      if nodes_equal?(expr1.left, expr2)
        return expr2.deep_clone
      elsif nodes_equal?(expr1.right, expr2)
        return expr2.deep_clone
      end
      
      # Check if multiplication contains a power that shares base with expr2
      # e.g., (2 * x^2) and x share x
      if expr1.right.data == '^' && nodes_equal?(expr1.right.left, expr2)
        return expr2.deep_clone
      elsif expr1.left.data == '^' && nodes_equal?(expr1.left.left, expr2)
        return expr2.deep_clone
      end
    end
    
    if expr2.data == '*'
      if nodes_equal?(expr2.left, expr1)
        return expr1.deep_clone
      elsif nodes_equal?(expr2.right, expr1)
        return expr1.deep_clone
      end
      
      # Check if multiplication contains a power that shares base with expr1
      if expr2.right.data == '^' && nodes_equal?(expr2.right.left, expr1)
        return expr1.deep_clone
      elsif expr2.left.data == '^' && nodes_equal?(expr2.left.left, expr1)
        return expr1.deep_clone
      end
    end
    
    # Case 4: Extract common variables from polynomials
    # e.g., 2*x^2 and x*(x+2) both have x
    factor1 = extract_gcd_factor(expr1)
    factor2 = extract_gcd_factor(expr2)
    
    if factor1 && factor2 && nodes_equal?(factor1, factor2)
      return factor1
    end
    
    nil
  end
  
  # Extract GCD factor from expression (simple cases)
  def extract_gcd_factor(expr)
    return nil unless expr
    
    # For multiplication a*b, try to find a factor
    if expr.data == '*'
      # Return the variable part (not numeric constant)
      if expr.left.isleaf && expr.left.data.is_a?(Numeric)
        return expr.right.deep_clone
      elsif expr.right.isleaf && expr.right.data.is_a?(Numeric)
        return expr.left.deep_clone
      else
        # Both non-numeric, return left (arbitrary choice)
        return expr.left.deep_clone
      end
    end
    
    # For addition/subtraction, harder - would need full factoring
    # For now, just return nil
    nil
  end
  
  # Divide expression by a factor (returns remaining expression)
  def divide_by_factor(expr, factor)
    return nil unless expr && factor
    
    # If they're equal, result is 1
    if nodes_equal?(expr, factor)
      return nil  # Signal that result is 1
    end
    
    # If expr is x^n and factor is x, return x^(n-1)
    if expr.data == '^' && nodes_equal?(expr.left, factor)
      exponent = expr.right
      if exponent.isleaf && exponent.data.is_a?(Numeric)
        new_exp = exponent.data - 1
        if new_exp == 1
          # x^2 / x = x
          return factor.deep_clone
        elsif new_exp == 0
          # x^1 / x = 1
          return nil
        else
          # x^n / x = x^(n-1)
          result = ExpressionNode.new(false, "^")
          result.connect(factor.deep_clone, "L")
          result.connect(ExpressionNode.new(true, new_exp), "R")
          return result
        end
      end
    end
    
    # If expr is a*factor, return a
    if expr.data == '*'
      if nodes_equal?(expr.left, factor)
        return expr.right.deep_clone
      elsif nodes_equal?(expr.right, factor)
        return expr.left.deep_clone
      end
      
      # If expr is a*(x^n) and factor is x, return a*x^(n-1)
      if expr.right.data == '^' && nodes_equal?(expr.right.left, factor)
        quotient = divide_by_factor(expr.right, factor)
        if quotient.nil?
          # x^n/x resulted in 1, so a*(x^n)/x = a
          return expr.left.deep_clone
        else
          # a*(x^n)/x = a*x^(n-1)
          result = ExpressionNode.new(false, "*")
          result.connect(expr.left.deep_clone, "L")
          result.connect(quotient, "R")
          return result
        end
      elsif expr.left.data == '^' && nodes_equal?(expr.left.left, factor)
        quotient = divide_by_factor(expr.left, factor)
        if quotient.nil?
          return expr.right.deep_clone
        else
          result = ExpressionNode.new(false, "*")
          result.connect(quotient, "L")
          result.connect(expr.right.deep_clone, "R")
          return result
        end
      end
    end
    
    # Otherwise, can't simplify - return original
    expr.deep_clone
  end
  
  # Collect constants in addition/subtraction: 3-1-1 → 1
  def collect_constants(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively process children first
    changed |= collect_constants(node.left, steps) if node.left
    changed |= collect_constants(node.right, steps) if node.right
    
    # Only process addition/subtraction
    return changed unless node.data == '+' || node.data == '-'
    
    # Collect all constants in this subtree
    constants = []
    non_constants = []
    collect_additive_terms(node, constants, non_constants, true)
    
    # If we have multiple constants, combine them
    if constants.length > 1
      from_expr = node.to_infix
      
      # Sum all constants
      total = constants.sum
      
      # Build result
      if non_constants.empty?
        # Only constants
        result = ExpressionNode.new(true, total)
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Collect constants", from: from_expr, to: node.to_infix} if steps
        changed = true
      elsif total != 0
        # Mix of constants and non-constants
        # Build sum of non-constants
        result = build_sum_from_terms(non_constants)
        
        # Add the constant
        add_node = ExpressionNode.new(false, "+")
        add_node.connect(result, "L")
        add_node.connect(ExpressionNode.new(true, total), "R")
        
        replace_node_with(node, add_node)
        steps << {operation: "simplification", rule: "Collect constants: #{constants.join('+')} = #{total}", from: from_expr, to: node.to_infix} if steps
        changed = true
      elsif total == 0 && !non_constants.empty?
        # Constants sum to 0, remove them
        result = build_sum_from_terms(non_constants)
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Remove zero constant", from: from_expr, to: node.to_infix} if steps
        changed = true
      end
    end
    
    changed
  end
  
  # Helper: collect additive terms (for constant collection)
  def collect_additive_terms(node, constants, non_constants, positive = true)
    return unless node
    
    if node.data == '+'
      collect_additive_terms(node.left, constants, non_constants, positive)
      collect_additive_terms(node.right, constants, non_constants, positive)
    elsif node.data == '-'
      collect_additive_terms(node.left, constants, non_constants, positive)
      collect_additive_terms(node.right, constants, non_constants, !positive)
    elsif node.isleaf && node.data.is_a?(Numeric)
      constants << (positive ? node.data : -node.data)
    else
      non_constants << {node: node.deep_clone, positive: positive}
    end
  end
  
  # Helper: build sum from terms array
  def build_sum_from_terms(terms)
    return ExpressionNode.new(true, 0) if terms.empty?
    return terms[0][:node] if terms.length == 1 && terms[0][:positive]
    
    # Build left-to-right
    result = nil
    terms.each do |term|
      if result.nil?
        if term[:positive]
          result = term[:node]
        else
          # First term is negative: 0 - term
          result = ExpressionNode.new(false, "-")
          result.connect(ExpressionNode.new(true, 0), "L")
          result.connect(term[:node], "R")
        end
      else
        op_node = ExpressionNode.new(false, term[:positive] ? "+" : "-")
        op_node.connect(result, "L")
        op_node.connect(term[:node], "R")
        result = op_node
      end
    end
    
    result
  end
  
  # Combine like terms: x^2 - x^2 → 0
  def combine_like_terms(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively process children first
    changed |= combine_like_terms(node.left, steps) if node.left
    changed |= combine_like_terms(node.right, steps) if node.right
    
    # Pattern: expr + (-1)*expr or expr - expr
    if node.data == '+'
      # Check if left and right are negatives of each other
      if nodes_equal?(node.left, node.right)
        # x + x = 2*x (already handled elsewhere)
      elsif node.right && !node.right.isleaf && 
            node.right.data == '*' && 
            node.right.left && node.right.left.isleaf && 
            node.right.left.data.is_a?(Numeric) &&
            node.right.left.data == -1 &&
            node.right.right &&
            nodes_equal?(node.left, node.right.right)
        # x + (-1)*x = 0
        from_expr = node.to_infix
        result = ExpressionNode.new(true, 0)
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Cancel like terms: a + (-a) = 0", from: from_expr, to: node.to_infix} if steps
        changed = true
      end
    elsif node.data == '-'
      if node.left && node.right && nodes_equal?(node.left, node.right)
        # x - x = 0
        from_expr = node.to_infix
        result = ExpressionNode.new(true, 0)
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Cancel like terms: a - a = 0", from: from_expr, to: node.to_infix} if steps
        changed = true
      end
    end
    
    changed
  end
  
  # Simplify polynomial division: (x^2+2*x)/x → x+2
  def simplify_polynomial_division(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively process children first
    changed |= simplify_polynomial_division(node.left, steps) if node.left
    changed |= simplify_polynomial_division(node.right, steps) if node.right
    
    # Only process division
    return changed unless node.data == '/'
    
    numerator = node.left
    denominator = node.right
    
    return changed unless numerator && denominator
    
    # Case 1: denominator is x^n (power of a variable)
    if !denominator.isleaf && denominator.data == '^' &&
       denominator.left && denominator.left.isleaf && 
       denominator.right && denominator.right.isleaf && denominator.right.data.is_a?(Numeric)
      
      variable = denominator.left.data
      div_exp = denominator.right.data
      
      # Try to distribute division over sum in numerator
      if numerator.data == '+' || numerator.data == '-'
        if can_divide_all_terms_by_power(numerator, variable, div_exp)
          from_expr = node.to_infix
          result = divide_polynomial_by_power(numerator, variable, div_exp)
          replace_node_with(node, result)
          steps << {operation: "simplification", rule: "Polynomial division by #{variable}^#{div_exp}", from: from_expr, to: node.to_infix} if steps
          changed = true
        end
      end
    # Case 2: denominator is just x (variable)
    elsif denominator.isleaf && !denominator.data.is_a?(Numeric)
      variable = denominator.data
      
      # Try to distribute division over sum in numerator
      if numerator.data == '+' || numerator.data == '-'
        if can_divide_all_terms_by_power(numerator, variable, 1)
          from_expr = node.to_infix
          result = divide_polynomial_by_power(numerator, variable, 1)
          replace_node_with(node, result)
          steps << {operation: "simplification", rule: "Polynomial division by #{variable}", from: from_expr, to: node.to_infix} if steps
          changed = true
        end
      end
    end
    
    changed
  end
  
  # Helper: Check if all terms in a sum can be divided by var^exp
  def can_divide_all_terms_by_power(node, variable, min_exp)
    return false unless node
    
    if node.data == '+' || node.data == '-'
      left_ok = can_divide_all_terms_by_power(node.left, variable, min_exp)
      right_ok = can_divide_all_terms_by_power(node.right, variable, min_exp)
      return left_ok && right_ok
    else
      # Check if this term has var^k where k >= min_exp
      term_exp = get_variable_exponent(node, variable)
      return term_exp && term_exp >= min_exp
    end
  end
  
  # Helper: Get the exponent of a variable in a term (or nil if not present)
  def get_variable_exponent(node, variable)
    return nil unless node
    
    # Simple variable: x
    if node.isleaf && node.data == variable
      return 1
    end
    
    # Power: x^n
    if !node.isleaf && node.data == '^' &&
       node.left && node.left.isleaf && node.left.data == variable &&
       node.right && node.right.isleaf && node.right.data.is_a?(Numeric)
      return node.right.data
    end
    
    # Product: coef * x^n or x^n * coef
    if !node.isleaf && node.data == '*'
      left_exp = get_variable_exponent(node.left, variable)
      right_exp = get_variable_exponent(node.right, variable)
      
      # If one side is the variable term, return its exponent
      return left_exp if left_exp && !right_exp
      return right_exp if right_exp && !left_exp
    end
    
    return nil
  end
  
  # Helper: Divide polynomial by var^exp
  def divide_polynomial_by_power(node, variable, div_exp)
    return nil unless node
    
    if node.data == '+' || node.data == '-'
      left_result = divide_polynomial_by_power(node.left, variable, div_exp)
      right_result = divide_polynomial_by_power(node.right, variable, div_exp)
      
      result = ExpressionNode.new(false, node.data)
      result.connect(left_result, "L")
      result.connect(right_result, "R")
      return result
    else
      # Divide this term
      return divide_term_by_power(node, variable, div_exp)
    end
  end
  
  # Helper: Divide a single term by var^exp
  def divide_term_by_power(term, variable, div_exp)
    # Get current exponent
    current_exp = get_variable_exponent(term, variable)
    return term.deep_clone unless current_exp && current_exp >= div_exp
    
    new_exp = current_exp - div_exp
    
    # Extract coefficient if present
    coef = nil
    var_part = term
    
    if !term.isleaf && term.data == '*'
      if term.left && term.left.isleaf && term.left.data.is_a?(Numeric)
        coef = term.left.data
        var_part = term.right
      elsif term.right && term.right.isleaf && term.right.data.is_a?(Numeric)
        coef = term.right.data
        var_part = term.left
      end
    end
    
    # Build result
    if new_exp == 0
      # Just the coefficient (or 1 if no coefficient)
      return ExpressionNode.new(true, coef || 1)
    elsif new_exp == 1
      # var (possibly with coefficient)
      var_node = ExpressionNode.new(true, variable)
      if coef
        result = ExpressionNode.new(false, "*")
        result.connect(ExpressionNode.new(true, coef), "L")
        result.connect(var_node, "R")
        return result
      else
        return var_node
      end
    else
      # var^new_exp (possibly with coefficient)
      pow_node = ExpressionNode.new(false, "^")
      pow_node.connect(ExpressionNode.new(true, variable), "L")
      pow_node.connect(ExpressionNode.new(true, new_exp), "R")
      
      if coef
        result = ExpressionNode.new(false, "*")
        result.connect(ExpressionNode.new(true, coef), "L")
        result.connect(pow_node, "R")
        return result
      else
        return pow_node
      end
    end
  end
  
  # Convert repeated multiplication to exponents: x*x*x → x^3, x*x*y*y → x^2*y^2
  def convert_repeated_multiplication(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively process children first
    changed |= convert_repeated_multiplication(node.left, steps) if node.left
    changed |= convert_repeated_multiplication(node.right, steps) if node.right
    
    # Only process multiplication
    return changed unless node.data == '*'
    
    # Collect all factors in this multiplication chain
    factors = []
    collect_multiplicative_factors(node, factors)
    
    # Separate numeric and symbolic factors, and handle powers
    base_counts = {}  # Track base: count for x^2*x -> base x: count 3
    numeric_factors = []
    
    factors.each do |factor|
      if factor.isleaf && factor.data.is_a?(Numeric)
        numeric_factors << factor
      elsif factor.data == '^'
        # It's a power: x^n
        base_key = factor.left.to_infix
        exponent = factor.right.isleaf && factor.right.data.is_a?(Numeric) ? factor.right.data : nil
        
        if exponent
          base_counts[base_key] ||= {node: factor.left, count: 0}
          base_counts[base_key][:count] += exponent
        else
          # Can't simplify non-numeric exponent
          key = factor.to_infix
          base_counts[key] ||= {node: factor, count: 0}
          base_counts[key][:count] += 1
        end
      else
        # Regular factor
        key = factor.to_infix
        base_counts[key] ||= {node: factor, count: 0}
        base_counts[key][:count] += 1
      end
    end
    
    # Check if any combining happened
    has_changes = base_counts.values.any? { |v| v[:count] > 1 }
    
    if has_changes || (base_counts.length < factors.length - numeric_factors.length)
      from_expr = node.to_infix
      
      # Build result with combined powers
      result = nil
      
      # Add numeric factors first
      numeric_factors.each do |num|
        if result.nil?
          result = num.deep_clone
        else
          mult_node = ExpressionNode.new(false, "*")
          mult_node.connect(result, "L")
          mult_node.connect(num.deep_clone, "R")
          result = mult_node
        end
      end
      
      # Add symbolic factors with powers
      base_counts.each do |key, data|
        term = if data[:count] == 1
          data[:node].deep_clone
        else
          # Build x^n
          pow_node = ExpressionNode.new(false, "^")
          pow_node.connect(data[:node].deep_clone, "L")
          pow_node.connect(ExpressionNode.new(true, data[:count]), "R")
          pow_node
        end
        
        if result.nil?
          result = term
        else
          mult_node = ExpressionNode.new(false, "*")
          mult_node.connect(result, "L")
          mult_node.connect(term, "R")
          result = mult_node
        end
      end
      
      if result
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Combine repeated factors: x*x... = x^n", from: from_expr, to: node.to_infix} if steps
        changed = true
      end
    end
    
    changed
  end
  
  # Helper: collect all factors in a multiplication chain
  def collect_multiplicative_factors(node, factors)
    return unless node
    
    if node.data == '*'
      collect_multiplicative_factors(node.left, factors)
      collect_multiplicative_factors(node.right, factors)
    else
      # It's a factor
      factors << node
    end
  end
  
  # Collect like polynomial terms: x^2 + x^2 → 2*x^2, 3*x + 2*x → 5*x
  def collect_like_polynomial_terms(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively process children first
    changed |= collect_like_polynomial_terms(node.left, steps) if node.left
    changed |= collect_like_polynomial_terms(node.right, steps) if node.right
    
    # Only process addition
    return changed unless node.data == '+'
    
    left = node.left
    right = node.right
    
    # Pattern 1: x^2 + x^2 → 2*x^2
    if nodes_equal?(left, right)
      from_expr = node.to_infix
      
      # Build 2*expr
      result = ExpressionNode.new(false, "*")
      result.connect(ExpressionNode.new(true, 2), "L")
      result.connect(left.deep_clone, "R")
      
      replace_node_with(node, result)
      steps << {operation: "simplification", rule: "Collect like terms: a + a = 2*a", from: from_expr, to: node.to_infix} if steps
      changed = true
      return changed
    end
    
    # Pattern 2: a*x^n + b*x^n → (a+b)*x^n
    # Extract coefficient and term from both sides
    left_result = extract_coefficient(left)
    right_result = extract_coefficient(right)
    
    # Safety checks
    return changed unless left_result && right_result
    
    left_coef, left_term = left_result
    right_coef, right_term = right_result
    
    # Additional safety checks
    return changed unless left_coef && right_coef
    
    if left_term && right_term && nodes_equal?(left_term, right_term)
      from_expr = node.to_infix
      
      # Combine coefficients
      total_coef = left_coef + right_coef
      
      if total_coef == 0
        # Terms cancel out
        result = ExpressionNode.new(true, 0)
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Cancel: #{left_coef}*a + #{right_coef}*a = 0", from: from_expr, to: node.to_infix} if steps
        changed = true
      elsif total_coef == 1
        # Just the term
        replace_node_with(node, left_term.deep_clone)
        steps << {operation: "simplification", rule: "Collect: #{left_coef}*a + #{right_coef}*a = a", from: from_expr, to: node.to_infix} if steps
        changed = true
      elsif total_coef == -1
        # -1 * term
        result = ExpressionNode.new(false, "*")
        result.connect(ExpressionNode.new(true, -1), "L")
        result.connect(left_term.deep_clone, "R")
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Collect: #{left_coef}*a + #{right_coef}*a = -a", from: from_expr, to: node.to_infix} if steps
        changed = true
      else
        # total_coef * term
        result = ExpressionNode.new(false, "*")
        result.connect(ExpressionNode.new(true, total_coef), "L")
        result.connect(left_term.deep_clone, "R")
        replace_node_with(node, result)
        steps << {operation: "simplification", rule: "Collect: #{left_coef}*a + #{right_coef}*a = #{total_coef}*a", from: from_expr, to: node.to_infix} if steps
        changed = true
      end
    end
    
    changed
  end
  
  # Helper: extract coefficient from term (returns [coef, term])
  # Examples: 3*x → [3, x], x → [1, x], -5*x^2 → [-5, x^2]
  def extract_coefficient(node)
    return nil unless node
    
    # Safety check: ensure node has data attribute
    return [1, node] if node.isleaf
    
    if !node.isleaf && node.data == '*'
      # Check if left is numeric
      if node.left && node.left.isleaf && node.left.data.is_a?(Numeric)
        # Safety: ensure right exists
        return [1, node] unless node.right
        return [node.left.data, node.right]
      # Check if right is numeric  
      elsif node.right && node.right.isleaf && node.right.data.is_a?(Numeric)
        # Safety: ensure left exists
        return [1, node] unless node.left
        return [node.right.data, node.left]
      end
    end
    
    # No coefficient, treat as 1*node
    return [1, node]
  end
  
  # Flatten and collect terms: x^2+(2*x+x^2) → collect all terms → 2*x^2+2*x
  def flatten_and_collect_terms(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively process children first
    changed |= flatten_and_collect_terms(node.left, steps) if node.left
    changed |= flatten_and_collect_terms(node.right, steps) if node.right
    
    # Only process addition and subtraction at top level
    return changed unless node.data == '+' || node.data == '-'
    
    # Collect all additive terms (flattened)
    all_terms = []
    collect_all_additive_terms(node, all_terms)
    
    # Group by term structure (ignoring coefficient)
    term_groups = {}
    all_terms.each do |term_data|
      next unless term_data[:node]  # Safety check
      
      coef, term = extract_coefficient(term_data[:node])
      next unless coef  # Safety check
      
      term_key = term ? term.to_infix : "const"
      
      term_groups[term_key] ||= {term: term, coefficients: []}
      term_groups[term_key][:coefficients] << (term_data[:positive] ? coef : -coef)
    end
    
    # Check if any grouping happened
    if term_groups.length < all_terms.length
      from_expr = node.to_infix
      
      # Build result by summing coefficients for each term
      result_terms = []
      term_groups.each do |key, data|
        total_coef = data[:coefficients].sum
        
        next if total_coef == 0  # Skip canceled terms
        
        if key == "const"
          # It's a constant
          result_terms << {node: ExpressionNode.new(true, total_coef), positive: total_coef >= 0, coef: total_coef.abs}
        elsif total_coef == 1
          # Just the term
          next unless data[:term]  # Safety check
          result_terms << {node: data[:term].deep_clone, positive: true, coef: 1}
        elsif total_coef == -1
          # Negative term
          next unless data[:term]  # Safety check
          result_terms << {node: data[:term].deep_clone, positive: false, coef: 1}
        else
          # Coefficient * term
          next unless data[:term]  # Safety check
          mult_node = ExpressionNode.new(false, "*")
          mult_node.connect(ExpressionNode.new(true, total_coef.abs), "L")
          mult_node.connect(data[:term].deep_clone, "R")
          result_terms << {node: mult_node, positive: total_coef >= 0, coef: total_coef.abs}
        end
      end
      
      # Build the sum
      if result_terms.empty?
        result = ExpressionNode.new(true, 0)
      else
        result = build_sum_from_collected_terms(result_terms)
      end
      
      replace_node_with(node, result)
      steps << {operation: "simplification", rule: "Flatten and collect terms", from: from_expr, to: node.to_infix} if steps
      changed = true
    end
    
    changed
  end
  
  # Helper: collect all additive terms with their signs
  def collect_all_additive_terms(node, terms, positive = true)
    return unless node
    
    if node.data == '+'
      collect_all_additive_terms(node.left, terms, positive)
      collect_all_additive_terms(node.right, terms, positive)
    elsif node.data == '-'
      collect_all_additive_terms(node.left, terms, positive)
      collect_all_additive_terms(node.right, terms, !positive)
    else
      terms << {node: node, positive: positive}
    end
  end
  
  # Helper: build sum from collected terms
  def build_sum_from_collected_terms(terms)
    return ExpressionNode.new(true, 0) if terms.empty?
    
    # Separate positive and negative terms
    positive_terms = terms.select { |t| t[:positive] }
    negative_terms = terms.reject { |t| t[:positive] }
    
    # Build result
    result = nil
    
    # Add positive terms first
    positive_terms.each do |term|
      if result.nil?
        result = term[:node]
      else
        add_node = ExpressionNode.new(false, "+")
        add_node.connect(result, "L")
        add_node.connect(term[:node], "R")
        result = add_node
      end
    end
    
    # Subtract negative terms
    negative_terms.each do |term|
      if result.nil?
        # First term is negative: 0 - term
        result = ExpressionNode.new(false, "-")
        result.connect(ExpressionNode.new(true, 0), "L")
        result.connect(term[:node], "R")
      else
        sub_node = ExpressionNode.new(false, "-")
        sub_node.connect(result, "L")
        sub_node.connect(term[:node], "R")
        result = sub_node
      end
    end
    
    result || ExpressionNode.new(true, 0)
  end
  
  # Simplify power of power: (x^a)^b → x^(a*b), and (a*b)^n → a^n * b^n
  def simplify_power_of_power(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively process children first
    changed |= simplify_power_of_power(node.left, steps) if node.left
    changed |= simplify_power_of_power(node.right, steps) if node.right
    
    # Pattern 1: (base^exp1)^exp2 → base^(exp1*exp2)
    if node.data == '^' && node.left && !node.left.isleaf && node.left.data == '^'
      # node is: (base^exp1)^exp2
      base = node.left.left
      exp1 = node.left.right
      exp2 = node.right
      
      # Skip if any component is missing
      return changed unless base && exp1 && exp2
      
      from_expr = node.to_infix
      
      # Build exp1 * exp2
      new_exp = ExpressionNode.new(false, "*")
      new_exp.connect(exp1.deep_clone, "L")
      new_exp.connect(exp2.deep_clone, "R")
      
      # Build base^(exp1*exp2)
      result = ExpressionNode.new(false, "^")
      result.connect(base.deep_clone, "L")
      result.connect(new_exp, "R")
      
      replace_node_with(node, result)
      steps << {operation: "simplification", rule: "Power of power: (a^b)^c = a^(b*c)", from: from_expr, to: node.to_infix} if steps
      changed = true
    # Pattern 2: (a*b)^n → a^n * b^n
    elsif node.data == '^' && node.left && !node.left.isleaf && node.left.data == '*' &&
          node.right && node.right.isleaf && node.right.data.is_a?(Numeric)
      # node is: (a*b)^n
      a = node.left.left
      b = node.left.right
      n = node.right
      
      # Skip if any component is missing
      return changed unless a && b && n
      
      from_expr = node.to_infix
      
      # Build a^n
      a_pow = ExpressionNode.new(false, "^")
      a_pow.connect(a.deep_clone, "L")
      a_pow.connect(n.deep_clone, "R")
      
      # Build b^n
      b_pow = ExpressionNode.new(false, "^")
      b_pow.connect(b.deep_clone, "L")
      b_pow.connect(n.deep_clone, "R")
      
      # Build a^n * b^n
      result = ExpressionNode.new(false, "*")
      result.connect(a_pow, "L")
      result.connect(b_pow, "R")
      
      replace_node_with(node, result)
      steps << {operation: "simplification", rule: "Power of product: (a*b)^n = a^n * b^n", from: from_expr, to: node.to_infix} if steps
      changed = true
    end
    
    changed
  end
  
  # Multiply constants in a product: 2*x*3 → 6*x, 2*x*2 → 4*x
  def multiply_constants_in_product(node, steps = nil)
    return false unless node
    
    changed = false
    
    # Recursively process children first
    changed |= multiply_constants_in_product(node.left, steps) if node.left
    changed |= multiply_constants_in_product(node.right, steps) if node.right
    
    # Only process multiplication
    return changed unless node.data == '*'
    
    # Collect all factors
    factors = []
    collect_multiplicative_factors(node, factors)
    
    # Separate numeric and non-numeric factors
    numeric_factors = []
    non_numeric_factors = []
    
    factors.each do |factor|
      if factor.isleaf && factor.data.is_a?(Numeric)
        numeric_factors << factor.data
      else
        non_numeric_factors << factor
      end
    end
    
    # If we have multiple numeric factors, multiply them
    if numeric_factors.length > 1
      from_expr = node.to_infix
      
      # Multiply all numeric factors
      product = numeric_factors.reduce(1, :*)
      
      # Build result
      if non_numeric_factors.empty?
        # Only numeric factors
        result = ExpressionNode.new(true, product)
      else
        # Build product of non-numeric factors
        result = non_numeric_factors[0].deep_clone
        non_numeric_factors[1..-1].each do |factor|
          mult_node = ExpressionNode.new(false, "*")
          mult_node.connect(result, "L")
          mult_node.connect(factor.deep_clone, "R")
          result = mult_node
        end
        
        # Prepend the numeric coefficient
        if product != 1
          mult_node = ExpressionNode.new(false, "*")
          mult_node.connect(ExpressionNode.new(true, product), "L")
          mult_node.connect(result, "R")
          result = mult_node
        end
      end
      
      replace_node_with(node, result)
      steps << {operation: "simplification", rule: "Multiply constants: #{numeric_factors.join('*')} = #{product}", from: from_expr, to: node.to_infix} if steps
      changed = true
    end
    
    changed
  end
end


# ===== mathematical_expression.rb =====
# Mathematical Expression - Main class that combines all functionality
# Provides a clean interface for mathematical operations


class MathematicalExpression
  attr_accessor :root, :variables, :steps, :use_experimental_integration, :debug_logs
  # the independent numeric verdict on an integration result (§11), carried
  # alongside the answer instead of being buried in a debug log
  attr_accessor :verification
  
  include TreeVisualizer
  include DerivativeOperations
  include IntegrationOperations
  include ExperimentalRisch
  include VectorCalculus
  include Simplification
  include Normalizer
  include GeneralUSubstitution
  include IntegralTable
  include TrigIdentities
  include Verification
  include StrategyReporter
  include RationalIntegration
  include SpecialProducts
  include SpecialFunctions
  include SeriesExpansion
  include Lebesgue
  include IntegrationTracer
  include DefiniteIntegral
  include ResidueTheorem
  
  def initialize(expression_string, variables = {})
    @variables = variables
    @steps = []
    @use_experimental_simplification = false
    @use_experimental_integration = false
    
    if expression_string.nil? || expression_string.empty?
      @root = nil
    else
      @root = ExpressionParser.parse(expression_string)
      assign_types(@root)
    end
  end
  
  # Evaluate the expression with current variable values
  def evaluate(custom_values = nil)
    values = custom_values || @variables
    @root ? @root.evaluate(values) : 0
  end
  
  # Get string representation
  def to_s
    to_readable_string
  end
  
  # Deep clone
  def clone
    new_expr = MathematicalExpression.new("", @variables.clone)
    new_expr.root = @root ? @root.deep_clone : nil
    new_expr.use_experimental_simplification = @use_experimental_simplification
    new_expr
  end
  
  # Print information about the expression
  def inspect
    "#<MathematicalExpression: #{to_readable_string}, vars: #{@variables}>"
  end
  
  # Show complete analysis
  def analyze(output: $stderr)
    output.puts "\n" + "=" * 70
    output.puts "  🔬 EXPRESSION ANALYSIS"
    output.puts "=" * 70
    output.puts "  Formula: #{to_readable_string}"
    output.puts "  LaTeX:   #{to_latex}"
    output.puts "  Variables: #{@variables.keys.join(', ')}"
    output.puts "  Value: #{evaluate}" if @variables.any?
    output.puts "=" * 70
    output.puts
  end
  
  private
  
  def assign_types(node)
    return unless node
    
    if node.isleaf
      if node.data.is_a?(Numeric)
        node.type = "number"
      elsif @variables.key?(node.data.to_s)
        node.type = "variable"
      else
        node.type = "constant"
      end
    else
      node.type = "operator"
    end
    
    assign_types(node.left)
    assign_types(node.right)
  end
end

# Factory methods for creating expressions
class MathExpression
  def self.parse(expression_string, variables = {})
    MathematicalExpression.new(expression_string, variables)
  end
  
  def self.from_file(filename)
    lines = File.readlines(filename).map(&:chomp)
    
    formula = lines[0]
    var_names = lines[1] ? lines[1].split(' ') : []
    
    variables = {}
    if lines[2]
      values = lines[2].split(' ')
      values.each_slice(2) do |name, value|
        variables[name] = value.to_f
      end
    end
    
    MathematicalExpression.new(formula, variables)
  end
end


# ===== complex_operations.rb =====
# Complex Number Operations Module
# Converts trigonometric and hyperbolic functions to exponential form using Euler's formula
# This is a separate module that doesn't interfere with existing integration logic

module ComplexOperations
  # Convert expression to complex exponential form
  # sin(x) = (e^(ix) - e^(-ix)) / (2i)
  # cos(x) = (e^(ix) + e^(-ix)) / 2
  # sinh(x) = (e^x - e^(-x)) / 2
  # cosh(x) = (e^x + e^(-x)) / 2
  
  def self.to_complex_form(node)
    return node if node.nil? || node.isleaf
    
    case node.data
    when 'sin'
      # sin(x) = (e^(ix) - e^(-ix)) / (2i)
      convert_sin_to_exponential(node)
      
    when 'cos'
      # cos(x) = (e^(ix) + e^(-ix)) / 2
      convert_cos_to_exponential(node)
      
    when 'sinh'
      # sinh(x) = (e^x - e^(-x)) / 2
      convert_sinh_to_exponential(node)
      
    when 'cosh'
      # cosh(x) = (e^x + e^(-x)) / 2
      convert_cosh_to_exponential(node)
      
    when 'tan'
      # tan(x) = sin(x)/cos(x) = -i(e^(ix) - e^(-ix)) / (e^(ix) + e^(-ix))
      convert_tan_to_exponential(node)
      
    else
      # Recursively convert children
      result = node.deep_clone
      if result.left
        result.left = to_complex_form(result.left)
      end
      if result.right
        result.right = to_complex_form(result.right)
      end
      result
    end
  end
  
  private
  
  # sin(x) = (e^(ix) - e^(-ix)) / (2i)
  def self.convert_sin_to_exponential(node)
    arg = node.right
    
    # Build ix
    i_times_arg = ExpressionNode.new(false, "*")
    i_times_arg.connect(ExpressionNode.new(true, "i"), "L")
    i_times_arg.connect(arg.deep_clone, "R")
    
    # Build e^(ix)
    exp_ix = ExpressionNode.new(false, "exp")
    exp_ix.connect(i_times_arg, "R")
    
    # Build -ix
    minus_i_times_arg = ExpressionNode.new(false, "*")
    minus_i_times_arg.connect(ExpressionNode.new(true, "-i"), "L")
    minus_i_times_arg.connect(arg.deep_clone, "R")
    
    # Build e^(-ix)
    exp_minus_ix = ExpressionNode.new(false, "exp")
    exp_minus_ix.connect(minus_i_times_arg, "R")
    
    # Build e^(ix) - e^(-ix)
    numerator = ExpressionNode.new(false, "-")
    numerator.connect(exp_ix, "L")
    numerator.connect(exp_minus_ix, "R")
    
    # Build 2i
    two_i = ExpressionNode.new(true, "2i")
    
    # Build (e^(ix) - e^(-ix)) / (2i)
    result = ExpressionNode.new(false, "/")
    result.connect(numerator, "L")
    result.connect(two_i, "R")
    
    result
  end
  
  # cos(x) = (e^(ix) + e^(-ix)) / 2
  def self.convert_cos_to_exponential(node)
    arg = node.right
    
    # Build ix
    i_times_arg = ExpressionNode.new(false, "*")
    i_times_arg.connect(ExpressionNode.new(true, "i"), "L")
    i_times_arg.connect(arg.deep_clone, "R")
    
    # Build e^(ix)
    exp_ix = ExpressionNode.new(false, "exp")
    exp_ix.connect(i_times_arg, "R")
    
    # Build -ix
    minus_i_times_arg = ExpressionNode.new(false, "*")
    minus_i_times_arg.connect(ExpressionNode.new(true, "-i"), "L")
    minus_i_times_arg.connect(arg.deep_clone, "R")
    
    # Build e^(-ix)
    exp_minus_ix = ExpressionNode.new(false, "exp")
    exp_minus_ix.connect(minus_i_times_arg, "R")
    
    # Build e^(ix) + e^(-ix)
    numerator = ExpressionNode.new(false, "+")
    numerator.connect(exp_ix, "L")
    numerator.connect(exp_minus_ix, "R")
    
    # Build (e^(ix) + e^(-ix)) / 2
    result = ExpressionNode.new(false, "/")
    result.connect(numerator, "L")
    result.connect(ExpressionNode.new(true, 2), "R")
    
    result
  end
  
  # sinh(x) = (e^x - e^(-x)) / 2
  def self.convert_sinh_to_exponential(node)
    arg = node.right
    
    # Build e^x
    exp_x = ExpressionNode.new(false, "exp")
    exp_x.connect(arg.deep_clone, "R")
    
    # Build -x
    minus_arg = ExpressionNode.new(false, "*")
    minus_arg.connect(ExpressionNode.new(true, -1), "L")
    minus_arg.connect(arg.deep_clone, "R")
    
    # Build e^(-x)
    exp_minus_x = ExpressionNode.new(false, "exp")
    exp_minus_x.connect(minus_arg, "R")
    
    # Build e^x - e^(-x)
    numerator = ExpressionNode.new(false, "-")
    numerator.connect(exp_x, "L")
    numerator.connect(exp_minus_x, "R")
    
    # Build (e^x - e^(-x)) / 2
    result = ExpressionNode.new(false, "/")
    result.connect(numerator, "L")
    result.connect(ExpressionNode.new(true, 2), "R")
    
    result
  end
  
  # cosh(x) = (e^x + e^(-x)) / 2
  def self.convert_cosh_to_exponential(node)
    arg = node.right
    
    # Build e^x
    exp_x = ExpressionNode.new(false, "exp")
    exp_x.connect(arg.deep_clone, "R")
    
    # Build -x
    minus_arg = ExpressionNode.new(false, "*")
    minus_arg.connect(ExpressionNode.new(true, -1), "L")
    minus_arg.connect(arg.deep_clone, "R")
    
    # Build e^(-x)
    exp_minus_x = ExpressionNode.new(false, "exp")
    exp_minus_x.connect(minus_arg, "R")
    
    # Build e^x + e^(-x)
    numerator = ExpressionNode.new(false, "+")
    numerator.connect(exp_x, "L")
    numerator.connect(exp_minus_x, "R")
    
    # Build (e^x + e^(-x)) / 2
    result = ExpressionNode.new(false, "/")
    result.connect(numerator, "L")
    result.connect(ExpressionNode.new(true, 2), "R")
    
    result
  end
  
  # tan(x) = -i(e^(ix) - e^(-ix)) / (e^(ix) + e^(-ix))
  def self.convert_tan_to_exponential(node)
    arg = node.right
    
    # Convert to sin/cos first, then to exponential
    sin_node = ExpressionNode.new(false, "sin")
    sin_node.connect(arg.deep_clone, "R")
    
    cos_node = ExpressionNode.new(false, "cos")
    cos_node.connect(arg.deep_clone, "R")
    
    # Build sin/cos
    result = ExpressionNode.new(false, "/")
    result.connect(convert_sin_to_exponential(sin_node), "L")
    result.connect(convert_cos_to_exponential(cos_node), "R")
    
    result
  end
  
  # Convert from complex form back to trig (for display)
  def self.from_complex_form(node)
    # This would detect patterns like (e^(ix) - e^(-ix))/(2i) and convert back to sin(x)
    # Implementation TBD - for now just return the node
    node
  end
end


# ===== taylor_series.rb =====
# Taylor Series Expansion Module
# Generates Taylor series expansions around a point
# Separate module to avoid interfering with existing operations

module TaylorSeries
  # Generate Taylor series expansion around point a
  # f(x) = f(a) + f'(a)(x-a) + f''(a)(x-a)²/2! + f'''(a)(x-a)³/3! + ...
  
  def self.expand(node, variable, point = 0, terms = 5)
    
    series_terms = []
    current_derivative = node.deep_clone
    factorial = 1
    
    (0...terms).each do |n|
      # Calculate nth derivative
      if n > 0
        deriv_ops = DerivativeOperations.new
        current_derivative = deriv_ops.compute_derivative(current_derivative, variable, nil)
        factorial *= n
      end
      
      # Evaluate at point a
      coeff = evaluate_at_point(current_derivative, variable, point)
      
      # Build (x-a)^n term
      if n == 0
        # Just the constant term
        series_terms << {
          coefficient: coeff,
          power: 0,
          factorial: 1,
          latex: format_coefficient(coeff)
        }
      else
        x_minus_a = if point == 0
          ExpressionNode.new(true, variable)
        else
          # Build x - a
          diff = ExpressionNode.new(false, "-")
          diff.connect(ExpressionNode.new(true, variable), "L")
          diff.connect(ExpressionNode.new(true, point), "R")
          diff
        end
        
        # Build (x-a)^n
        power_term = if n == 1
          x_minus_a
        else
          pow = ExpressionNode.new(false, "^")
          pow.connect(x_minus_a, "L")
          pow.connect(ExpressionNode.new(true, n), "R")
          pow
        end
        
        series_terms << {
          coefficient: coeff,
          power: n,
          factorial: factorial,
          latex: build_term_latex(coeff, power_term, factorial, variable, point, n)
        }
      end
    end
    
    {
      terms: series_terms,
      center: point,
      latex: build_series_latex(series_terms, variable, point),
      infix: build_series_infix(series_terms, variable, point)
    }
  end
  
  # Common series expansions (hardcoded for efficiency)
  def self.known_expansions
    {
      'sin' => {
        description: "sin(x) = x - x³/3! + x⁵/5! - x⁷/7! + ...",
        pattern: ->(n) { n.odd? ? (n % 4 == 1 ? 1 : -1) : 0 }
      },
      'cos' => {
        description: "cos(x) = 1 - x²/2! + x⁴/4! - x⁶/6! + ...",
        pattern: ->(n) { n.even? ? (n % 4 == 0 ? 1 : -1) : 0 }
      },
      'exp' => {
        description: "eˣ = 1 + x + x²/2! + x³/3! + x⁴/4! + ...",
        pattern: ->(n) { 1 }
      },
      'ln' => {
        description: "ln(1+x) = x - x²/2 + x³/3 - x⁴/4 + ... (|x| < 1)",
        pattern: ->(n) { n > 0 ? ((n % 2 == 1) ? 1 : -1) : nil }
      }
    }
  end
  
  private
  
  # Evaluate expression at a specific point
  def self.evaluate_at_point(node, variable, point)
    return node.data if node.isleaf && node.data != variable
    return point if node.isleaf && node.data == variable
    
    # For now, return symbolic (would need full evaluation engine)
    # This is a simplified version
    if node.isleaf
      node.data == variable ? point : node.data
    else
      "f^(n)(#{point})"  # Symbolic notation
    end
  end
  
  def self.format_coefficient(coeff)
    if coeff.is_a?(Numeric)
      coeff.to_s
    else
      coeff.to_s
    end
  end
  
  def self.build_term_latex(coeff, power_term, factorial, variable, point, n)
    coeff_str = format_coefficient(coeff)
    fact_str = factorial > 1 ? "/#{factorial}" : ""
    
    if point == 0
      if n == 1
        "#{coeff_str}#{fact_str}#{variable}"
      else
        "#{coeff_str}#{fact_str}#{variable}^{#{n}}"
      end
    else
      if n == 1
        "#{coeff_str}#{fact_str}(#{variable}-#{point})"
      else
        "#{coeff_str}#{fact_str}(#{variable}-#{point})^{#{n}}"
      end
    end
  end
  
  def self.build_series_latex(terms, variable, point)
    latex_terms = terms.map { |t| t[:latex] }
    latex_terms.join(" + ")
  end
  
  def self.build_series_infix(terms, variable, point)
    # Build simplified infix notation
    terms.map { |t| t[:latex] }.join(" + ")
  end
end


# ===== vector_integrals.rb =====
# Vector Integrals (2D) - EXPERIMENTAL
#
# Line integrals over a parametric curve r(t) = (x(t), y(t)), t in [t0, t1]:
#   work form:       integral_C F . dr   = integral P(x,y) x'(t) + Q(x,y) y'(t) dt
#   arc-length form: integral_C f ds    = integral f(x,y) sqrt(x'^2 + y'^2) dt
# x'(t), y'(t) are SYMBOLIC derivatives from the engine; the t-integral is Simpson.
#
# For a CLOSED curve in work form, Green's theorem is verified two ways:
#   direct:  the line integral above
#   region:  double integral of curl F = dQ/dx - dP/dy over the enclosed region,
#            with SYMBOLIC partials and Monte Carlo sampling of the region
#            (point-in-polygon against the sampled curve).
# Agreement of the two values demonstrates the theorem numerically.


module VectorIntegrals
  module_function

  # extra: additional variable bindings (e.g. a swept parameter {'s' => 1.5})
  # light: reduced sampling + no visualization payload (used for parameter sweeps)
  def line_integral(xt:, yt:, t0:, t1:, form:, p_str: nil, q_str: nil, f_str: nil, n: 2000, extra: {}, light: false)
    x_expr = MathematicalExpression.new(xt)
    y_expr = MathematicalExpression.new(yt)
    raise "could not parse x(t)/y(t)" unless x_expr.root && y_expr.root
    dx_expr = x_expr.derivative('t')
    dy_expr = y_expr.derivative('t')

    a = parse_bound(t0)
    b = parse_bound(t1)
    raise "bad t range" unless a.finite? && b.finite? && b > a

    p_expr = p_str && !p_str.empty? ? MathematicalExpression.new(p_str) : nil
    q_expr = q_str && !q_str.empty? ? MathematicalExpression.new(q_str) : nil
    f_expr = f_str && !f_str.empty? ? MathematicalExpression.new(f_str) : nil

    at = lambda do |expr, t|
      expr.root.evaluate({ 't' => t }.merge(extra))
    end
    field_at = lambda do |expr, x, y|
      expr.root.evaluate({ 'x' => x, 'y' => y }.merge(extra))
    end

    integrand = lambda do |t|
      x = at.call(x_expr, t); y = at.call(y_expr, t)
      dx = at.call(dx_expr, t); dy = at.call(dy_expr, t)
      case form
      when 'work'
        p = p_expr ? field_at.call(p_expr, x, y) : 0.0
        q = q_expr ? field_at.call(q_expr, x, y) : 0.0
        p * dx + q * dy
      when 'flux'
        # outward flux: F . n ds = P dy - Q dx (counterclockwise curve)
        p = p_expr ? field_at.call(p_expr, x, y) : 0.0
        q = q_expr ? field_at.call(q_expr, x, y) : 0.0
        p * dy - q * dx
      else
        f = f_expr ? field_at.call(f_expr, x, y) : 1.0
        f * Math.sqrt(dx * dx + dy * dy)
      end
    end

    value = simpson(a, b, n) { |t| integrand.call(t) }

    # curve samples + closedness
    m = light ? 140 : 300
    pts = (0..m).map do |k|
      t = a + (b - a) * k / m.to_f
      [at.call(x_expr, t), at.call(y_expr, t)]
    end
    closed = Math.hypot(pts[0][0] - pts[-1][0], pts[0][1] - pts[-1][1]) < 1e-6

    # "method in place" formula strings for the comparison view
    direct_formula = case form
                     when 'work' then "∫ (#{p_str || '0'})·x'(t) + (#{q_str || '0'})·y'(t) dt   with x'(t) = #{dx_expr.to_readable_string}, y'(t) = #{dy_expr.to_readable_string}"
                     when 'flux' then "∫ (#{p_str || '0'})·y'(t) − (#{q_str || '0'})·x'(t) dt   with x'(t) = #{dx_expr.to_readable_string}, y'(t) = #{dy_expr.to_readable_string}"
                     else "∫ (#{f_str || '1'})·√(x'² + y'²) dt"
                     end

    form_rule = case form
                when 'work' then "Work integral: integral P dx + Q dy = integral (P x'(t) + Q y'(t)) dt"
                when 'flux' then "Outward flux: integral F.n ds = integral (P y'(t) - Q x'(t)) dt"
                else "Arc-length integral: integral f ds = integral f(x,y) sqrt(x'^2 + y'^2) dt"
                end
    result = {
      value: value,
      form: form,
      closed: closed,
      direct_formula: direct_formula,
      curve: pts.map { |p| [p[0].round(5), p[1].round(5)] },
      steps: [
        { rule: form_rule },
        { rule: "Symbolic tangent: x'(t) = #{dx_expr.to_readable_string}, y'(t) = #{dy_expr.to_readable_string}" },
        { rule: "Simpson over t in [#{a.round(4)}, #{b.round(4)}], n=#{n}: #{value.round(8)}" }
      ]
    }

    # quiver grid for the field visualization (work / flux forms)
    if %w[work flux].include?(form) && (p_expr || q_expr) && !light
      xsmin, xsmax = pts.map(&:first).minmax
      ysmin, ysmax = pts.map(&:last).minmax
      padx = (xsmax - xsmin) * 0.25 + 0.1
      pady = (ysmax - ysmin) * 0.25 + 0.1
      arrows = []
      12.times do |i|
        12.times do |j|
          x = xsmin - padx + (xsmax - xsmin + 2 * padx) * i / 11.0
          y = ysmin - pady + (ysmax - ysmin + 2 * pady) * j / 11.0
          p = p_expr ? (field_at.call(p_expr, x, y) rescue 0.0) : 0.0
          q = q_expr ? (field_at.call(q_expr, x, y) rescue 0.0) : 0.0
          arrows << [x.round(4), y.round(4), p.round(4), q.round(4)] if p.is_a?(Numeric) && q.is_a?(Numeric) && p.finite? && q.finite?
        end
      end
      result[:field] = arrows
    end

    # Green's theorem cross-check for closed curves:
    #   work form -> circulation:  ∮F.dr  = ∬ (dQ/dx - dP/dy) dA
    #   flux form -> divergence:   ∮F.n ds = ∬ (dP/dx + dQ/dy) dA
    if %w[work flux].include?(form) && closed && (p_expr || q_expr)
      curl_str = []
      if form == 'work'
        e1 = q_expr ? q_expr.derivative('x') : nil
        e2 = p_expr ? p_expr.derivative('y') : nil
        curl_str << "dQ/dx = #{e1.to_readable_string}" if e1
        curl_str << "dP/dy = #{e2.to_readable_string}" if e2
        sign2 = -1.0
      else
        e1 = p_expr ? p_expr.derivative('x') : nil
        e2 = q_expr ? q_expr.derivative('y') : nil
        curl_str << "dP/dx = #{e1.to_readable_string}" if e1
        curl_str << "dQ/dy = #{e2.to_readable_string}" if e2
        sign2 = 1.0
      end

      curl_at = lambda do |x, y|
        c = 0.0
        c += e1.root.evaluate({ 'x' => x, 'y' => y }.merge(extra)) if e1
        c += sign2 * e2.root.evaluate({ 'x' => x, 'y' => y }.merge(extra)) if e2
        c
      end

      xsmin, xsmax = pts.map(&:first).minmax
      ysmin, ysmax = pts.map(&:last).minmax
      box_area = (xsmax - xsmin) * (ysmax - ysmin)
      rng = Random.new(20_260_610)
      nmc = light ? 9_000 : 30_000
      vals = []
      darts = []
      nmc.times do |k|
        x = xsmin + rng.rand * (xsmax - xsmin)
        y = ysmin + rng.rand * (ysmax - ysmin)
        inside = point_in_polygon(x, y, pts)
        v = inside ? (curl_at.call(x, y) rescue nil) : 0.0
        vals << v if v.is_a?(Numeric) && v.finite?
        darts << [x.round(4), y.round(4), inside] if !light && k < 300
      end
      mean = vals.sum / vals.size
      var = vals.sum { |v| (v - mean)**2 } / (vals.size - 1)
      green_value = mean * box_area
      stderr = box_area * Math.sqrt(var / vals.size)

      result[:green] = {
        value: green_value,
        stderr: stderr,
        curl: curl_str.join(',  '),
        match: (green_value - value).abs <= 3 * stderr + 1e-3,
        darts: darts
      }
      result[:steps] << { rule: form == 'work' ?
        "Green's theorem (circulation): closed curve, so the same value must equal the double integral of curl F = dQ/dx - dP/dy over the enclosed region" :
        "Divergence theorem in the plane: closed curve, so the outward flux must equal the double integral of div F = dP/dx + dQ/dy over the enclosed region" }
      result[:steps] << { rule: "#{curl_str.join(', ')}; MC over the region (n=#{vals.size}): #{green_value.round(6)} ± #{stderr.round(6)}" }
      result[:steps] << { rule: "Direct line integral #{value.round(6)} vs region integral #{green_value.round(6)} — #{(green_value - value).abs <= 3 * stderr + 1e-3 ? 'AGREE (theorem verified numerically)' : 'disagree (check the inputs)'}" }
    end

    result
  end

  # Sweep a named parameter over [from, to]: run a light evaluation per value and
  # collect both methods' results, so the client can plot value(s) vs green(s)
  # and show the theorem holds AS A FUNCTION of the parameter, not just at a point.
  def sweep_line_integral(args, name, from, to, steps_n = 11)
    steps_n = steps_n.to_i.clamp(3, 25)
    (0...steps_n).map do |k|
      s = from + (to - from) * k / (steps_n - 1.0)
      r = line_integral(**args, extra: { name => s }, light: true)
      { s: s.round(5), value: r[:value].round(6),
        green: r[:green] ? r[:green][:value].round(6) : nil }
    end
  end

  def parse_bound(s)
    v = MathematicalExpression.new(s.to_s).evaluate({})
    v.to_f
  end

  def simpson(a, b, n)
    n += 1 if n.odd?
    h = (b - a) / n.to_f
    sum = yield(a) + yield(b)
    (1...n).each { |i| sum += yield(a + i * h) * (i.odd? ? 4 : 2) }
    sum * h / 3.0
  end

  # ray-casting point-in-polygon against the sampled curve
  def point_in_polygon(x, y, pts)
    inside = false
    j = pts.size - 1
    pts.each_with_index do |pi, i|
      xi, yi = pi
      xj, yj = pts[j]
      if (yi > y) != (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi
        inside = !inside
      end
      j = i
    end
    inside
  end
end


# ===== surface_integrals.rb =====
# Surface Integrals (3D) - EXPERIMENTAL
#
# Parametric surface r(u,v) = (x(u,v), y(u,v), z(u,v)) on [u0,u1]x[v0,v1].
# Tangents r_u, r_v are SYMBOLIC derivatives; n = r_u x r_v.
#
#   scalar:  integral_S f dS      = integral f(r) |n| du dv
#   flux:    integral_S F . dS    = integral F(r) . n du dv
#   stokes:  for a surface with boundary edge: the boundary line integral
#            ∮_∂S F.dr must equal the flux of curl F (SYMBOLIC partials) — both computed.
#   gauss:   for a closed surface bounding a preset solid: the flux of F must
#            equal the Monte Carlo volume integral of div F (SYMBOLIC) — both computed.
#
# (u,v) integration: midpoint rule on an N x N grid.


module SurfaceIntegrals
  module_function

  def surface_integral(xs:, ys:, zs:, u0:, u1:, v0:, v1:, mode:,
                       p_str: nil, q_str: nil, r_str: nil, f_str: nil,
                       solid: nil, boundary_edge: 'u1', n: 110)
    sx = MathematicalExpression.new(xs)
    sy = MathematicalExpression.new(ys)
    sz = MathematicalExpression.new(zs)
    raise "could not parse x/y/z(u,v)" unless sx.root && sy.root && sz.root
    d = { xu: sx.derivative('u'), xv: sx.derivative('v'),
          yu: sy.derivative('u'), yv: sy.derivative('v'),
          zu: sz.derivative('u'), zv: sz.derivative('v') }

    a_u = bound(u0); b_u = bound(u1); a_v = bound(v0); b_v = bound(v1)

    fp = p_str && !p_str.empty? ? MathematicalExpression.new(p_str) : nil
    fq = q_str && !q_str.empty? ? MathematicalExpression.new(q_str) : nil
    fr = r_str && !r_str.empty? ? MathematicalExpression.new(r_str) : nil
    ff = f_str && !f_str.empty? ? MathematicalExpression.new(f_str) : nil

    pos = ->(u, v) { tv = { 'u' => u, 'v' => v }; [sx.root.evaluate(tv), sy.root.evaluate(tv), sz.root.evaluate(tv)] }
    normal = lambda do |u, v|
      tv = { 'u' => u, 'v' => v }
      ru = [d[:xu].root.evaluate(tv), d[:yu].root.evaluate(tv), d[:zu].root.evaluate(tv)]
      rv = [d[:xv].root.evaluate(tv), d[:yv].root.evaluate(tv), d[:zv].root.evaluate(tv)]
      cross(ru, rv)
    end
    field = lambda do |x, y, z|
      tv = { 'x' => x, 'y' => y, 'z' => z }
      [fp ? fp.root.evaluate(tv) : 0.0, fq ? fq.root.evaluate(tv) : 0.0, fr ? fr.root.evaluate(tv) : 0.0]
    end

    du = (b_u - a_u) / n
    dv = (b_v - a_v) / n
    value = 0.0
    n.times do |i|
      u = a_u + (i + 0.5) * du
      n.times do |j|
        v = a_v + (j + 0.5) * dv
        nn = normal.call(u, v)
        if mode == 'scalar'
          x, y, z = pos.call(u, v)
          fv = ff ? ff.root.evaluate({ 'x' => x, 'y' => y, 'z' => z }) : 1.0
          value += fv * norm(nn) * du * dv
        else
          x, y, z = pos.call(u, v)
          value += dot(field.call(x, y, z), nn) * du * dv
        end
      end
    end

    result = { value: value, mode: mode, steps: [
      { rule: mode == 'scalar' ? "Scalar surface integral: integral f |r_u x r_v| du dv" : "Flux: integral F . (r_u x r_v) du dv" },
      { rule: "Symbolic tangents, e.g. r_u = (#{d[:xu].to_readable_string}, #{d[:yu].to_readable_string}, #{d[:zu].to_readable_string})" },
      { rule: "Midpoint grid #{n}x#{n} over (u,v): #{value.round(8)}" }
    ] }

    # ---- Stokes: boundary work vs flux of curl ----
    if mode == 'stokes'
      raise "stokes needs the field P,Q,R" unless fp || fq || fr
      curl = symbolic_curl(fp, fq, fr)
      curl_flux = 0.0
      n.times do |i|
        u = a_u + (i + 0.5) * du
        n.times do |j|
          v = a_v + (j + 0.5) * dv
          x, y, z = pos.call(u, v)
          tv = { 'x' => x, 'y' => y, 'z' => z }
          c = curl[:exprs].map { |e| e ? e.root.evaluate(tv) : 0.0 }
          curl_flux += dot(c, normal.call(u, v)) * du * dv
        end
      end

      # boundary line integral along the chosen parameter edge
      m = 1600
      boundary_work = 0.0
      bpts = []
      (0...m).each do |k|
        s0 = k.to_f / m
        s1 = (k + 1.0) / m
        pA = edge_point(pos, boundary_edge, a_u, b_u, a_v, b_v, s0)
        pB = edge_point(pos, boundary_edge, a_u, b_u, a_v, b_v, s1)
        mid = pA.zip(pB).map { |w| (w[0] + w[1]) / 2.0 }
        fmid = field.call(*mid)
        seg = pB.zip(pA).map { |w| w[0] - w[1] }
        boundary_work += dot(fmid, seg)
        bpts << pA.map { |w| w.round(4) } if (k % (m / 240)).zero?
      end

      result[:value] = curl_flux
      result[:stokes] = {
        curl_flux: curl_flux,
        boundary_work: boundary_work,
        curl: curl[:text],
        match: (curl_flux - boundary_work).abs <= [5e-3, (curl_flux.abs + boundary_work.abs) * 5e-3].max
      }
      result[:boundary] = bpts
      result[:steps] << { rule: "Stokes: ∮_∂S F.dr = ∬_S (curl F).dS; curl F = #{curl[:text]}" }
      result[:steps] << { rule: "curl flux through S = #{curl_flux.round(6)}; boundary work = #{boundary_work.round(6)} — #{result[:stokes][:match] ? 'AGREE: Stokes verified' : 'disagree'}" }
    end

    # ---- Gauss: flux vs MC volume integral of div ----
    if mode == 'gauss'
      raise "gauss needs the field P,Q,R" unless fp || fq || fr
      raise "gauss needs a preset solid (sphere/ellipsoid) for the inside test" unless solid
      divs = []
      div_text = []
      { 'x' => fp, 'y' => fq, 'z' => fr }.each do |var, e|
        next unless e
        de = e.derivative(var)
        divs << de
        div_text << "d#{var.upcase}/d#{var} = #{de.to_readable_string}"
      end
      inside = solid_inside_test(solid)
      bbox = solid[:bbox]
      rng = Random.new(20_260_610)
      vol_box = (bbox[1] - bbox[0]) * (bbox[3] - bbox[2]) * (bbox[5] - bbox[4])
      nmc = 40_000
      vals = []
      darts = []
      nmc.times do |k|
        x = bbox[0] + rng.rand * (bbox[1] - bbox[0])
        y = bbox[2] + rng.rand * (bbox[3] - bbox[2])
        z = bbox[4] + rng.rand * (bbox[5] - bbox[4])
        ins = inside.call(x, y, z)
        v = ins ? divs.sum { |e| e.root.evaluate({ 'x' => x, 'y' => y, 'z' => z }) } : 0.0
        vals << v if v.is_a?(Numeric) && v.finite?
        darts << [x.round(3), y.round(3), z.round(3), ins] if k < 400
      end
      mean = vals.sum / vals.size
      var = vals.sum { |w| (w - mean)**2 } / (vals.size - 1)
      div_volume = mean * vol_box
      stderr = vol_box * Math.sqrt(var / vals.size)
      result[:gauss] = {
        flux: value,
        div_volume: div_volume,
        stderr: stderr,
        div: div_text.join(',  '),
        match: (value - div_volume).abs <= 3 * stderr + [5e-3, value.abs * 5e-3].max,
        darts: darts
      }
      result[:steps] << { rule: "Gauss/divergence: ∬_S F.dS = ∭_V div F dV; #{div_text.join(', ')}" }
      result[:steps] << { rule: "surface flux = #{value.round(6)}; MC volume integral = #{div_volume.round(6)} ± #{stderr.round(6)} — #{result[:gauss][:match] ? 'AGREE: Gauss verified' : 'disagree'}" }
    end

    # ---- mesh + arrows for the 3D visualization ----
    gm = 36
    mesh = (0..gm).map do |i|
      u = a_u + (b_u - a_u) * i / gm
      (0..gm).map do |j|
        v = a_v + (b_v - a_v) * j / gm
        pos.call(u, v).map { |w| w.round(4) }
      end
    end
    arrows = []
    if fp || fq || fr
      6.times do |i|
        6.times do |j|
          u = a_u + (b_u - a_u) * (i + 0.5) / 6
          v = a_v + (b_v - a_v) * (j + 0.5) / 6
          x, y, z = pos.call(u, v)
          fv = field.call(x, y, z)
          arrows << [x, y, z, fv[0], fv[1], fv[2]].map { |w| w.round(4) }
        end
      end
    end
    result[:mesh] = mesh
    result[:arrows] = arrows
    result
  end

  def bound(s)
    MathematicalExpression.new(s.to_s).evaluate({}).to_f
  end

  def cross(a, b)
    [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]
  end

  def dot(a, b) = a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
  def norm(a) = Math.sqrt(dot(a, a))

  def edge_point(pos, edge, a_u, b_u, a_v, b_v, s)
    case edge
    when 'u1' then pos.call(b_u, a_v + (b_v - a_v) * s)
    when 'u0' then pos.call(a_u, a_v + (b_v - a_v) * (1 - s))
    when 'v1' then pos.call(a_u + (b_u - a_u) * (1 - s), b_v)
    else           pos.call(a_u + (b_u - a_u) * s, a_v)
    end
  end

  # curl F = (Ry - Qz, Pz - Rx, Qx - Py), all partials symbolic
  def symbolic_curl(fp, fq, fr)
    dpart = ->(e, var) { e ? e.derivative(var) : nil }
    ry = dpart.call(fr, 'y'); qz = dpart.call(fq, 'z')
    pz = dpart.call(fp, 'z'); rx = dpart.call(fr, 'x')
    qx = dpart.call(fq, 'x'); py = dpart.call(fp, 'y')
    pair = lambda do |a, b|
      return nil if a.nil? && b.nil?
      s = "#{a ? a.to_readable_string : '0'} - #{b ? b.to_readable_string : '0'}"
      expr = MathematicalExpression.new("(#{a ? a.to_readable_string : '0'}) - (#{b ? b.to_readable_string : '0'})")
      [expr, s]
    end
    c1 = pair.call(ry, qz); c2 = pair.call(pz, rx); c3 = pair.call(qx, py)
    { exprs: [c1&.first, c2&.first, c3&.first],
      text: "(#{c1 ? c1[1] : '0'}, #{c2 ? c2[1] : '0'}, #{c3 ? c3[1] : '0'})" }
  end

  def solid_inside_test(solid)
    case solid[:type]
    when 'sphere'
      rr = solid[:r].to_f
      ->(x, y, z) { x * x + y * y + z * z <= rr * rr }
    when 'ellipsoid'
      a = solid[:a].to_f; b = solid[:b].to_f; c = solid[:c].to_f
      ->(x, y, z) { (x / a)**2 + (y / b)**2 + (z / c)**2 <= 1.0 }
    else
      raise "unknown solid #{solid[:type]}"
    end
  end
end


# ===== leibniz_rule.rb =====
# Leibniz Rule / 1D Reynolds Transport - EXPERIMENTAL
#
#   d/dt  integral_{a(t)}^{b(t)} f(x,t) dx
#     =  f(b(t),t) b'(t)  -  f(a(t),t) a'(t)  +  integral_{a(t)}^{b(t)} df/dt dx
#
# (boundary motion terms + bulk change — the 1D Reynolds transport theorem).
# Both sides are computed independently: the LHS by central-differencing the
# integral in t, the RHS from SYMBOLIC a'(t), b'(t), df/dt. Agreement is the check.
# Also returns animation frames of the moving domain.


module LeibnizRule
  module_function

  def moving_domain_derivative(f_str:, a_str:, b_str:, t_val:, frames: 48)
    f = MathematicalExpression.new(f_str)        # f(x, t)
    a = MathematicalExpression.new(a_str)        # a(t)
    b = MathematicalExpression.new(b_str)        # b(t)
    raise "could not parse f/a/b" unless f.root && a.root && b.root
    da = a.derivative('t')
    db = b.derivative('t')
    df_dt = f.derivative('t')

    t = t_val.to_f
    f_at  = ->(x, tt) { f.root.evaluate({ 'x' => x, 't' => tt }) }
    a_at  = ->(tt) { a.root.evaluate({ 't' => tt }) }
    b_at  = ->(tt) { b.root.evaluate({ 't' => tt }) }
    integral_at = lambda do |tt|
      lo = a_at.call(tt)
      hi = b_at.call(tt)
      simpson(lo, hi, 600) { |x| f_at.call(x, tt) }
    end

    # LHS: numeric d/dt of the integral
    h = 1e-4
    lhs = (integral_at.call(t + h) - integral_at.call(t - h)) / (2 * h)

    # RHS: boundary terms (symbolic bound derivatives) + bulk term (symbolic df/dt)
    av = a_at.call(t)
    bv = b_at.call(t)
    dav = da.root.evaluate({ 't' => t })
    dbv = db.root.evaluate({ 't' => t })
    boundary = f_at.call(bv, t) * dbv - f_at.call(av, t) * dav
    bulk = simpson(av, bv, 600) { |x| df_dt.root.evaluate({ 'x' => x, 't' => t }) }
    rhs = boundary + bulk

    # animation frames over a t-window
    t0 = t - 1.5
    t1 = t + 1.5
    all_bounds = []
    fr = (0...frames).map do |k|
      tt = t0 + (t1 - t0) * k / (frames - 1.0)
      lo = a_at.call(tt)
      hi = b_at.call(tt)
      all_bounds << lo << hi
      { t: tt.round(4), a: lo.round(5), b: hi.round(5), integral: integral_at.call(tt).round(6) }
    end
    xmin = all_bounds.min - 0.5
    xmax = all_bounds.max + 0.5
    nx = 90
    fr.each do |frame|
      xs = (0..nx).map { |k| xmin + (xmax - xmin) * k / nx }
      frame[:xs] = xs.map { |x| x.round(4) }
      frame[:fs] = xs.map do |x|
        v = (f_at.call(x, frame[:t]) rescue nil)
        v.is_a?(Numeric) && v.finite? && v.abs < 1e6 ? v.round(5) : nil
      end
    end

    {
      lhs: lhs,
      rhs: rhs,
      boundary_term: boundary,
      bulk_term: bulk,
      match: (lhs - rhs).abs <= [1e-4, (lhs.abs + rhs.abs) * 1e-3].max,
      derivatives: "a'(t) = #{da.to_readable_string},  b'(t) = #{db.to_readable_string},  df/dt = #{df_dt.to_readable_string}",
      frames: fr,
      t: t,
      steps: [
        { rule: "Leibniz / Reynolds (1D): d/dt integral_a(t)^b(t) f dx = f(b,t)b' - f(a,t)a' + integral df/dt dx" },
        { rule: "Symbolic: #{da.to_readable_string} and #{db.to_readable_string} for the moving bounds, df/dt = #{df_dt.to_readable_string}" },
        { rule: "boundary motion = #{boundary.round(8)}, bulk change = #{bulk.round(8)}, RHS total = #{rhs.round(8)}" },
        { rule: "LHS (numeric d/dt of the integral) = #{lhs.round(8)} — #{(lhs - rhs).abs <= 1e-3 ? 'AGREE: theorem verified' : 'disagree, check inputs'}" }
      ]
    }
  end

  def simpson(a, b, n)
    return 0.0 if (b - a).abs < 1e-15
    n += 1 if n.odd?
    h = (b - a) / n.to_f
    sum = yield(a) + yield(b)
    (1...n).each { |i| sum += yield(a + i * h) * (i.odd? ? 4 : 2) }
    sum * h / 3.0
  end
end


# ===== leibniz_higher.rb =====
# Higher-dimensional Leibniz rule / transport theorem (2D area, 3D volume) - EXPERIMENTAL
#
#   d/dt  integral_{Omega(t)} f dV  =  integral_Omega df/dt dV  +  integral_{dOmega} f (v_b . n) dS
#
# Omega(t) is an ellipse (2D) / ellipsoid (3D) with semi-axes A(t) = diag(a_i(t))
# and center c(t). Flow map phi_t(u) = c(t) + A(t) u sends the FIXED unit ball B
# onto Omega(t), with det(Dphi) = prod a_i(t). Therefore
#
#   I(t) = integral_Omega f dV = det A(t) * integral_B f(phi_t(u), t) du,
#   d/dt I = det A * integral_B df/dt du                 (= bulk term, integral_Omega df/dt dV)
#          + (det A)' integral_B f du + det A integral_B grad f . phi_t' du   (= boundary motion).
#
# The boundary-motion term equals integral_{dOmega} f (v_b.n) dS by the divergence
# theorem, but is computed here from SYMBOLIC (det A)', grad f and phi_t' over the
# fixed unit ball (common random numbers) -- far more robust than surface quadrature
# for a general deformation. LHS is an independent central difference of I(t).


module LeibnizHigher
  module_function

  # dim: 2 or 3. axes/center: arrays of expression strings in t.
  def transport(dim:, f_str:, axes:, center:, t_val:, n_mc: 7000)
    raise "dim must be 2 or 3" unless [2, 3].include?(dim)
    f = MathematicalExpression.new(f_str)
    raise "could not parse f" unless f.root
    coords = dim == 2 ? %w[x y] : %w[x y z]

    ax_e = axes.first(dim).map { |s| MathematicalExpression.new(s.to_s) }
    c_e  = center.first(dim).map { |s| MathematicalExpression.new(s.to_s.empty? ? '0' : s.to_s) }
    raise "could not parse axes/center" if (ax_e + c_e).any? { |e| e.root.nil? }
    dax = ax_e.map { |e| e.derivative('t') }
    dcc = c_e.map { |e| e.derivative('t') }
    dft = f.derivative('t')
    dfc = coords.map { |v| f.derivative(v) }

    # fixed unit-ball samples (common random numbers across all t)
    rng = Random.new(20_260_610)
    samples = []
    while samples.size < n_mc
      u = Array.new(dim) { rng.rand * 2 - 1 }
      samples << u if u.sum { |w| w * w } <= 1.0
    end
    unit_measure = dim == 2 ? Math::PI : 4.0 / 3 * Math::PI

    ev = ->(e, t) { e.root.evaluate({ 't' => t }) }
    bind = lambda do |u, t, a, c|
      h = { 't' => t }
      coords.each_with_index { |cv, i| h[cv] = c[i] + a[i] * u[i] }
      h
    end

    integral = lambda do |t|
      a = ax_e.map { |e| ev.call(e, t) }
      c = c_e.map { |e| ev.call(e, t) }
      det = a.reduce(:*)
      s = samples.sum { |u| f.root.evaluate(bind.call(u, t, a, c)) }
      det * unit_measure * (s / samples.size)
    end

    t = t_val.to_f
    h = 1e-3
    lhs = (integral.call(t + h) - integral.call(t - h)) / (2 * h)

    a  = ax_e.map { |e| ev.call(e, t) }
    c  = c_e.map  { |e| ev.call(e, t) }
    da = dax.map  { |e| ev.call(e, t) }
    dc = dcc.map  { |e| ev.call(e, t) }
    det = a.reduce(:*)
    detp = (0...dim).sum { |i| da[i] * (0...dim).reject { |j| j == i }.map { |j| a[j] }.reduce(1, :*) }

    mean = ->(blk) { samples.sum { |u| blk.call(u) } / samples.size }
    pt   = ->(u) { bind.call(u, t, a, c) }

    bulk    = det * unit_measure * mean.call(->(u) { dft.root.evaluate(pt.call(u)) })
    int_f   = unit_measure * mean.call(->(u) { f.root.evaluate(pt.call(u)) })
    grad_t  = unit_measure * mean.call(->(u) {
      hh = pt.call(u)
      (0...dim).sum { |i| dfc[i].root.evaluate(hh) * (dc[i] + da[i] * u[i]) }
    })
    boundary = detp * int_f + det * grad_t
    rhs = bulk + boundary

    # functional sweep + geometry track for the animation
    t0 = t - 1.5; t1 = t + 1.5
    sweep = (0...15).map do |k|
      tt = t0 + (t1 - t0) * k / 14.0
      l = (integral.call(tt + h) - integral.call(tt - h)) / (2 * h)
      aa = ax_e.map { |e| ev.call(e, tt) }
      cc = c_e.map  { |e| ev.call(e, tt) }
      dda = dax.map { |e| ev.call(e, tt) }
      ddc = dcc.map { |e| ev.call(e, tt) }
      dt2 = aa.reduce(:*)
      dtp2 = (0...dim).sum { |i| dda[i] * (0...dim).reject { |j| j == i }.map { |j| aa[j] }.reduce(1, :*) }
      bk = dt2 * unit_measure * (samples.sum { |u| dft.root.evaluate(bind.call(u, tt, aa, cc)) } / samples.size)
      iff = unit_measure * (samples.sum { |u| f.root.evaluate(bind.call(u, tt, aa, cc)) } / samples.size)
      gt = unit_measure * (samples.sum { |u|
        hh = bind.call(u, tt, aa, cc)
        (0...dim).sum { |i| dfc[i].root.evaluate(hh) * (ddc[i] + dda[i] * u[i]) }
      } / samples.size)
      { t: tt.round(4), lhs: l.round(5), rhs: (bk + dtp2 * iff + dt2 * gt).round(5) }
    end
    geo = (0...60).map do |k|
      tt = t0 + (t1 - t0) * k / 59.0
      { t: tt.round(4), axes: ax_e.map { |e| ev.call(e, tt).round(5) }, center: c_e.map { |e| ev.call(e, tt).round(5) } }
    end

    axis_names = dim == 2 ? %w[ax ay] : %w[ax ay az]
    {
      dim: dim, t: t, lhs: lhs, rhs: rhs, bulk_term: bulk, boundary_term: boundary,
      match: (lhs - rhs).abs <= [5e-3, (lhs.abs + rhs.abs) * 2.5e-2].max,
      derivatives: axis_names.each_with_index.map { |nm, i| "#{nm}'(t) = #{dax[i].to_readable_string}" }.join(',  ') +
                   ",  df/dt = #{dft.to_readable_string}",
      sweep: sweep, geometry: geo,
      steps: [
        { rule: "Leibniz #{dim}D / transport: d/dt #{dim == 2 ? '∬' : '∭'}_Ω f #{dim == 2 ? 'dA' : 'dV'} = #{dim == 2 ? '∬' : '∭'}_Ω ∂f/∂t #{dim == 2 ? 'dA' : 'dV'} + #{dim == 2 ? '∮' : '∬'}_∂Ω f (v_b·n) #{dim == 2 ? 'ds' : 'dS'}" },
        { rule: "Flow map φ_t(u) = c(t) + A(t)u maps the fixed unit #{dim == 2 ? 'disk' : 'ball'}; det A = #{axis_names.join('·')}, with SYMBOLIC #{dax.map.with_index { |e, i| "#{axis_names[i]}'=#{e.to_readable_string}" }.join(', ')}" },
        { rule: "bulk (∂f/∂t) = #{bulk.round(6)}, boundary motion = #{boundary.round(6)}, RHS = #{rhs.round(6)}" },
        { rule: "LHS (independent d/dt of the integral) = #{lhs.round(6)} — #{(lhs - rhs).abs <= [5e-3, (lhs.abs + rhs.abs) * 2.5e-2].max ? 'AGREE: theorem verified' : 'disagree'}" }
      ]
    }
  end
end


# ===== reynolds_transport.rb =====
# Reynolds Transport Theorem (3D) - EXPERIMENTAL
#
#   d/dt  integral_{Omega(t)} f(x,y,z,t) dV
#     =  integral_{Omega(t)} df/dt dV   +   integral_{dOmega(t)} f (v_b . n) dS
#
# (bulk change + boundary motion). Omega(t) is a deforming/translating sphere:
# radius R(t) and center (c(t), 0, 0), both given as expressions in t whose
# derivatives R'(t), c'(t) are SYMBOLIC. On the sphere, v_b . n = R'(t) + c'(t) n_x.
#
# LHS uses common-random-number Monte Carlo (the same unit-ball samples are
# rescaled at t +/- h, so the central difference is smooth). RHS = MC bulk term
# + a (theta,phi) surface quadrature. Both sides are also swept over a t-window
# so the client can plot LHS(t) vs RHS(t) and show they coincide as functions.


module ReynoldsTransport
  module_function

  def transport(f_str:, r_str:, cx_str: '0', t_val:, n_mc: 6000)
    f = MathematicalExpression.new(f_str)            # f(x, y, z, t)
    r = MathematicalExpression.new(r_str)            # R(t)
    cx = MathematicalExpression.new(cx_str.to_s.empty? ? '0' : cx_str)
    raise "could not parse f/R/c" unless f.root && r.root && cx.root
    df_dt = f.derivative('t')
    dr = r.derivative('t')
    dcx = cx.derivative('t')

    # fixed unit-ball samples (common random numbers across all t)
    rng = Random.new(20_260_610)
    ball = []
    while ball.size < n_mc
      x = rng.rand * 2 - 1; y = rng.rand * 2 - 1; z = rng.rand * 2 - 1
      ball << [x, y, z] if x * x + y * y + z * z <= 1.0
    end

    r_at  = ->(t) { r.root.evaluate({ 't' => t }) }
    cx_at = ->(t) { cx.root.evaluate({ 't' => t }) }
    vol_integral = lambda do |expr, t|
      rr = r_at.call(t); c = cx_at.call(t)
      vol = 4.0 / 3 * Math::PI * rr**3
      s = 0.0
      ball.each { |u| s += expr.root.evaluate({ 'x' => c + rr * u[0], 'y' => rr * u[1], 'z' => rr * u[2], 't' => t }) }
      s / ball.size * vol
    end
    surface_term = lambda do |t|
      rr = r_at.call(t); c = cx_at.call(t)
      drv = dr.root.evaluate({ 't' => t })
      dcv = dcx.root.evaluate({ 't' => t })
      nth = 28; nph = 56
      s = 0.0
      nth.times do |i|
        th = Math::PI * (i + 0.5) / nth
        nph.times do |j|
          ph = 2 * Math::PI * (j + 0.5) / nph
          nx = Math.sin(th) * Math.cos(ph); ny = Math.sin(th) * Math.sin(ph); nz = Math.cos(th)
          fv = f.root.evaluate({ 'x' => c + rr * nx, 'y' => rr * ny, 'z' => rr * nz, 't' => t })
          vn = drv + dcv * nx
          s += fv * vn * rr * rr * Math.sin(th)
        end
      end
      s * (Math::PI / nth) * (2 * Math::PI / nph)
    end

    both_sides = lambda do |t|
      h = 1e-3
      lhs = (vol_integral.call(f, t + h) - vol_integral.call(f, t - h)) / (2 * h)
      bulk = vol_integral.call(df_dt, t)
      surf = surface_term.call(t)
      [lhs, bulk, surf]
    end

    t = t_val.to_f
    lhs, bulk, surf = both_sides.call(t)
    rhs = bulk + surf

    # sweep both sides over a t-window for the functional comparison
    t0 = t - 1.5; t1 = t + 1.5
    nsw = 17
    sweep = (0...nsw).map do |k|
      tt = t0 + (t1 - t0) * k / (nsw - 1.0)
      l, b, sf = both_sides.call(tt)
      { t: tt.round(4), lhs: l.round(6), rhs: (b + sf).round(6) }
    end
    # geometry track for the deforming-sphere animation (client scales a unit mesh)
    ngeo = 60
    geo = (0...ngeo).map do |k|
      tt = t0 + (t1 - t0) * k / (ngeo - 1.0)
      { t: tt.round(4), r: r_at.call(tt).round(5), cx: cx_at.call(tt).round(5) }
    end

    {
      t: t, lhs: lhs, rhs: rhs, bulk_term: bulk, surface_term: surf,
      match: (lhs - rhs).abs <= [5e-3, (lhs.abs + rhs.abs) * 2e-2].max,
      derivatives: "R'(t) = #{dr.to_readable_string},  c'(t) = #{dcx.to_readable_string},  df/dt = #{df_dt.to_readable_string}",
      sweep: sweep,
      geometry: geo,
      steps: [
        { rule: "Reynolds transport: d/dt ∭_Ω f dV = ∭_Ω df/dt dV + ∬_∂Ω f (v_b.n) dS" },
        { rule: "Deforming sphere: R(t) = #{r.to_readable_string}, center x = #{cx.to_readable_string}; on the boundary v_b.n = R'(t) + c'(t) n_x with SYMBOLIC R' = #{dr.to_readable_string}" },
        { rule: "bulk (∭ df/dt) = #{bulk.round(6)}, boundary motion (∬ f v_n dS) = #{surf.round(6)}, RHS = #{rhs.round(6)}" },
        { rule: "LHS (common-random-number MC d/dt) = #{lhs.round(6)} — #{(lhs - rhs).abs <= [5e-3, (lhs.abs + rhs.abs) * 2e-2].max ? 'AGREE: theorem verified' : 'disagree'}" }
      ]
    }
  end
end


# ===== sindy.rb =====
# SINDy - Sparse Identification of Nonlinear Dynamics  (Brunton, Proctor & Kutz, PNAS 2016)
#
# Recovers the governing differential equation from trajectory data alone:
#
#     X_dot  =  Theta(X) * Xi ,      Xi sparse
#
# Theta(X) is a library of candidate functions evaluated along the trajectory
# (monomials up to a chosen total degree, optionally sin/cos), and Xi is found
# by STLSQ - sequential thresholded least squares: solve the least-squares
# problem, zero every coefficient below lambda, re-solve on the survivors,
# repeat to convergence. Sparsity is the prior that turns a mere fit into a
# candidate *physical law*.
#
# The "truth" trajectory is itself produced by this engine: each preset system
# is a set of ordinary expression strings, parsed and evaluated by
# MathematicalExpression, so a user-supplied ODE works exactly like a preset.
#
# HONESTY - the discovered model is judged only by oracles the regression never
# saw:
#   1. vector-field agreement:  ||f_disc(X) - f_true(X)|| / ||f_true(X)|| over
#      every sample. This is the verdict-carrying check: it is meaningful even
#      for chaotic systems.
#   2. re-simulation: RK4-integrate the DISCOVERED model from the same initial
#      condition and compare trajectories.
# For a chaotic system (Lorenz) two nearby trajectories separate exponentially
# even when the model is perfect, so the trajectory check is scored only over a
# short horizon (~1 Lyapunov time) and is reported as corroboration, never as
# the verdict. Claiming otherwise would be exactly the kind of confidently-wrong
# result this engine refuses to emit.


module Sindy
  module_function

  # Preset systems. rhs/x0 define the truth; `truth` gives the exact coefficients
  # in library-term naming so the UI can show a term-by-term comparison.
  SYSTEMS = {
    'linear2d' => {
      label: 'Damped linear oscillator', vars: %w[x y],
      rhs: ['-0.1*x + 2*y', '-2*x - 0.1*y'],
      truth: [{ 'x' => -0.1, 'y' => 2.0 }, { 'x' => -2.0, 'y' => -0.1 }],
      x0: [2.0, 0.0], dt: 0.01, t_end: 12.0, thr: 0.05, poly: 3, trig: false
    },
    'cubic2d' => {
      label: 'Cubic oscillator', vars: %w[x y],
      rhs: ['-0.1*x^3 + 2*y^3', '-2*x^3 - 0.1*y^3'],
      truth: [{ 'x^3' => -0.1, 'y^3' => 2.0 }, { 'x^3' => -2.0, 'y^3' => -0.1 }],
      x0: [2.0, 0.0], dt: 0.01, t_end: 12.0, thr: 0.05, poly: 3, trig: false
    },
    'vanderpol' => {
      label: 'Van der Pol oscillator', vars: %w[x y],
      rhs: ['y', '2*(1 - x^2)*y - x'],
      truth: [{ 'y' => 1.0 }, { 'x' => -1.0, 'y' => 2.0, 'x^2*y' => -2.0 }],
      x0: [1.0, 0.5], dt: 0.005, t_end: 14.0, thr: 0.05, poly: 3, trig: false
    },
    'pendulum' => {
      label: 'Damped pendulum (needs sin)', vars: %w[x y],
      rhs: ['y', '-sin(x) - 0.2*y'],
      truth: [{ 'y' => 1.0 }, { 'sin(x)' => -1.0, 'y' => -0.2 }],
      x0: [2.0, 0.0], dt: 0.01, t_end: 15.0, thr: 0.05, poly: 2, trig: true
    },
    'lorenz' => {
      label: 'Lorenz attractor (chaotic)', vars: %w[x y z],
      rhs: ['10*(y - x)', 'x*(28 - z) - y', 'x*y - 8/3*z'],
      truth: [{ 'x' => -10.0, 'y' => 10.0 },
              { 'x' => 28.0, 'y' => -1.0, 'x*z' => -1.0 },
              { 'z' => -8.0 / 3.0, 'x*y' => 1.0 }],
      x0: [-8.0, 8.0, 27.0], dt: 0.004, t_end: 10.0, thr: 0.1, poly: 2, trig: false,
      chaotic: true, check_t: 2.0
    }
  }.freeze

  # ---------------------------------------------------------------- entry point

  # system: preset key, or 'custom' with rhs:/vars:/x0: supplied.
  def discover(system: 'lorenz', noise: 0.0, threshold: nil, poly_order: nil,
               use_trig: nil, rhs: nil, vars: nil, x0: nil, dt: nil, t_end: nil)
    spec = build_spec(system, rhs, vars, x0, dt, t_end, poly_order, use_trig, threshold)
    n    = spec[:vars].size

    # 1. truth trajectory, generated by the engine itself
    f_true = compile_rhs(spec[:rhs], spec[:vars])
    ts, xs = simulate(f_true, spec[:x0], spec[:dt], spec[:t_end])
    raise 'simulation diverged - check the equations or initial condition' if xs.empty?

    # 2. measurement: optional noise, as a fraction of each variable's spread
    noise = noise.to_f.clamp(0.0, 0.5)
    measured = add_noise(xs, noise, n)

    # 3. derivatives + states. A Savitzky-Golay window (quadratic fit) both
    #    smooths and differentiates; wider window when the data is noisy.
    w = noise <= 0 ? 2 : [2 + (noise * 300).round, 25].min
    dx    = sg_derivative(measured, spec[:dt], w, noise <= 0)
    x_fit = noise <= 0 ? trim(measured, w) : sg_smooth(measured, w)
    x_ref = trim(xs, w) # noiseless states, used only for scoring

    # 4. candidate library
    lib   = build_library(spec[:vars], spec[:poly], spec[:trig])
    theta = lib.map { |term| x_fit.map { |s| term[:f].call(s) } }

    # 5. sparse regression, one column of X_dot at a time
    xi = (0...n).map do |j|
      stlsq(theta, dx.map { |d| d[j] }, spec[:thr])
    end
    raise 'regression failed (singular library) - try a lower polynomial order' if xi.any?(&:nil?)

    # 6. symbolic result
    equations = (0...n).map do |j|
      expr = format_equation(lib, xi[j], spec[:thr] * 0.5)
      { variable: spec[:vars][j], expression: expr,
        truth: spec[:rhs][j],
        terms: active_terms(lib, xi[j], spec[:truth] ? spec[:truth][j] : nil, spec[:thr] * 0.5) }
    end
    parse_ok = equations.all? { |e| !ExpressionParser.parse(e[:expression]).nil? rescue false }

    # 7. verification against oracles the regression never saw
    f_disc = discovered_field(lib, xi)
    field_err = field_error(f_disc, f_true, x_ref, spec[:vars])
    check_t   = spec[:check_t] || spec[:t_end]
    _, rec    = simulate(f_disc, spec[:x0], spec[:dt], check_t)
    traj_err  = trajectory_error(rec, xs, rec.size)
    structure = spec[:truth] ? structure_match?(equations, spec[:truth]) : nil

    verdict = verdict_for(field_err, structure)
    active  = equations.sum { |e| e[:terms].size }

    {
      system: system, label: spec[:label], variables: spec[:vars],
      noise: noise, threshold: spec[:thr], poly_order: spec[:poly], use_trig: spec[:trig],
      library: lib.map { |t| t[:name] }, library_size: lib.size,
      equations: equations,
      active_terms: active,
      sparsity: "#{active} of #{lib.size * n} candidate coefficients non-zero",
      structure_match: structure,
      parse_ok: parse_ok,
      verification: {
        method: 'vector-field agreement over all samples (verdict) + RK4 re-simulation of the discovered model (corroboration)',
        field_rel_error: field_err,
        trajectory_rel_error: traj_err,
        check_horizon: check_t,
        chaotic: !!spec[:chaotic],
        passed: verdict[:passed],
        verdict: verdict[:text]
      },
      trajectory: pack_trajectory(ts, xs, measured, rec, spec[:vars], noise),
      steps: build_steps(spec, lib, equations, field_err, traj_err, verdict, w, noise)
    }
  end

  # ------------------------------------------------------------------- spec

  def build_spec(system, rhs, vars, x0, dt, t_end, poly, trig, thr)
    if system.to_s == 'custom'
      v = (vars && !vars.empty?) ? vars.map(&:to_s) : %w[x y]
      r = rhs or raise 'custom mode needs one right-hand side per variable'
      raise 'need one equation per variable' unless r.size == v.size
      { label: 'Custom system', vars: v, rhs: r.map(&:to_s), truth: nil,
        x0: (x0 && x0.size == v.size ? x0.map(&:to_f) : Array.new(v.size) { |i| i.zero? ? 1.0 : 0.5 }),
        dt: (dt || 0.01).to_f, t_end: (t_end || 12.0).to_f,
        thr: (thr || 0.05).to_f, poly: (poly || 3).to_i, trig: trig.nil? ? true : !!trig }
    else
      s = SYSTEMS[system.to_s] or raise "unknown system '#{system}'"
      s.merge(
        thr: (thr || s[:thr]).to_f,
        poly: (poly || s[:poly]).to_i,
        trig: trig.nil? ? s[:trig] : !!trig,
        dt: (dt || s[:dt]).to_f, t_end: (t_end || s[:t_end]).to_f
      )
    end
  end

  # Parse each RHS once; return a lambda state -> derivative vector.
  def compile_rhs(rhs, vars)
    roots = rhs.map do |s|
      e = MathematicalExpression.new(s.to_s)
      raise "could not parse '#{s}'" unless e.root
      e.root
    end
    lambda do |state|
      env = {}
      vars.each_with_index { |v, i| env[v] = state[i] }
      roots.map { |r| r.evaluate(env) }
    end
  end

  # ------------------------------------------------------------- numerics

  def simulate(f, x0, dt, t_end)
    steps = (t_end / dt).round
    ts = [0.0]
    xs = [x0.dup]
    s = x0.dup
    steps.times do |i|
      k1 = f.call(s)
      k2 = f.call(axpy(s, k1, dt / 2))
      k3 = f.call(axpy(s, k2, dt / 2))
      k4 = f.call(axpy(s, k3, dt))
      s = s.each_with_index.map { |v, j| v + dt / 6.0 * (k1[j] + 2 * k2[j] + 2 * k3[j] + k4[j]) }
      return [ts, xs] unless s.all? { |v| v.finite? && v.abs < 1e8 }
      ts << (i + 1) * dt
      xs << s
    end
    [ts, xs]
  end

  def axpy(s, k, h)
    s.each_with_index.map { |v, j| v + h * k[j] }
  end

  def add_noise(xs, noise, n)
    return xs.map(&:dup) if noise <= 0
    rng = Random.new(20_260_621)
    scale = (0...n).map do |j|
      col = xs.map { |s| s[j] }
      mu = col.sum / col.size
      Math.sqrt(col.sum { |v| (v - mu)**2 } / col.size)
    end
    xs.map do |s|
      s.each_with_index.map { |v, j| v + noise * scale[j] * gaussian(rng) }
    end
  end

  def gaussian(rng)
    u1 = rng.rand.clamp(1e-12, 1.0)
    Math.sqrt(-2.0 * Math.log(u1)) * Math.cos(2 * Math::PI * rng.rand)
  end

  # Savitzky-Golay first derivative: fit a quadratic on a symmetric window;
  # by odd/even symmetry the slope term decouples, giving weights s / sum(s^2).
  # Accuracy is O(dt^2), which on clean data is the dominant error source - so
  # for noise-free data we instead use the 4th-order 5-point stencil, whose
  # O(dt^4) truncation lets the coefficients come back at full precision.
  def sg_derivative(xs, dt, w, high_order = false)
    return five_point_derivative(xs, dt) if high_order
    denom = (-w..w).sum { |s| s * s } * dt
    (w...(xs.size - w)).map do |i|
      (0...xs[i].size).map do |j|
        (-w..w).sum { |s| s * xs[i + s][j] } / denom
      end
    end
  end

  # f'(x) = (-f[i+2] + 8f[i+1] - 8f[i-1] + f[i-2]) / (12 dt),  error O(dt^4)
  def five_point_derivative(xs, dt)
    (2...(xs.size - 2)).map do |i|
      (0...xs[i].size).map do |j|
        (-xs[i + 2][j] + 8 * xs[i + 1][j] - 8 * xs[i - 1][j] + xs[i - 2][j]) / (12.0 * dt)
      end
    end
  end

  def sg_smooth(xs, w)
    span = 2 * w + 1
    (w...(xs.size - w)).map do |i|
      (0...xs[i].size).map do |j|
        (-w..w).sum { |s| xs[i + s][j] } / span.to_f
      end
    end
  end

  def trim(xs, w)
    xs[w...(xs.size - w)].map(&:dup)
  end

  # ------------------------------------------------------------- library

  def build_library(vars, poly_order, use_trig)
    terms = [{ name: '1', f: ->(_s) { 1.0 } }]
    (1..poly_order).each do |d|
      (0...vars.size).to_a.repeated_combination(d).each do |combo|
        counts = Hash.new(0)
        combo.each { |i| counts[i] += 1 }
        name = counts.keys.sort.map { |i| counts[i] == 1 ? vars[i] : "#{vars[i]}^#{counts[i]}" }.join('*')
        terms << { name: name, f: ->(s) { combo.reduce(1.0) { |p, i| p * s[i] } } }
      end
    end
    if use_trig
      vars.each_with_index do |v, i|
        terms << { name: "sin(#{v})", f: ->(s) { Math.sin(s[i]) } }
        terms << { name: "cos(#{v})", f: ->(s) { Math.cos(s[i]) } }
      end
    end
    terms
  end

  # ------------------------------------------------- sparse regression (STLSQ)

  def stlsq(theta, target, lambda_thr, iters = 12)
    m = theta.size
    xi = lstsq(theta, target)
    return nil unless xi
    active = (0...m).to_a
    iters.times do
      keep = active.select { |j| xi[j].abs >= lambda_thr }
      return Array.new(m, 0.0) if keep.empty?
      break if keep == active
      active = keep
      sol = lstsq(active.map { |j| theta[j] }, target)
      return nil unless sol
      xi = Array.new(m, 0.0)
      active.each_with_index { |j, k| xi[j] = sol[k] }
    end
    xi
  end

  # Least squares via normal equations with a scale-relative ridge for safety.
  def lstsq(cols, target)
    m = cols.size
    a = Array.new(m) { Array.new(m, 0.0) }
    b = Array.new(m, 0.0)
    m.times do |i|
      (i...m).each do |j|
        v = dot(cols[i], cols[j])
        a[i][j] = v
        a[j][i] = v
      end
      b[i] = dot(cols[i], target)
    end
    max_diag = (0...m).map { |i| a[i][i].abs }.max
    return nil if max_diag.nil? || max_diag == 0
    m.times { |i| a[i][i] += 1e-12 * max_diag }
    gauss_solve(a, b)
  end

  def dot(u, v)
    s = 0.0
    u.each_with_index { |val, i| s += val * v[i] }
    s
  end

  def gauss_solve(a, b)
    n = b.size
    m = a.map(&:dup)
    r = b.dup
    n.times do |k|
      piv = (k...n).max_by { |i| m[i][k].abs }
      return nil if m[piv][k].abs < 1e-13
      m[k], m[piv] = m[piv], m[k]
      r[k], r[piv] = r[piv], r[k]
      ((k + 1)...n).each do |i|
        f = m[i][k] / m[k][k]
        next if f == 0.0
        (k...n).each { |j| m[i][j] -= f * m[k][j] }
        r[i] -= f * r[k]
      end
    end
    x = Array.new(n, 0.0)
    (n - 1).downto(0) do |i|
      s = r[i] - ((i + 1)...n).sum { |j| m[i][j] * x[j] }
      x[i] = s / m[i][i]
    end
    return nil unless x.all? { |v| v.finite? }
    x
  end

  # ------------------------------------------------------------ presentation

  def format_equation(lib, xi, tol)
    parts = []
    lib.each_with_index do |term, j|
      c = xi[j]
      next if c.abs < tol
      parts << [c, term[:name]]
    end
    return '0' if parts.empty?
    parts.each_with_index.map do |(c, name), k|
      sign = c.negative? ? (k.zero? ? '-' : ' - ') : (k.zero? ? '' : ' + ')
      mag = fmt_num(c.abs)
      name == '1' ? "#{sign}#{mag}" : "#{sign}#{mag}*#{name}"
    end.join
  end

  def active_terms(lib, xi, truth, tol)
    lib.each_with_index.filter_map do |term, j|
      next if xi[j].abs < tol
      { name: term[:name], coefficient: round6(xi[j]),
        true_coefficient: truth ? (truth[term[:name]] ? round6(truth[term[:name]]) : nil) : nil,
        spurious: truth ? !truth.key?(term[:name]) : nil }
    end
  end

  def fmt_num(v)
    return '0' if v.abs < 1e-12
    r = v.round
    (v - r).abs < 1e-9 ? r.to_i.to_s : v.round(4).to_s
  end

  def round6(v)
    (v * 1e6).round / 1e6
  end

  # --------------------------------------------------------------- verification

  # Evaluate the DISCOVERED model: a plain dot product of library and coefficients.
  def discovered_field(lib, xi)
    lambda do |state|
      xi.map do |col|
        s = 0.0
        lib.each_with_index { |term, j| s += col[j] * term[:f].call(state) unless col[j] == 0.0 }
        s
      end
    end
  end

  # The verdict check: does the discovered vector field agree with the true one
  # at every sampled state? Independent of the regression's own residual.
  def field_error(f_disc, f_true, states, _vars)
    num = 0.0
    den = 0.0
    states.each do |s|
      a = f_disc.call(s)
      b = f_true.call(s)
      b.each_index do |j|
        d = a[j] - b[j]
        num += d * d
        den += b[j] * b[j]
      end
    end
    return Float::INFINITY if den <= 0
    Math.sqrt(num / den)
  end

  def trajectory_error(rec, truth, len)
    n = [len, rec.size, truth.size].min
    return Float::INFINITY if n < 2
    num = 0.0
    den = 0.0
    (0...n).each do |i|
      rec[i].each_index do |j|
        d = rec[i][j] - truth[i][j]
        num += d * d
        den += truth[i][j] * truth[i][j]
      end
    end
    return Float::INFINITY if den <= 0
    Math.sqrt(num / den)
  end

  def structure_match?(equations, truth)
    equations.each_with_index.all? do |eq, j|
      found = eq[:terms].map { |t| t[:name] }.sort
      found == truth[j].keys.sort
    end
  end

  def verdict_for(field_err, structure)
    if field_err < 1e-6 && structure != false
      { passed: true, text: 'EXACT - sparse structure and coefficients recovered to numerical precision (relative error < 1e-6)' }
    elsif field_err < 0.01 && structure != false
      { passed: true, text: 'RECOVERED - correct sparse structure, coefficients within 1%' }
    elsif field_err < 0.10
      { passed: true, text: 'APPROXIMATE - close vector field, but coefficients are off; treat as a fit, not a law' }
    else
      { passed: false, text: 'FAILED - the discovered model does not reproduce the true dynamics' }
    end
  end

  # ------------------------------------------------------------------ output

  def pack_trajectory(ts, xs, measured, rec, vars, noise)
    stride = [(xs.size / 600.0).ceil, 1].max
    idx = (0...xs.size).step(stride).to_a
    {
      variables: vars,
      t: idx.map { |i| ts[i].round(4) },
      truth: idx.map { |i| xs[i].map { |v| v.round(5) } },
      measured: noise > 0 ? idx.map { |i| measured[i].map { |v| v.round(5) } } : nil,
      recovered: rec.each_slice(stride).map { |sl| sl.first.map { |v| v.round(5) } }
    }
  end

  def build_steps(spec, lib, equations, field_err, traj_err, verdict, w, noise)
    steps = []
    steps << { rule: "SINDy: assume X_dot = Theta(X)*Xi with Xi sparse; library = #{lib.size} candidates " \
                     "(monomials to degree #{spec[:poly]}#{spec[:trig] ? ' + sin/cos' : ''}) over #{spec[:vars].join(', ')}" }
    steps << { rule: "Data: RK4 trajectory of the true system, dt = #{spec[:dt]}, T = #{spec[:t_end]}" \
                     "#{noise > 0 ? ", with #{(noise * 100).round(1)}% measurement noise" : ' (noise-free)'}" }
    steps << { rule: noise > 0 ?
      "Derivatives estimated by Savitzky-Golay (quadratic, window #{2 * w + 1}) - widened to suppress noise amplification" :
      'Derivatives estimated by the 4th-order 5-point stencil (O(dt^4)) - clean data, so truncation is the only error to beat' }
    steps << { rule: "STLSQ: least squares, then zero every |coefficient| < #{spec[:thr]} and re-solve on the survivors, to convergence" }
    equations.each do |eq|
      steps << { rule: "d#{eq[:variable]}/dt = #{eq[:expression]}" }
    end
    steps << { rule: "Verify (independent): vector-field relative error = #{fmt_err(field_err)}; " \
                     "re-simulation relative error over #{spec[:check_t] || spec[:t_end]}s = #{fmt_err(traj_err)}" }
    if spec[:chaotic]
      steps << { rule: 'Chaotic system: trajectories separate exponentially even for a perfect model, ' \
                       'so the trajectory check is corroboration only - the vector field carries the verdict' }
    end
    steps << { rule: verdict[:text] }
    steps
  end

  def fmt_err(e)
    return 'inf' unless e.finite?
    e < 1e-10 ? '<1e-10' : format('%.3g', e)
  end
end


# ===== pade.rb =====
# Pade approximants - rational approximation [L/M] from Taylor coefficients.
#
#   f(x) ~ P(u)/Q(u),  u = x - c,  deg P = L, deg Q = M, Q(0) = 1,
#   chosen so that Q(u) * T(u) - P(u) = O(u^(L+M+1))   (T = Taylor series of f).
#
# The denominator solves the M x M Toeplitz system
#   sum_{j=1..M} c_{k-j} q_j = -c_k        for k = L+1 .. L+M   (c_i = 0, i < 0)
# and the numerator follows directly:  p_i = sum_{j=0..min(i,M)} q_j c_{i-j}.
#
# Why bother: a Taylor polynomial is blind to poles - it diverges outside the
# circle through the nearest singularity. The Pade denominator PUTS the poles
# back: [3/3] of tan(x) has a Q-root at sqrt(5/2) = 1.5811, within 0.7% of the
# true pole pi/2, and keeps tracking f far beyond the Taylor radius. For a
# rational f the approximant is EXACT (the table "closes").
#
# HONESTY - three independent checks, none of which trust the construction:
#   1. the defining relation's residuals (construction check),
#   2. numeric agreement with f itself near the center and across the window,
#   3. every real pole of Q is tested against f: if f does not actually blow
#      up there it is labelled a SPURIOUS (Froissart) pole, a well-known Pade
#      artifact - shown, never hidden.


module Pade
  module_function

  MAX_ORDER = 12  # L + M cap: symbolic derivative trees grow fast beyond this

  def approximate(f_str:, variable: 'x', center: 0.0, l: 3, m: 3, half_width: nil)
    l = l.to_i.clamp(0, MAX_ORDER)
    m = m.to_i.clamp(1, MAX_ORDER)
    raise "L + M = #{l + m} exceeds #{MAX_ORDER} (symbolic derivatives get too large)" if l + m > MAX_ORDER
    center = center.to_f
    n = l + m

    f = MathematicalExpression.new(f_str.to_s)
    raise "could not parse '#{f_str}'" unless f.root

    # --- 1. Taylor coefficients c_0..c_n at the center (symbolic derivatives) --
    c = taylor_coefficients(f, variable, center, n)

    # --- 2. denominator: M x M Toeplitz solve ---------------------------------
    a = Array.new(m) { |r| Array.new(m) { |j| coef(c, l + 1 + r - (j + 1)) } }
    b = Array.new(m) { |r| -coef(c, l + 1 + r) }
    q_tail = pd_solve(a, b)
    unless q_tail
      odd  = c.each_with_index.all? { |v, i| i.even? ? v.abs < 1e-12 : true }
      even = c.each_with_index.all? { |v, i| i.odd?  ? v.abs < 1e-12 : true }
      hint = odd || even
      msg = "the Pade system is singular for [#{l}/#{m}] at this center"
      msg += hint ? " (the function has odd/even symmetry - try L,M with matching parity, e.g. [#{l + 1}/#{m}] or [#{l}/#{m + 1}])" : ' - try a different L/M'
      raise msg
    end
    q = [1.0] + q_tail

    # --- 3. numerator ---------------------------------------------------------
    p_ = (0..l).map { |i| (0..[i, m].min).sum { |j| q[j] * coef(c, i - j) } }

    # --- 4. defining-relation residuals (construction check) ------------------
    residuals = (0..n).map do |k|
      lhs = (0..[k, m].min).sum { |j| q[j] * coef(c, k - j) }
      k <= l ? (lhs - p_[k]).abs : lhs.abs
    end
    c_scale = c.map(&:abs).max
    c_scale = 1.0 if c_scale.zero?

    # --- 5. poles of Q (Durand-Kerner), reported in x-coordinates -------------
    roots = pd_roots(q)
    poles = roots.map do |z|
      { re: (center + z.real).round(10), im: z.imaginary.round(10), modulus: z.abs.round(10) }
    end.sort_by { |pp| pp[:modulus] }

    # --- 6. sampling window ---------------------------------------------------
    hw = (half_width || default_half_width(poles)).to_f
    hw = 4.0 unless hw.finite? && hw > 0
    real_poles = poles.select { |pp| pp[:im].abs < 1e-8 * [pp[:modulus], 1].max }
    samples = sample_curves(f, variable, center, c, p_, q, hw)
    base_mag = base_magnitude(samples)

    # --- 7. verification against f itself (the oracle) ------------------------
    ver = verify(f, variable, center, c, p_, q, hw, real_poles, residuals, c_scale, base_mag)

    {
      variable: variable, center: center, l: l, m: m,
      numerator: poly_string(p_, variable, center),
      denominator: poly_string(q, variable, center),
      taylor_string: poly_string(c, variable, center),
      coefficients: { taylor: c.map { |v| round12(v) }, p: p_.map { |v| round12(v) }, q: q.map { |v| round12(v) } },
      poles: poles.map { |pp| pp.merge(spurious: real_poles.include?(pp) ? !genuine_pole?(f, variable, pp[:re], center, base_mag) : nil) },
      half_width: hw,
      samples: samples,
      verification: ver,
      steps: build_steps(f_str, l, m, center, c, poles, ver, variable)
    }
  end

  # ---------------------------------------------------------------- internals

  def coef(c, i)
    i.negative? ? 0.0 : (c[i] || 0.0)
  end

  # evaluate -> a real Float, or nil. Guards the two ways the engine can hand
  # back something unusable: Complex (from '^' on a negative base with a
  # fractional exponent - Complex is Numeric, has finite?/abs, but no round)
  # and non-finite values. Every numeric consumer below goes through this.
  def real_eval(f, variable, x)
    v = begin
      f.evaluate({ variable => x })
    rescue StandardError
      nil
    end
    return nil unless v.is_a?(Numeric)
    return nil if v.is_a?(Complex) && v.imaginary.abs > 1e-12
    v = v.is_a?(Complex) ? v.real : v.to_f
    v.finite? ? v : nil
  end

  def taylor_coefficients(f, variable, center, n)
    c = []
    d = f
    fact = 1.0
    (0..n).each do |k|
      fact *= k if k > 0
      v = real_eval(d, variable, center)
      if v.nil?
        raise "f^(#{k}) is not finite (or not real) at the center #{variable} = #{center} - Pade needs an analytic point (shift the center)"
      end
      c << v / fact
      d = d.derivative(variable) if k < n
    end
    c
  end

  # Gaussian elimination with partial pivoting; nil if (near-)singular.
  def pd_solve(a, b)
    nn = b.size
    m = a.map(&:dup)
    r = b.dup
    scale = m.flatten.map(&:abs).max
    return nil if scale.nil? || scale.zero?
    nn.times do |k|
      piv = (k...nn).max_by { |i| m[i][k].abs }
      return nil if m[piv][k].abs < 1e-12 * scale
      m[k], m[piv] = m[piv], m[k]
      r[k], r[piv] = r[piv], r[k]
      ((k + 1)...nn).each do |i|
        f = m[i][k] / m[k][k]
        next if f.zero?
        (k...nn).each { |j| m[i][j] -= f * m[k][j] }
        r[i] -= f * r[k]
      end
    end
    x = Array.new(nn, 0.0)
    (nn - 1).downto(0) do |i|
      x[i] = (r[i] - ((i + 1)...nn).sum { |j| m[i][j] * x[j] }) / m[i][i]
    end
    x.all?(&:finite?) ? x : nil
  end

  # Durand-Kerner on q0 + q1 u + ... + qm u^m (complex roots, in u).
  # Trailing coefficients can vanish (odd/even f => the table closes early),
  # so trim them first - but ONLY the solver-noise zeros (~1e-16 relative).
  # A genuinely tiny leading coefficient means genuinely DISTANT poles
  # (q_m ~ R^-m for roots at radius R); trimming those would silently delete
  # real pole structure, so the tolerance must sit well below "small but real".
  def pd_roots(q)
    q = q.dup
    qmax = q.map(&:abs).max
    q.pop while q.size > 1 && q.last.abs < 1e-13 * qmax
    qm = q.last
    return [] if q.size < 2 || qm.abs < 1e-300
    mono = q.map { |v| v / qm }
    deg = q.size - 1
    # start the iterates on a circle of the geometric-mean root radius
    # |q0/qm|^(1/deg): unit-circle starts fail to reach distant roots
    # (poles at |u| = 100 simply never converged in the iteration budget)
    r0 = mono[0].abs**(1.0 / deg)
    r0 = 1.0 unless r0.finite? && r0 > 1e-12
    z = (0...deg).map { |k| a = 0.7 + 2 * Math::PI * k / deg; r0 * Complex(Math.cos(a), Math.sin(a)) }
    eval_p = ->(x) { mono.each_with_index.reduce(Complex(0, 0)) { |s, (cv, i)| s + cv * x**i } }
    200.times do
      done = true
      z = z.each_with_index.map do |zi, i|
        denom = z.each_with_index.reduce(Complex(1, 0)) { |pr, (zj, j)| j == i ? pr : pr * (zi - zj) }
        step = denom.abs < 1e-300 ? Complex(0, 0) : eval_p.call(zi) / denom
        done &&= step.abs < 1e-13 * [zi.abs, 1].max
        zi - step
      end
      break if done
    end
    z
  end

  def default_half_width(poles)
    return 4.0 if poles.empty?
    nearest = poles.first[:modulus]
    return 4.0 if nearest < 1e-9
    real = poles.find { |pp| pp[:im].abs < 1e-8 * [pp[:modulus], 1].max }
    real ? 1.6 * nearest : 2.2 * nearest
  end

  def horner(cs, u)
    cs.reverse.reduce(0.0) { |s, cv| s * u + cv }
  end

  def sample_curves(f, variable, center, c, p_, q, hw)
    xs, yf, yt, yp = [], [], [], []
    241.times do |i|
      x = center - hw + 2.0 * hw * i / 240
      u = x - center
      xs << x.round(8)
      fv = real_eval(f, variable, x)
      yf << (fv && fv.abs < 1e6 ? fv.round(8) : nil)
      tv = horner(c, u)
      yt << (tv.finite? && tv.abs < 1e6 ? tv.round(8) : nil)
      qv = horner(q, u)
      pv = qv.abs < 1e-9 || !qv.finite? ? Float::NAN : horner(p_, u) / qv
      yp << (pv.finite? && pv.abs < 1e6 ? pv.round(8) : nil)
    end
    { xs: xs, f: yf, taylor: yt, pade: yp }
  end

  # Does f actually misbehave near the predicted pole? The Q-root only
  # approximates the true singularity (tan: 1.5811 vs pi/2), so search a
  # neighbourhood scaled to the pole distance. A point where f is undefined
  # (NaN / domain error / complex) counts as singular evidence - that is what
  # "f fails to exist here" means numerically. The blow-up test is RELATIVE to
  # f's typical magnitude on the window: an absolute threshold would call the
  # genuine pole of 1e-8*tan(x) spurious and every Q-root of 1000+g(x) genuine.
  def genuine_pole?(f, variable, x_pole, center, base_mag)
    r = [0.05 * (x_pole - center).abs, 0.03].max
    vmax = 0.0
    (0..80).each do |i|
      x = x_pole - r + 2.0 * r * i / 80
      v = real_eval(f, variable, x)
      return true if v.nil?   # undefined / complex near the pole: singular evidence
      vmax = [vmax, v.abs].max
    end
    vmax > 100 * [base_mag, 1e-12].max
  end

  # typical |f| on the plot window (median of the finite samples) - the
  # yardstick that keeps every pole/exactness test amplitude-invariant
  def base_magnitude(samples)
    vals = samples[:f].compact.map(&:abs).sort
    vals.empty? ? 1e-12 : vals[vals.size / 2]
  end

  def verify(f, variable, center, c, p_, q, hw, real_poles, residuals, c_scale, base_mag)
    res_max = residuals.max / c_scale
    near_err = 0.0
    41.times do |i|
      nhw = [0.1, 0.05 * hw].min
      x = center - nhw + 2.0 * nhw * i / 40
      u = x - center
      fv = real_eval(f, variable, x)
      next unless fv
      qv = horner(q, u)
      next if qv.abs < 1e-9 || !qv.finite?
      pv = horner(p_, u) / qv
      err = (pv - fv).abs / [fv.abs, 0.01 * base_mag, 1e-12].max
      near_err = [near_err, err].max if err.finite?
    end
    errs_t, errs_p = [], []
    201.times do |i|
      x = center - hw + 2.0 * hw * i / 200
      u = x - center
      next if real_poles.any? { |pp| (x - pp[:re]).abs < 0.04 * hw }
      fv = real_eval(f, variable, x)
      next unless fv && fv.abs < 1e6
      # amplitude-invariant scale: relative to f locally, floored by a small
      # fraction of f's TYPICAL magnitude - never by the absolute constant 1.0,
      # which silently turned the test into absolute error for small-amplitude f
      sc = [fv.abs, 0.01 * base_mag, 1e-12].max
      et = (horner(c, u) - fv).abs / sc
      errs_t << et if et.finite?
      qv = horner(q, u)
      if qv.abs > 1e-9 && qv.finite?
        ep = (horner(p_, u) / qv - fv).abs / sc
        errs_p << ep if ep.finite?
      end
    end
    med = ->(arr) { arr.empty? ? Float::INFINITY : arr.sort[arr.size / 2] }
    med_t = med.call(errs_t)
    med_p = med.call(errs_p)
    spurious = real_poles.count { |pp| !genuine_pole?(f, variable, pp[:re], center, base_mag) }
    exact = med_p < 1e-9 && errs_p.size > 50
    passed = near_err < 1e-6 && res_max < 1e-8
    # every claim states exactly what was tested - an agreement over the sampled
    # window is evidence of exactness, not a theorem about f
    verdict =
      if !passed then 'FAILED - the approximant does not reproduce f near the center'
      elsif exact then "EXACT on the sampled window (median relative error #{fmt_e(med_p)} over |#{variable} - #{fmt_num(center)}| <= #{fmt_num(hw)}) - consistent with f being rational of this degree"
      elsif spurious.positive? then "GOOD with #{spurious} SPURIOUS pole(s) - a Froissart artifact of the finite table, flagged below"
      else "GOOD - reproduces f near the center to #{fmt_e(near_err)}, and the denominator carries the analytic structure"
      end
    { passed: passed, verdict: verdict, exact: exact,
      residual_max: fmt_e(res_max), near_center_rel_error: fmt_e(near_err),
      median_rel_error_taylor: fmt_e(med_t), median_rel_error_pade: fmt_e(med_p),
      improvement: (med_p.positive? && med_t.finite? && med_p.finite? ? (med_t / [med_p, 1e-16].max).round(1) : nil),
      spurious_poles: spurious }
  end

  # pretty "1 - 2*x^2/5"-style string with rationalised coefficients
  def poly_string(cs, variable, center)
    u = center.zero? ? variable : "(#{variable} - #{fmt_num(center)})"
    parts = []
    cs.each_with_index do |v, i|
      next if v.abs < 1e-11
      mag = fmt_num(v.abs)
      term = if i.zero?
               mag
             elsif mag == '1'
               pow_str(u, i)
             else
               "#{mag}*#{pow_str(u, i)}"
             end
      parts << [(v.negative? ? '-' : '+'), term]
    end
    return '0' if parts.empty?
    parts.each_with_index.map { |(sg, t), k| k.zero? ? (sg == '-' ? "-#{t}" : t) : " #{sg} #{t}" }.join
  end

  def pow_str(u, i)
    i == 1 ? u : "#{u}^#{i}"
  end

  def fmt_num(v)
    return '0' if v.abs < 1e-11
    r = v.round
    return r.to_i.to_s if (v - r).abs < 1e-9 * [v.abs, 1].max
    (1..9999).each do |den|
      num = (v * den).round
      return "#{num}/#{den}" if num.abs < 1e15 && (v - num.to_f / den).abs < 1e-9 * [v.abs, 1].max
    end
    v.round(6).to_s
  end

  def fmt_e(v)
    return 'inf' unless v.finite?
    v < 1e-14 ? '<1e-14' : format('%.3g', v)
  end

  def round12(v)
    # (v * 1e12).round overflows to Infinity for |v| > ~1.8e296, and no-arg
    # Float#round on Infinity raises - huge coefficients pass through raw
    return v unless v.finite? && v.abs < 1e15
    (v * 1e12).round / 1e12
  end

  def build_steps(f_str, l, m, center, c, poles, ver, variable)
    steps = []
    steps << { rule: "Pade [#{l}/#{m}]: find P/Q (deg #{l}/deg #{m}, Q(0)=1) with Q*Taylor - P = O(u^#{l + m + 1}), u = #{variable} - #{fmt_num(center)}" }
    steps << { rule: "Taylor coefficients c_0..c_#{l + m} from #{l + m} successive SYMBOLIC derivatives evaluated at the center: #{c.first(6).map { |v| fmt_num(v) }.join(', ')}#{c.size > 6 ? ', ...' : ''}" }
    steps << { rule: "Denominator: #{m}x#{m} Toeplitz system solved by Gaussian elimination with partial pivoting; numerator by direct convolution" }
    real = poles.select { |pp| pp[:im].abs < 1e-8 }
    if real.any?
      steps << { rule: "Q has real roots at #{real.map { |pp| fmt_num(pp[:re]) }.join(', ')} - the approximant's poles; a Taylor polynomial can never do this" }
    elsif poles.any?
      steps << { rule: "Q's roots are complex (nearest |root| = #{fmt_num(poles.first[:modulus])}) - they mark the convergence radius that limits the polynomial but not the rational" }
    end
    steps << { rule: "Verify vs f itself: residuals #{ver[:residual_max]}, near-center error #{ver[:near_center_rel_error]}, window median error Taylor #{ver[:median_rel_error_taylor]} vs Pade #{ver[:median_rel_error_pade]}#{ver[:improvement] ? " (x#{ver[:improvement]} better)" : ''}" }
    steps << { rule: ver[:verdict] }
    steps
  end
end


# ===== interval_arithmetic.rb =====
# Interval arithmetic - conditional enclosures for the float-only engine.
#
# Every other verification in this engine is statistical (sample points, MC).
# This module is the rigorous upgrade: evaluate_interval walks the SAME tree as
# evaluate but carries [lo, hi] bounds through every operation with OUTWARD
# ROUNDING (Float#prev_float / #next_float), so the result interval provably
# contains the true range over the whole box - not just at the sampled points.
# IEEE +,-,*,/ are correctly rounded (1 ulp suffices); libm transcendentals are
# widened by 2 ulps. This assumes the platform libm error fits that bound;
# it is not a verified property of every supported platform or argument.
#
# On top of that primitive, three certified applications:
#   * enclose            - guaranteed range over a box, tightened by subdivision
#                          (watch the dependency problem shrink: x - x over
#                          [0,1] is [-1,1] naively, and -> [0,0] as boxes split)
#   * global_min         - branch & bound: a PROVEN enclosure of the global
#                          minimum. Sampling can get trapped in a local dip;
#                          a lower bound from interval evaluation cannot.
#   * certified_integral - Darboux-style bounds: sum of width*[f_lo, f_hi] over
#                          adaptive segments. The Simpson estimate must land
#                          inside the proven bracket - the oracle turned around.
#
# HONESTY - certification REFUSES rather than guesses: an unbound variable, a
# domain violation (ln over an interval touching 0), or an unsupported special
# function raises IntervalDomainError instead of returning a plausible number.
# Division by an interval containing 0 returns the whole line - wide, but true.


module IntervalOps
  module_function

  class IntervalDomainError < StandardError; end

  TWO_PI = 2 * Math::PI
  WHOLE = [-Float::INFINITY, Float::INFINITY].freeze

  def whole
    WHOLE.dup
  end

  # outward rounding: 1 ulp for exact IEEE ops.
  # Overflow direction matters: a LOWER bound that overflowed to +Inf means the
  # true values all exceed Float::MAX, so Float::MAX is a valid (finite) lower
  # bound - leaving +Inf there would make [Inf, Inf] an "enclosure" that
  # contains NO real number at all, i.e. an unsound certificate. Mirror for an
  # upper bound at -Inf.
  def out(l, h)
    return whole if l.nan? || h.nan?
    l = Float::MAX if l == Float::INFINITY
    h = -Float::MAX if h == -Float::INFINITY
    [l.infinite? ? l : l.prev_float, h.infinite? ? h : h.next_float]
  end

  # 2 ulp for libm transcendentals (faithful, not correctly rounded)
  def out2(l, h)
    return whole if l.nan? || h.nan?
    l = Float::MAX if l == Float::INFINITY
    h = -Float::MAX if h == -Float::INFINITY
    [l.infinite? ? l : l.prev_float.prev_float, h.infinite? ? h : h.next_float.next_float]
  end

  def add(x, y)
    out(x[0] + y[0], x[1] + y[1])
  end

  def sub(x, y)
    out(x[0] - y[1], x[1] - y[0])
  end

  def neg(x)
    [-x[1], -x[0]]
  end

  def mul(x, y)
    ps = [x[0] * y[0], x[0] * y[1], x[1] * y[0], x[1] * y[1]]
    return whole if ps.any?(&:nan?)  # 0 * inf - fall back to the always-true answer
    out(ps.min, ps.max)
  end

  def div(x, y)
    return whole if y[0] <= 0.0 && y[1] >= 0.0  # denominator can vanish: wide but true
    mul(x, out(1.0 / y[1], 1.0 / y[0]))
  end

  def int_pow(x, n)
    return [1.0, 1.0] if n.zero?  # x^0 = 1 (matches evaluate's convention)
    return div([1.0, 1.0], int_pow(x, -n)) if n.negative?
    l, h = x
    if n.odd?
      out(l**n, h**n)
    elsif l >= 0
      out(l**n, h**n)
    elsif h <= 0
      out(h**n, l**n)
    else
      out(0.0, [l.abs, h.abs].max**n)
    end
  end

  # x^y for interval exponent: needs x > 0 (via exp(y ln x)); integer point
  # exponents go through int_pow and allow any base. The integer route takes
  # ONLY exact point-integer exponents - snapping x^2.0000000001 to x^2 would
  # evaluate a different function and break the enclosure guarantee. (Literal
  # exponents in parsed expressions are exact point intervals, so real use is
  # unaffected; perturbed exponents go the exp/ln route or refuse honestly.)
  def pow(x, y)
    if y[0] == y[1] && y[0].finite? && y[0].abs < 1e15 && y[0] == y[0].round
      return int_pow(x, y[0].to_i)
    end
    raise IntervalDomainError, "x^y with a non-integer exponent needs x > 0 over the whole box (got x down to #{x[0]})" if x[0] <= 0
    exp_i(mul(y, ln_i(x)))
  end

  # is there a critical point offset + period*k inside [l, h]?
  def contains_crit?(l, h, offset, period)
    k = ((l - offset) / period).ceil
    offset + period * k <= h
  end

  def sin_i(x)
    l, h = x
    return [-1.0, 1.0] if !l.finite? || !h.finite? || h - l >= TWO_PI
    m = 1e-9 * [l.abs, h.abs, 1.0].max  # pi is inexact: widen the crit test conservatively
    vals = [Math.sin(l), Math.sin(h)]
    lo = contains_crit?(l - m, h + m, -Math::PI / 2, TWO_PI) ? -1.0 : vals.min
    hi = contains_crit?(l - m, h + m, Math::PI / 2, TWO_PI) ? 1.0 : vals.max
    clamp1(out2(lo, hi))
  end

  def cos_i(x)
    l, h = x
    return [-1.0, 1.0] if !l.finite? || !h.finite? || h - l >= TWO_PI
    m = 1e-9 * [l.abs, h.abs, 1.0].max
    vals = [Math.cos(l), Math.cos(h)]
    lo = contains_crit?(l - m, h + m, Math::PI, TWO_PI) ? -1.0 : vals.min
    hi = contains_crit?(l - m, h + m, 0.0, TWO_PI) ? 1.0 : vals.max
    clamp1(out2(lo, hi))
  end

  def clamp1(x)
    [[x[0], -1.0].max, [x[1], 1.0].min]
  end

  def tan_i(x)
    l, h = x
    return whole if !l.finite? || !h.finite? || h - l >= Math::PI
    m = 1e-9 * [l.abs, h.abs, 1.0].max
    return whole if contains_crit?(l - m, h + m, Math::PI / 2, Math::PI)  # pole inside
    out2(Math.tan(l), Math.tan(h))
  end

  def cot_i(x)
    l, h = x
    return whole if !l.finite? || !h.finite? || h - l >= Math::PI
    m = 1e-9 * [l.abs, h.abs, 1.0].max
    return whole if contains_crit?(l - m, h + m, 0.0, Math::PI)  # pole at k*pi
    out2(1.0 / Math.tan(h), 1.0 / Math.tan(l))  # decreasing on each branch
  end

  def exp_i(x)
    out2(x[0].finite? ? Math.exp(x[0]) : (x[0] < 0 ? 0.0 : Float::INFINITY),
         x[1].finite? ? Math.exp(x[1]) : (x[1] < 0 ? 0.0 : Float::INFINITY))
  end

  def ln_i(x)
    raise IntervalDomainError, "ln over [#{x[0]}, #{x[1]}] - the interval touches x <= 0, where ln does not exist" if x[0] <= 0
    out2(Math.log(x[0]), x[1].finite? ? Math.log(x[1]) : Float::INFINITY)
  end

  def sqrt_i(x)
    raise IntervalDomainError, "sqrt over [#{x[0]}, #{x[1]}] - the interval reaches below 0" if x[0] < 0
    out2(Math.sqrt(x[0]), x[1].finite? ? Math.sqrt(x[1]) : Float::INFINITY)
  end

  def abs_i(x)
    l, h = x
    if l >= 0 then [l, h]
    elsif h <= 0 then [-h, -l]
    else [0.0, [l.abs, h.abs].max]
    end
  end

  def mono(x, domain_lo = nil, domain_hi = nil, name = nil, &fn)
    if (domain_lo && x[0] < domain_lo) || (domain_hi && x[1] > domain_hi)
      raise IntervalDomainError, "#{name} over [#{x[0]}, #{x[1]}] leaves its domain"
    end
    out2(fn.call(x[0]), fn.call(x[1]))
  end

  def anti_mono(x, domain_lo, domain_hi, name, &fn)  # decreasing (arccos)
    if x[0] < domain_lo || x[1] > domain_hi
      raise IntervalDomainError, "#{name} over [#{x[0]}, #{x[1]}] leaves its domain"
    end
    out2(fn.call(x[1]), fn.call(x[0]))
  end

  def cosh_i(x)
    l, h = x
    hi = [Math.cosh(l), Math.cosh(h)].max
    lo = l <= 0 && h >= 0 ? 1.0 : [Math.cosh(l), Math.cosh(h)].min
    out2(lo, hi)
  end
end

# evaluate_interval lives directly on the AST node, beside evaluate: the same
# recursion, but every step carries a proven [lo, hi] instead of one float.
class ExpressionNode
  def evaluate_interval(box)
    if isleaf
      if data.is_a?(Numeric)
        v = data.to_f
        return [v, v]
      end
      iv = box[data.to_s]
      unless iv
        raise IntervalOps::IntervalDomainError,
              "no interval given for '#{data}' - certification refuses to guess (plain evaluate would default it to 0, which here would be a silent lie)"
      end
      return iv
    end

    o = IntervalOps
    case data
    when '+' then o.add(left.evaluate_interval(box), right.evaluate_interval(box))
    when '-' then o.sub(left.evaluate_interval(box), right.evaluate_interval(box))
    when '*' then o.mul(left.evaluate_interval(box), right.evaluate_interval(box))
    when '/' then o.div(left.evaluate_interval(box), right.evaluate_interval(box))
    when '^' then o.pow(left.evaluate_interval(box), right.evaluate_interval(box))
    when 'sin' then o.sin_i(right.evaluate_interval(box))
    when 'cos' then o.cos_i(right.evaluate_interval(box))
    when 'tan' then o.tan_i(right.evaluate_interval(box))
    when 'cot' then o.cot_i(right.evaluate_interval(box))
    when 'sec' then o.div([1.0, 1.0], o.cos_i(right.evaluate_interval(box)))
    when 'csc' then o.div([1.0, 1.0], o.sin_i(right.evaluate_interval(box)))
    when 'exp' then o.exp_i(right.evaluate_interval(box))
    when 'ln' then o.ln_i(right.evaluate_interval(box))
    when 'sqrt' then o.sqrt_i(right.evaluate_interval(box))
    when 'abs' then o.abs_i(right.evaluate_interval(box))
    when 'arctan' then o.mono(right.evaluate_interval(box), nil, nil, 'arctan') { |v| Math.atan(v) }
    when 'arcsin' then o.mono(right.evaluate_interval(box), -1.0, 1.0, 'arcsin') { |v| Math.asin(v) }
    when 'arccos' then o.anti_mono(right.evaluate_interval(box), -1.0, 1.0, 'arccos') { |v| Math.acos(v) }
    when 'sinh' then o.mono(right.evaluate_interval(box), nil, nil, 'sinh') { |v| Math.sinh(v) }
    when 'cosh' then o.cosh_i(right.evaluate_interval(box))
    when 'tanh' then o.mono(right.evaluate_interval(box), nil, nil, 'tanh') { |v| Math.tanh(v) }
    when 'erf' then o.mono(right.evaluate_interval(box), nil, nil, 'erf') { |v| Math.erf(v) }
    else
      raise IntervalOps::IntervalDomainError,
            "interval evaluation does not support '#{data}' - refusing to certify rather than guessing"
    end
  end
end

module IntervalArithmetic
  module_function

  # ------------------------------------------------------- range enclosure

  def enclose(f_str:, box:, splits: 32)
    f, vars, nbox = ia_setup(f_str, box)
    raise 'enclose supports 1 or 2 variables' unless (1..2).cover?(vars.size)
    splits = splits.to_i.clamp(2, vars.size == 1 ? 256 : 24)

    naive = f.root.evaluate_interval(nbox)

    stages = []
    pieces = nil
    hull = nil
    [1, 4, splits].uniq.sort.each do |s|
      pieces = subdivide_grid(nbox, vars, s).map do |bx|
        iv = f.root.evaluate_interval(bx)
        { box: vars.map { |v| bx[v].map { |q| q.round(9) } }, lo: iv[0], hi: iv[1] }
      end
      hull = [pieces.map { |p| p[:lo] }.min, pieces.map { |p| p[:hi] }.max]
      stages << { splits: s, width: fin_or_nil(hull[1] - hull[0]),
                  lo: fin_or_nil(floor_out(hull[0])), hi: fin_or_nil(ceil_out(hull[1])) }
    end
    bounded = hull[0].finite? && hull[1].finite?

    # sampling oracle: every sample MUST land inside the certified hull
    smin, smax, violations = sample_range(f, vars, nbox, 4000, hull)
    curve = vars.size == 1 ? curve_samples(f, vars[0], nbox[vars[0]]) : nil

    {
      variables: vars, box: vars.map { |v| nbox[v] },
      naive: { lo: fin_or_nil(floor_out(naive[0])), hi: fin_or_nil(ceil_out(naive[1])), width: fin_or_nil(naive[1] - naive[0]) },
      certified: { lo: fin_or_nil(floor_out(hull[0])), hi: fin_or_nil(ceil_out(hull[1])), width: fin_or_nil(hull[1] - hull[0]) },
      stages: stages,
      pieces: vars.size == 1 ? pieces.map { |p| { x0: p[:box][0][0], x1: p[:box][0][1], lo: clip9(p[:lo]), hi: clip9(p[:hi]) } } : nil,
      curve: curve,
      sampled: { min: fin_or_nil(smin), max: fin_or_nil(smax), n: 4000, inside_certified: violations.zero?, violations: violations },
      verification: {
        passed: violations.zero?,
        verdict: if !violations.zero?
                   "FAILED: #{violations} sample(s) escaped the interval hull - that is a bug in the interval code, not in the samples"
                 elsif !bounded
                   'UNBOUNDED ENCLOSURE: containment holds trivially, but the hull never became finite at this subdivision (a division by an interval containing 0, or genuine unboundedness) - true, and honestly uninformative; shrink the box away from the singularity'
                 else
                   "CONDITIONAL INTERVAL BOUND: values on the box are enclosed by [#{fmt(hull[0])}, #{fmt(hull[1])}] - 4000 samples all inside; transcendental bounds assume a two-ULP library error bound"
                 end
      },
      steps: [
        { rule: "Interval evaluation: walk the same AST as evaluate, but carry [lo, hi] through every op with outward rounding (1 ulp arithmetic, 2 ulp libm)" },
        { rule: "Naive single-box enclosure: [#{fmt(naive[0])}, #{fmt(naive[1])}] - wide when a variable appears twice (the dependency problem: each occurrence varies independently)" },
        { rule: "Subdivide #{splits}#{vars.size == 2 ? ' x ' + splits.to_s : ''} boxes and take the hull: [#{fmt(hull[0])}, #{fmt(hull[1])}] - width #{fmt(stages.last[:width])} vs #{fmt(stages.first[:width])} naive" },
        { rule: 'Regression check: 4000 random samples must land inside the interval. Passing does not prove the assumed transcendental library error bound.' }
      ]
    }
  end

  # ------------------------------------------------- certified global minimum

  def global_min(f_str:, box:, max_boxes: 1500, xtol: 1e-7)
    f, vars, nbox = ia_setup(f_str, box)
    raise 'global_min supports 1 or 2 variables' unless (1..2).cover?(vars.size)

    # the certified upper bound comes from an INTERVAL evaluation at the box
    # midpoint (a point box): plain float evaluation carries uncontrolled
    # rounding and for cancellation-prone f can land BELOW every true value,
    # which would make "min <= ub" - half the certificate - simply false
    mid_eval = lambda do |bx|
      pt = vars.to_h { |v| m = (bx[v][0] + bx[v][1]) / 2.0; [v, [m, m]] }
      iv = begin
        f.root.evaluate_interval(pt)
      rescue IntervalOps::IntervalDomainError
        nil
      end
      iv && iv[1].finite? ? iv[1] : nil
    end
    ub = mid_eval.call(nbox) || Float::INFINITY
    queue = [[f.root.evaluate_interval(nbox)[0], nbox]]
    done = []
    trace = []
    processed = 0

    while (item = queue.min_by(&:first)) && processed < max_boxes
      queue.delete_at(queue.index(item))
      lb, bx = item
      processed += 1
      if lb > ub
        push_trace(trace, vars, bx, 'pruned')
        next
      end
      widest = vars.max_by { |v| bx[v][1] - bx[v][0] }
      if bx[widest][1] - bx[widest][0] < xtol
        done << [lb, bx]
        push_trace(trace, vars, bx, 'converged')
        next
      end
      mid = (bx[widest][0] + bx[widest][1]) / 2.0
      [[bx[widest][0], mid], [mid, bx[widest][1]]].each do |half|
        child = bx.merge(widest => half)
        iv = f.root.evaluate_interval(child)
        m = mid_eval.call(child)
        ub = [ub, m].min if m
        if iv[0] > ub
          push_trace(trace, vars, child, 'pruned')
        else
          queue << [iv[0], child]
        end
      end
    end
    queue.each { |lbq, bxq| push_trace(trace, vars, bxq, lbq <= ub ? 'live' : 'pruned') }

    lb_all = (queue + done).map(&:first).min || ub
    minimizers = (queue + done).select { |lbq, _| lbq <= ub }
                               .sort_by(&:first).first(24)
                               .map { |_, bxq| vars.map { |v| bxq[v].map { |q| q.round(8) } } }

    # oracle: dense sampling may approach but NEVER beat the certified lower bound
    best_sample = sample_min(f, vars, nbox, 20_000)
    sound = best_sample >= lb_all - 1e-9 * [lb_all.abs, 1].max
    gap = (ub - lb_all).abs

    curve = vars.size == 1 ? curve_samples(f, vars[0], nbox[vars[0]]) : nil
    heat = vars.size == 2 ? heat_grid(f, vars, nbox, 46) : nil

    {
      variables: vars, box: vars.map { |v| nbox[v] },
      certified: { lb: fin_or_nil(floor_out(lb_all, 12)), ub: fin_or_nil(ceil_out(ub, 12)), gap: fin_or_nil(gap) },
      minimizer_boxes: minimizers,
      boxes_processed: processed,
      trace: trace.first(700),
      sampled_min: fin_or_nil(clip12(best_sample)),
      curve: curve, heat: heat,
      verification: {
        passed: sound && lb_all.finite? && ub.finite?,
        verdict: if !sound
                   "FAILED: a sample beat the interval lower bound - the interval code is wrong, and this check just caught it"
                 elsif !lb_all.finite? || !ub.finite?
                   'NO CERTIFICATE: the bounds never became finite (division by an interval spanning 0, unboundedness, or an unevaluable midpoint) - refusing to print a proven-looking interval that is not one'
                 else
                   "CONDITIONAL INTERVAL BOUND: the global minimum is enclosed by [#{fmt(lb_all)}, #{fmt(ub)}] - no point of the box can go below #{fmt(lb_all)}; 20000 samples respect the bound (best found: #{fmt(best_sample)}); transcendental bounds assume a two-ULP library error bound"
                 end
      },
      steps: [
        { rule: 'Branch & bound: discard boxes whose interval lower bound exceeds the best midpoint upper bound, subject to the enclosure assumptions.' },
        { rule: "#{processed} boxes processed; #{trace.count { |t| t[:s] == 'pruned' }} pruned by interval bounds, #{minimizers.size} minimizer box(es) survive" },
        { rule: "Conditional interval enclosure of min f: [#{fmt(lb_all)}, #{fmt(ub)}], gap #{fmt(gap)}" },
        { rule: 'Regression check: compare 20000 samples against the interval lower bound. Passing is supporting evidence, not proof of the library assumption.' }
      ]
    }
  end

  # ------------------------------------------------ certified definite integral

  def certified_integral(f_str:, variable: 'x', lower:, upper:, tol: 1e-4, max_segments: 1200)
    f = MathematicalExpression.new(f_str.to_s)
    raise "could not parse '#{f_str}'" unless f.root
    a = lower.to_f
    b = upper.to_f
    raise 'needs finite bounds with lower < upper' unless a.finite? && b.finite? && a < b

    seg = ->(x0, x1) do
      iv = f.root.evaluate_interval(variable => [x0, x1])
      { x0: x0, x1: x1, lo: iv[0], hi: iv[1] }
    end
    segs = [seg.call(a, b)]
    snapshots = []
    loop do
      lo_sum, hi_sum = darboux(segs)
      width = hi_sum - lo_sum
      snapshots << { n: segs.size, lo: fin_or_nil(clip12(lo_sum)), hi: fin_or_nil(clip12(hi_sum)), width: fin_or_nil(clip12(width)) } if [1, 8, 32, 128].include?(segs.size)
      break if width < tol * [1.0, (lo_sum.abs + hi_sum.abs) / 2].max || segs.size >= max_segments
      worst = segs.each_with_index.max_by { |s, _| w = (s[:x1] - s[:x0]) * (s[:hi] - s[:lo]); w.nan? ? Float::INFINITY : w }[1]
      s = segs.delete_at(worst)
      mid = (s[:x0] + s[:x1]) / 2.0
      segs << seg.call(s[:x0], mid) << seg.call(mid, s[:x1])
    end
    segs.sort_by! { |s| s[:x0] }
    lo_sum, hi_sum = darboux(segs)
    snapshots << { n: segs.size, lo: fin_or_nil(clip12(lo_sum)), hi: fin_or_nil(clip12(hi_sum)), width: fin_or_nil(clip12(hi_sum - lo_sum)) }

    # oracle: Simpson (independent numerics) must land inside the proven bracket,
    # up to Simpson's own estimated error
    s2 = simpson(f, variable, a, b, 2000)
    s1 = simpson(f, variable, a, b, 1000)
    grace = 2 * (s2 - s1).abs + 1e-10 * [1.0, s2.abs].max
    inside = s2 >= lo_sum - grace && s2 <= hi_sum + grace

    unless lo_sum.finite? && hi_sum.finite?
      # a singular integrand never yields a finite bracket - refuse honestly
      return {
        variable: variable, lower: a, upper: b,
        certified: { lo: lo_sum.finite? ? clip12(lo_sum) : nil, hi: hi_sum.finite? ? clip12(hi_sum) : nil, width: nil },
        segments: segs.map { |s| { x0: s[:x0].round(9), x1: s[:x1].round(9), lo: clip9(s[:lo]), hi: clip9(s[:hi]) } },
        snapshots: snapshots, simpson: fin_or_nil(clip12(s2)), curve: curve_samples(f, variable, [a, b]),
        verification: {
          passed: false,
          verdict: 'NO CERTIFICATE - the enclosure stayed unbounded: f is (or may be) singular inside the range, so no finite proven bracket exists. A plain numeric estimate here would be exactly the kind of confident guess this engine refuses to make.'
        },
        steps: [
          { rule: 'Darboux-style bounds: on each segment, width * [f_lo, f_hi] brackets the true area' },
          { rule: "Refinement stalled: some segment's enclosure is unbounded (division by an interval containing 0, or a pole) - the honest answer is that no finite certificate exists" }
        ]
      }
    end

    {
      variable: variable, lower: a, upper: b,
      certified: { lo: clip12(lo_sum), hi: clip12(hi_sum), width: clip12(hi_sum - lo_sum) },
      segments: segs.map { |s| { x0: s[:x0].round(9), x1: s[:x1].round(9), lo: clip9(s[:lo]), hi: clip9(s[:hi]) } },
      snapshots: snapshots,
      simpson: fin_or_nil(clip12(s2)),
      curve: curve_samples(f, variable, [a, b]),
      verification: {
        passed: inside,
        verdict: inside ?
          "CONDITIONAL INTERVAL BOUND: the integral is enclosed by [#{fmt(lo_sum)}, #{fmt(hi_sum)}]; Simpson says #{fmt(s2)} and falls inside the bracket; transcendental bounds assume a two-ULP library error bound" :
          "FAILED: Simpson's estimate #{fmt(s2)} escaped the interval bracket - the enclosure code is wrong and this oracle caught it"
      },
      steps: [
        { rule: 'Darboux-style bounds: on each segment, width * [f_lo, f_hi] brackets the true area; summed with outward rounding under the stated enclosure assumptions' },
        { rule: "Adaptive bisection of the worst segment (largest width * uncertainty) -> #{segs.size} segments, bracket width #{fmt(hi_sum - lo_sum)}" },
        { rule: "Conditional interval bound: integral in [#{fmt(lo_sum)}, #{fmt(hi_sum)}]; independent Simpson: #{fmt(s2)}" }
      ]
    }
  end

  # ---------------------------------------------------------------- helpers

  def ia_setup(f_str, box)
    f = MathematicalExpression.new(f_str.to_s)
    raise "could not parse '#{f_str}'" unless f.root
    nbox = {}
    box.each do |k, v|
      arr = v.is_a?(Array) ? v.map(&:to_f) : [v.to_f, v.to_f]
      raise "bad interval for #{k}" unless arr.size == 2 && arr[0].finite? && arr[1].finite? && arr[0] <= arr[1]
      nbox[k.to_s] = arr
    end
    [f, nbox.keys, nbox]
  end

  def subdivide_grid(nbox, vars, s)
    axes = vars.map do |v|
      l, h = nbox[v]
      (0...s).map { |i| [l + (h - l) * i / s, l + (h - l) * (i + 1) / s] }
    end
    if vars.size == 1
      axes[0].map { |seg| { vars[0] => seg } }
    else
      axes[0].product(axes[1]).map { |sx, sy| { vars[0] => sx, vars[1] => sy } }
    end
  end

  def sample_range(f, vars, nbox, n, hull)
    rng = Random.new(20_260_824)
    smin = Float::INFINITY
    smax = -Float::INFINITY
    violations = 0
    n.times do
      pt = vars.to_h { |v| [v, nbox[v][0] + rng.rand * (nbox[v][1] - nbox[v][0])] }
      val = begin
        f.evaluate(pt)
      rescue StandardError
        next
      end
      next unless val.is_a?(Numeric) && val.to_f.finite?
      smin = [smin, val].min
      smax = [smax, val].max
      violations += 1 if val < hull[0] || val > hull[1]
    end
    [smin, smax, violations]
  end

  def sample_min(f, vars, nbox, n)
    rng = Random.new(20_260_825)
    best = Float::INFINITY
    n.times do |i|
      pt = vars.to_h do |v|
        l, h = nbox[v]
        # half grid-ish, half random for coverage
        frac = i.even? ? ((i / 2 % 101) / 100.0) : rng.rand
        [v, l + frac * (h - l)]
      end
      val = begin
        f.evaluate(pt)
      rescue StandardError
        next
      end
      best = [best, val].min if val.is_a?(Numeric) && val.to_f.finite?
    end
    best
  end

  def curve_samples(f, var, seg)
    l, h = seg
    xs, ys = [], []
    201.times do |i|
      x = l + (h - l) * i / 200.0
      v = begin
        f.evaluate(var => x)
      rescue StandardError
        nil
      end
      xs << x.round(8)
      ys << (v.is_a?(Numeric) && v.to_f.finite? && v.abs < 1e9 ? v.round(8) : nil)
    end
    { xs: xs, ys: ys }
  end

  def heat_grid(f, vars, nbox, n)
    (0...n).map do |j|
      (0...n).map do |i|
        pt = { vars[0] => nbox[vars[0]][0] + (nbox[vars[0]][1] - nbox[vars[0]][0]) * i / (n - 1.0),
               vars[1] => nbox[vars[1]][0] + (nbox[vars[1]][1] - nbox[vars[1]][0]) * j / (n - 1.0) }
        v = begin
          f.evaluate(pt)
        rescue StandardError
          nil
        end
        v.is_a?(Numeric) && v.to_f.finite? ? v.round(6) : nil
      end
    end
  end

  def push_trace(trace, vars, bx, status)
    return if trace.size >= 700
    trace << { b: vars.map { |v| bx[v].map { |q| q.round(8) } }, s: status }
  end

  def darboux(segs)
    lo = 0.0
    hi = 0.0
    segs.each do |s|
      w = s[:x1] - s[:x0]
      lo = (lo + w * s[:lo]).prev_float
      hi = (hi + w * s[:hi]).next_float
    end
    [lo, hi]
  end

  def simpson(f, var, a, b, n)
    n += 1 if n.odd?
    h = (b - a) / n
    s = 0.0
    (0..n).each do |i|
      v = begin
        f.evaluate(var => a + i * h)
      rescue StandardError
        0.0
      end
      v = 0.0 unless v.is_a?(Numeric) && v.to_f.finite?
      s += v * (i.zero? || i == n ? 1 : i.odd? ? 4 : 2)
    end
    s * h / 3
  end

  def clip12(v)
    # (v * 1e12).round overflows for |v| > ~1.8e296 and no-arg round on
    # Infinity raises FloatDomainError - huge magnitudes pass through raw
    return v unless v.finite? && v.abs < 1e15
    (v * 1e12).round / 1e12
  end

  # display rounding for certified bounds must never round INWARD - a bound
  # printed tighter than proven is a small lie. Floor the lo, ceil the hi.
  def floor_out(v, digits = 10)
    return v unless v.finite? && v.abs < 1e15
    (v * 10**digits).floor / 10.0**digits
  end

  def ceil_out(v, digits = 10)
    return v unless v.finite? && v.abs < 1e15
    (v * 10**digits).ceil / 10.0**digits
  end

  # JSON cannot carry Infinity/NaN - unbounded endpoints become nil, and the
  # caller is expected to say honestly that no finite bound exists
  def fin_or_nil(v)
    v.is_a?(Numeric) && v.to_f.finite? ? v : nil
  end

  def clip9(v)
    return v unless v.is_a?(Float)
    v.finite? ? v.round(9) : (v.positive? ? 1e9 : -1e9)
  end

  def fmt(v)
    return 'unbounded' unless v.is_a?(Numeric) && v.to_f.finite?
    v = v.to_f
    v.abs >= 1e5 || (v != 0 && v.abs < 1e-4) ? format('%.6e', v) : v.round(8).to_s
  end
end


# ===== general_relativity.rb =====
# Symbolic differential geometry / general relativity - metric in, curvature out.
#
#   g_uv (diagonal, symbolic)  ->  Christoffel  ->  Riemann  ->  Ricci / Kretschmann
#
#   Gamma^l_{uv} = 1/(2 g_ll) (d_u g_lv + d_v g_lu - d_l g_uv)          (diagonal g)
#   R^r_{s u v}  = d_u Gamma^r_{vs} - d_v Gamma^r_{us}
#                  + Gamma^r_{ul} Gamma^l_{vs} - Gamma^r_{vl} Gamma^l_{us}
#   R_{sv} = R^r_{s r v}                    (signature -+++, MTW conventions)
#
# All derivatives are the engine's own symbolic derivatives; expressions are
# composed as parseable infix (to_infix round-trips through the parser), so
# mass M / Hubble H stay SYMBOLIC in the displayed Christoffels.
#
# HONESTY - the classic self-checks of the field, all against oracles the
# construction never saw:
#   * Schwarzschild: all 10 Ricci components must vanish (vacuum) - one wrong
#     sign or index anywhere and they will not. The Kretschmann scalar must
#     equal 48 M^2 / r^6 exactly - a NONZERO closed form, so "it is all just
#     zero" cannot fake a pass.
#   * de Sitter: R_uv = 3 H^2 g_uv - its sign pins the curvature convention.
#   * Riemann index symmetries + first Bianchi identity, checked numerically.
#   * The geodesic integrator runs on the COMPUTED Christoffels; energy,
#     angular momentum and 4-velocity norm must stay conserved (sharp check),
#     and the measured perihelion advance must match 6 pi M / ell (first-order
#     PN, so corroboration with an honest tolerance, not the verdict).
# Custom metrics get the structural checks only, and say so.

require 'stringio'

module GeneralRelativity
  module_function

  # the simplifier narrates to stdout; certification output should not
  def gr_silence
    old = $stdout
    $stdout = StringIO.new
    yield
  ensure
    $stdout = old
  end

  PRESETS = {
    'minkowski' => {
      label: 'Minkowski (flat spacetime)',
      coords: %w[t x y z],
      metric: ['-1', '1', '1', '1'],
      params: {},
      ranges: { 't' => [-2, 2], 'x' => [-2, 2], 'y' => [-2, 2], 'z' => [-2, 2] },
      oracle: :flat
    },
    'schwarzschild' => {
      label: 'Schwarzschild (black hole / star exterior)',
      coords: %w[t r th ph],
      metric: ['-(1 - 2*M/r)', '1/(1 - 2*M/r)', 'r^2', 'r^2*sin(th)^2'],
      params: { 'M' => 1.0 },
      ranges: { 't' => [0, 1], 'r' => [3.2, 20], 'th' => [0.4, 2.7], 'ph' => [0, 6] },
      oracle: :vacuum
    },
    'desitter' => {
      label: 'de Sitter (exponentially expanding universe)',
      coords: %w[t x y z],
      metric: ['-1', 'exp(2*H*t)', 'exp(2*H*t)', 'exp(2*H*t)'],
      params: { 'H' => 0.7 },
      ranges: { 't' => [0, 1.2], 'x' => [-1.5, 1.5], 'y' => [-1.5, 1.5], 'z' => [-1.5, 1.5] },
      oracle: :einstein_lambda
    }
  }.freeze

  GREEK = { 'th' => 'θ', 'ph' => 'φ' }.freeze

  def analyze(preset: 'schwarzschild', metric: nil, coords: nil, params: nil, ranges: nil, orbit: nil)
    spec = build_spec(preset, metric, coords, params, ranges)
    cs = spec[:coords]
    ctx = build_context(spec)

    # random sample points for every numeric check
    envs = sample_envs(spec, 9)

    christoffels = list_christoffels(ctx, cs)
    ricci = ricci_analysis(ctx, spec, envs)
    sym = symmetry_checks(ctx, spec, envs)
    kre = spec[:oracle] == :vacuum ? kretschmann_check(ctx, spec, envs) : nil

    # Explicit orbit parameters that are infeasible should error loudly (the
    # user asked for that orbit); an infeasible DEFAULT orbit (e.g. params
    # M = 0) must not throw away the already-computed curvature results.
    orb = nil
    if spec[:key] == 'schwarzschild'
      begin
        orb = geodesic_orbit(ctx, spec, orbit || {})
      rescue StandardError => e
        raise if orbit && !orbit.empty?
        orb = { skipped: "orbit skipped: #{e.message} (with the current params)" }
      end
    end

    checks = [ricci[:passed], sym[:passed]]
    checks << kre[:passed] if kre
    checks << orb[:verification][:passed] if orb && orb[:verification]
    all_pass = checks.all?

    {
      preset: spec[:key], label: spec[:label], coords: cs.map { |c| GREEK[c] || c },
      metric: cs.each_index.map { |i| { component: "g_#{sub2(cs[i], cs[i])}", expr: spec[:metric][i] } },
      christoffels: christoffels,
      n_nonzero_christoffels: ctx[:gamma_list].size,
      ricci: ricci, symmetry: sym, kretschmann: kre, orbit: orb,
      verification: {
        passed: all_pass,
        verdict: all_pass ? overall_verdict(spec) :
          'FAILED - at least one geometric identity does not hold; see the individual checks'
      },
      steps: build_steps(spec, ctx, ricci, sym, kre, orb)
    }
  end

  # ------------------------------------------------------------ construction

  def build_spec(preset, metric, coords, params, ranges)
    if metric
      cs = (coords || %w[t x y z]).map(&:to_s).first(4)
      raise 'a custom metric needs 4 diagonal components' unless metric.size == 4 && cs.size == 4
      { key: 'custom', label: 'Custom diagonal metric', coords: cs, metric: metric.map(&:to_s),
        params: (params || {}).transform_keys(&:to_s).transform_values(&:to_f),
        ranges: cs.to_h { |c| [c, (ranges && ranges[c]) || [0.7, 1.9]] }, oracle: :none }
    else
      s = PRESETS[preset.to_s] or raise "unknown preset '#{preset}'"
      out = s.merge(key: preset.to_s)
      out = out.merge(params: out[:params].merge((params || {}).transform_keys(&:to_s).transform_values(&:to_f)))
      out
    end
  end

  def build_context(spec)
    cs = spec[:coords]
    g = spec[:metric].map do |s|
      e = MathematicalExpression.new(s)
      raise "could not parse metric component '#{s}'" unless e.root
      e
    end

    # every free symbol must be a coordinate or a bound parameter: the
    # evaluator silently reads unknown names as 0, which would prune real
    # Christoffels as "structural zeros" and yield confidently-wrong curvature
    free = g.flat_map { |e| leaf_symbols(e.root) }.uniq - cs - spec[:params].keys
    unless free.empty?
      raise "unbound symbol(s) in the metric: #{free.join(', ')} - pass params: {#{free.map { |s| "#{s}: value" }.join(', ')}} (evaluate would silently treat them as 0)"
    end

    # d g_ii / d x^mu, normalized (folds the mechanical zero-branches away)
    dg = g.map do |gi|
      cs.map do |c|
        d = gi.derivative(c)
        d.root = d.normalize_expression(d.root)
        d
      end
    end

    probe_envs = sample_envs(spec, 7)

    # Christoffels: Gamma^l_{uv} for u <= v; drop structural zeros numerically
    gamma = Array.new(4) { Array.new(4) { Array.new(4) } }
    gamma_list = []
    4.times do |l|
      4.times do |u|
        (u...4).each do |v|
          parts = []
          parts << dg[l][u].root.to_infix if v == l
          parts << dg[l][v].root.to_infix if u == l
          parts << "(0 - (#{dg[u][l].root.to_infix}))" if u == v && !(u == l && v == l)
          # when all three indices coincide the sum collapses to a single d_l g_ll
          parts = [dg[l][l].root.to_infix] if u == l && v == l && u == v
          next if parts.empty?
          num = parts.join(' + ')
          e = MathematicalExpression.new("(#{num}) / (2 * (#{spec[:metric][l]}))")
          next unless e.root
          e.root = e.normalize_expression(e.root)
          next if structural_zero?(parts, probe_envs)
          gamma[l][u][v] = e
          gamma[l][v][u] = e
          gamma_list << [l, u, v, e]
        end
      end
    end

    # d Gamma^l_{uv} / d x^k for the Riemann tensor
    dgamma = Array.new(4) { Array.new(4) { Array.new(4) } }
    gamma_list.each do |l, u, v, e|
      ds = cs.map do |c|
        d = e.derivative(c)
        d.root = d.normalize_expression(d.root)
        d
      end
      dgamma[l][u][v] = ds
      dgamma[l][v][u] = ds
    end

    { spec: spec, g: g, dg: dg, gamma: gamma, gamma_list: gamma_list, dgamma: dgamma }
  end

  # A Christoffel is a structural zero iff its numerator parts CANCEL - the sum
  # is tiny relative to the largest part - at every probe point. An absolute
  # threshold would wrongly prune small-but-real symbols (Schwarzschild with
  # M = 1e-11 has Gamma^t_tr ~ 1e-13: small because M is small, not zero).
  def structural_zero?(part_strs, envs)
    parts = part_strs.map do |s|
      e = MathematicalExpression.new(s)
      return false unless e.root
      e
    end
    envs.all? do |env|
      vals = parts.map do |p|
        v = begin
          p.evaluate(env)
        rescue StandardError
          return false
        end
        return false unless v.is_a?(Numeric) && v.to_f.finite?
        v.to_f
      end
      vals.sum.abs <= 1e-9 * [vals.map(&:abs).max, 1e-300].max
    end
  end

  # non-numeric leaves of a tree = the free symbols it mentions
  def leaf_symbols(node)
    return [] unless node
    if node.isleaf
      node.data.is_a?(Numeric) ? [] : [node.data.to_s]
    else
      leaf_symbols(node.left) + leaf_symbols(node.right)
    end
  end

  def sample_envs(spec, n)
    rng = Random.new(20_260_824)
    Array.new(n) do
      env = spec[:params].dup
      spec[:coords].each { |c| l, h = spec[:ranges][c]; env[c] = l + rng.rand * (h - l) }
      env
    end
  end

  # ------------------------------------------------------------ numeric core

  def gamma_table(ctx, env)
    t = Array.new(4) { Array.new(4) { Array.new(4, 0.0) } }
    ctx[:gamma_list].each do |l, u, v, e|
      val = e.evaluate(env).to_f
      t[l][u][v] = val
      t[l][v][u] = val
    end
    t
  end

  def dgamma_table(ctx, env)
    t = Array.new(4) { Array.new(4) { Array.new(4) { Array.new(4, 0.0) } } }
    ctx[:gamma_list].each do |l, u, v, _e|
      4.times do |k|
        val = ctx[:dgamma][l][u][v][k].evaluate(env).to_f
        t[l][u][v][k] = val
        t[l][v][u][k] = val
      end
    end
    t
  end

  # R^r_{s u v} at a point, from the tables
  def riemann_up(gt, dgt, r, s, u, v)
    val = dgt[r][v][s][u] - dgt[r][u][s][v]
    4.times { |l| val += gt[r][u][l] * gt[l][v][s] - gt[r][v][l] * gt[l][u][s] }
    val
  end

  def ricci_at(gt, dgt, s, v)
    (0...4).sum { |r| riemann_up(gt, dgt, r, s, r, v) }
  end

  # ------------------------------------------------------------ the checks

  def ricci_analysis(ctx, spec, envs)
    cs = spec[:coords]
    max_abs = 0.0
    worst = nil
    lam_dev = 0.0
    tables = envs.map { |env| [env, gamma_table(ctx, env), dgamma_table(ctx, env)] }
    # a NaN here would poison every max() below with an ArgumentError - refuse
    # with a real explanation instead
    bad = tables.find { |_env, gt, dgt| !(gt.flatten.all?(&:finite?) && dgt.flatten.all?(&:finite?)) }
    if bad
      pt = bad[0].map { |k, v| "#{k}=#{v.is_a?(Float) ? v.round(4) : v}" }.join(', ')
      raise "the connection is non-finite at a sampled point (#{pt}) - the metric is singular inside the sampled coordinate ranges; move the ranges away from horizons/zeros"
    end
    comps = {}
    4.times do |s|
      (s...4).each do |v|
        vals = tables.map { |env, gt, dgt| ricci_at(gt, dgt, s, v) }
        m = vals.map(&:abs).max
        comps["#{cs[s]}#{cs[v]}"] = m
        if m > max_abs
          max_abs = m
          worst = "R_#{sub2(cs[s], cs[v])}"
        end
        next unless spec[:oracle] == :einstein_lambda
        h = spec[:params]['H']
        tables.each_with_index do |(env, _gt, _dgt), i|
          gval = ctx[:g][s].evaluate(env).to_f
          expected = s == v ? 3 * h * h * gval : 0.0
          lam_dev = [lam_dev, (vals[i] - expected).abs].max
        end
      end
    end

    case spec[:oracle]
    when :flat, :vacuum
      passed = max_abs < 1e-7
      { kind: spec[:oracle].to_s, max_abs: fmt_e(max_abs), worst_component: worst, passed: passed,
        display: 'all 10 components ≡ 0',
        note: passed ? "vacuum verified: every R_uv vanishes (max |R| = #{fmt_e(max_abs)} across #{envs.size} random points)" :
                       "NOT a vacuum solution: #{worst} reaches #{fmt_e(max_abs)}" }
    when :einstein_lambda
      h = spec[:params]['H']
      # absolute floor so H = 0 (a legitimately flat de Sitter) does not turn
      # the relative tolerance into "must be < 0"
      passed = lam_dev < [1e-7 * 3 * h * h, 1e-10].max
      { kind: 'einstein_lambda', max_abs: fmt_e(max_abs), max_dev: fmt_e(lam_dev), passed: passed,
        display: "R_uv = 3H² g_uv  (H = #{h})",
        note: passed ? "Einstein equation with Λ verified: max |R_uv − 3H² g_uv| = #{fmt_e(lam_dev)} - and its SIGN pins the curvature convention" :
                       "R_uv does not equal 3H² g_uv (deviation #{fmt_e(lam_dev)})" }
    else
      { kind: 'structural', max_abs: fmt_e(max_abs), passed: true,
        display: 'no closed-form oracle for a custom metric',
        note: 'custom metric: Ricci computed, but only the structural identities below are checkable - no oracle, and this label says so' }
    end
  end

  def symmetry_checks(ctx, spec, envs)
    max_r = 0.0
    a1 = a2 = pr = bi = 0.0
    term_scale = 1e-12   # magnitude of the summed dG / G*G terms: the roundoff yardstick
    envs.first(5).each do |env|
      gt = gamma_table(ctx, env)
      dgt = dgamma_table(ctx, env)
      gmax = gt.flatten.map(&:abs).max
      dmax = dgt.flatten.flatten.map(&:abs).max
      term_scale = [term_scale, dmax, 4 * gmax * gmax].max
      gv = (0...4).map { |i| ctx[:g][i].evaluate(env).to_f }
      # lower the first index: R_{rsuv} = g_rr R^r_{suv}
      rl = Array.new(4) { |r| Array.new(4) { |s| Array.new(4) { |u| Array.new(4) { |v| gv[r] * riemann_up(gt, dgt, r, s, u, v) } } } }
      4.times do |r|
        4.times do |s|
          4.times do |u|
            4.times do |v|
              val = rl[r][s][u][v]
              max_r = [max_r, val.abs].max
              a1 = [a1, (val + rl[s][r][u][v]).abs].max
              a2 = [a2, (val + rl[r][s][v][u]).abs].max
              pr = [pr, (val - rl[u][v][r][s]).abs].max
              bi = [bi, (rl[r][s][u][v] + rl[r][u][v][s] + rl[r][v][s][u]).abs].max
            end
          end
        end
      end
    end
    # Roundoff lives at the scale of the summed terms (dG, G*G products), NOT
    # at the scale of the final Riemann - for a flat metric in curvilinear
    # coordinates the Riemann is ~0 while the terms are O(1), and normalising
    # by the result would turn pure roundoff into a fake violation.
    scale = [max_r, term_scale].max
    passed = [a1, a2, pr, bi].all? { |x| x / scale < 1e-9 }
    { passed: passed, max_riemann: fmt_e(max_r),
      antisym_first_pair: fmt_e(a1 / scale), antisym_second_pair: fmt_e(a2 / scale),
      pair_symmetry: fmt_e(pr / scale), first_bianchi: fmt_e(bi / scale),
      note: passed ? 'all four Riemann index identities hold to 1e-9 of the term scale - an index slip anywhere would break at least one' :
                     'a Riemann symmetry is violated - the curvature computation is wrong' }
  end

  def kretschmann_check(ctx, spec, envs)
    worst = 0.0
    rmax = 1e-300
    tsca = 1e-300
    m = spec[:params]['M']
    envs.each do |env|
      gt = gamma_table(ctx, env)
      dgt = dgamma_table(ctx, env)
      gmax = gt.flatten.map(&:abs).max || 0.0
      dmax = dgt.flatten.map(&:abs).max || 0.0
      tsca = [tsca, dmax, 4 * gmax * gmax].max
      gv = (0...4).map { |i| ctx[:g][i].evaluate(env).to_f }
      k = 0.0
      4.times do |r|
        4.times do |s|
          4.times do |u|
            4.times do |v|
              rl = gv[r] * riemann_up(gt, dgt, r, s, u, v)
              rmax = [rmax, rl.abs].max
              k += rl * rl / (gv[r] * gv[s] * gv[u] * gv[v])
            end
          end
        end
      end
      expected = 48.0 * m * m / env['r']**6
      # M = 0 is flat space: expected is 0 and the ratio would be NaN - the
      # right check there is that K itself vanishes
      dev = expected.abs < 1e-30 ? k.abs : (k / expected - 1.0).abs
      worst = [worst, dev].max
    end
    # Roundoff floor: each Riemann value carries ~eps * (term scale) of noise
    # from cancelling O(term-scale) pieces. When the curvature itself is tiny
    # (e.g. M = 1e-11: R ~ 1e-13 built from O(1) terms), the RELATIVE deviation
    # of K is roundoff-limited at ~eps*tsca/rmax and a fixed 1e-6 gate would
    # fail mathematically perfect tensors. Strict gate in the normal regime.
    tol = [1e-6, 2e3 * Float::EPSILON * tsca / rmax].max
    passed = worst < tol
    { passed: passed, max_rel_dev: fmt_e(worst), formula: 'K = R_rsuv R^rsuv = 48 M² / r⁶',
      note: passed ? "Kretschmann = 48M²/r⁶ to #{fmt_e(worst)}#{tol > 1e-6 ? " (roundoff-limited regime: curvature ~#{fmt_e(rmax)} from O(#{fmt_e(tsca)}) terms, tolerance #{fmt_e(tol)})" : ''} - a NONZERO oracle, so 'everything is zero' cannot fake this pass" :
                     "Kretschmann deviates from 48M²/r⁶ by #{fmt_e(worst)} (tolerance #{fmt_e(tol)})" }
  end

  # ------------------------------------------------------------ the orbit

  def geodesic_orbit(ctx, spec, opts)
    m = spec[:params]['M']
    r_p = (opts['r_p'] || opts[:r_p] || 40.0).to_f
    r_a = (opts['r_a'] || opts[:r_a] || 60.0).to_f
    orbits = (opts['orbits'] || opts[:orbits] || 4).to_i.clamp(2, 8)
    raise 'need 2M < r_p < r_a (outside the horizon, bound orbit)' unless 2 * m < r_p && r_p < r_a

    fmet = ->(r) { 1.0 - 2.0 * m / r }
    a_ = fmet.call(r_p)
    b_ = fmet.call(r_a)
    l2 = (b_ - a_) / (a_ / r_p**2 - b_ / r_a**2)
    e2 = a_ * (1 + l2 / r_p**2)
    raise 'no bound timelike orbit for these radii' unless l2.positive? && e2.positive?
    e_cons = Math.sqrt(e2)
    l_cons = Math.sqrt(l2)

    sma = (r_p + r_a) / 2.0
    period = 2 * Math::PI * Math.sqrt(sma**3 / m)
    dtau = period / 2600.0
    max_steps = [(orbits + 1.2) * 2600, 30_000].min.to_i

    cs = spec[:coords]
    x = [0.0, r_a, Math::PI / 2, 0.0]
    u = [e_cons / b_, 0.0, 0.0, l_cons / r_a**2]

    env_of = ->(xx) { spec[:params].merge(cs[0] => xx[0], cs[1] => xx[1], cs[2] => xx[2], cs[3] => xx[3]) }
    accel = lambda do |xx, uu|
      gt = gamma_table(ctx, env_of.call(xx))
      (0...4).map do |lam|
        s = 0.0
        4.times { |mu| 4.times { |nu| gv = gt[lam][mu][nu]; s += gv * uu[mu] * uu[nu] unless gv.zero? } }
        -s
      end
    end

    path = []
    perihelia = []
    drift_e = drift_l = drift_n = 0.0
    prev_ur = 0.0
    prev_phi = 0.0
    max_steps.times do |i|
      # RK4 on the 8-dim state
      k1x = u
      k1u = accel.call(x, u)
      x2 = axpy4(x, k1x, dtau / 2)
      u2 = axpy4(u, k1u, dtau / 2)
      k2x = u2
      k2u = accel.call(x2, u2)
      x3 = axpy4(x, k2x, dtau / 2)
      u3 = axpy4(u, k2u, dtau / 2)
      k3x = u3
      k3u = accel.call(x3, u3)
      x4 = axpy4(x, k3x, dtau)
      u4 = axpy4(u, k3u, dtau)
      k4x = u4
      k4u = accel.call(x4, u4)
      x = (0...4).map { |j| x[j] + dtau / 6 * (k1x[j] + 2 * k2x[j] + 2 * k3x[j] + k4x[j]) }
      u = (0...4).map { |j| u[j] + dtau / 6 * (k1u[j] + 2 * k2u[j] + 2 * k3u[j] + k4u[j]) }

      path << [x[1] * Math.cos(x[3]), x[1] * Math.sin(x[3])] if (i % [max_steps / 1100, 1].max).zero?
      if prev_ur.negative? && u[1] >= 0
        fr = prev_ur / (prev_ur - u[1])
        perihelia << prev_phi + fr * (x[3] - prev_phi)
      end
      prev_ur = u[1]
      prev_phi = x[3]

      if (i % 40).zero?
        f_here = fmet.call(x[1])
        drift_e = [drift_e, (f_here * u[0] / e_cons - 1).abs].max
        drift_l = [drift_l, (x[1]**2 * Math.sin(x[2])**2 * u[3] / l_cons - 1).abs].max
        norm = -f_here * u[0]**2 + u[1]**2 / f_here + x[1]**2 * u[2]**2 + x[1]**2 * Math.sin(x[2])**2 * u[3]**2
        drift_n = [drift_n, (norm + 1).abs].max
      end
      break if perihelia.size > orbits
    end

    advances = perihelia.each_cons(2).map { |p1, p2| p2 - p1 - 2 * Math::PI }
    measured = advances.empty? ? nil : advances.sum / advances.size
    ell = 2.0 * r_p * r_a / (r_p + r_a)
    theory = 6 * Math::PI * m / ell
    rel_err = measured ? (measured / theory - 1).abs : nil

    # Mercury, from the verified formula with real constants
    gm_sun_km = 1.47664
    a_mer = 5.7909050e7
    e_mer = 0.205630
    orbits_per_century = 36_525.0 / 87.9691
    mercury = 6 * Math::PI * gm_sun_km / (a_mer * (1 - e_mer**2)) * orbits_per_century * 206_264.806

    conserved_ok = drift_e < 1e-6 && drift_l < 1e-6 && drift_n < 1e-5
    prec_ok = !measured.nil? && rel_err < 0.12
    # The VERDICT rests on the exact conservation laws only. 6piM/ell is a
    # first-order PN approximation: a strongly relativistic orbit disagreeing
    # with it is physics, not an error - failing a mathematically correct
    # geodesic for out-precessing a first-order formula would itself be the
    # kind of confidently-wrong claim this engine refuses to make.
    prec_note = if measured.nil?
                  'too few perihelion passes to measure the advance - increase orbits'
                else
                  "perihelion advance #{(measured * 180 / Math::PI).round(3)}°/orbit vs 6πM/ℓ = #{(theory * 180 / Math::PI).round(3)}° (#{(rel_err * 100).round(1)}% off - #{prec_ok ? 'within' : 'beyond'} the first-order PN tolerance#{prec_ok ? '' : ', expected for strongly relativistic orbits'}; corroboration, not the verdict)"
                end
    {
      r_p: r_p, r_a: r_a, orbits: orbits, path: path,
      perihelion_angles: perihelia.map { |p| (p % (2 * Math::PI)).round(5) },
      precession_measured_deg: measured ? (measured * 180 / Math::PI).round(4) : nil,
      precession_theory_deg: (theory * 180 / Math::PI).round(4),
      precession_rel_err: rel_err ? rel_err.round(4) : nil,
      precession_matches_pn: prec_ok,
      conservation: { energy_drift: fmt_e(drift_e), ang_momentum_drift: fmt_e(drift_l), norm_drift: fmt_e(drift_n) },
      mercury_arcsec_per_century: mercury.round(2),
      verification: {
        passed: conserved_ok,
        verdict: if !conserved_ok
                   'FAILED - a conserved quantity drifted: the Christoffels or the integrator are wrong'
                 else
                   "orbit integrated on the COMPUTED Christoffels: E, L and the 4-velocity norm conserved to #{fmt_e([drift_e, drift_l, drift_n].max)}; #{prec_note}"
                 end
      }
    }
  end

  def axpy4(a, b, h)
    (0...4).map { |i| a[i] + h * b[i] }
  end

  # ------------------------------------------------------------ presentation

  def list_christoffels(ctx, cs)
    ctx[:gamma_list].map do |l, u, v, e|
      disp = MathematicalExpression.new(e.root.to_infix)
      disp.use_experimental_simplification = true
      begin
        gr_silence { disp.simplify(max_iterations: 18) }
      rescue StandardError
        disp = e
      end
      s = disp.to_readable_string
      s = e.to_readable_string if s.nil? || s.empty?
      { symbol: "Γ^#{GREEK[cs[l]] || cs[l]}_#{sub2(cs[u], cs[v])}", expr: s.length > 90 ? s[0, 87] + '…' : s }
    end
  end

  def sub2(a, b)
    "{#{GREEK[a] || a} #{GREEK[b] || b}}"
  end

  def overall_verdict(spec)
    case spec[:oracle]
    when :flat then 'VERIFIED: flat spacetime - every Christoffel and curvature component vanishes'
    when :vacuum then 'VERIFIED: a vacuum solution - all 10 Ricci components vanish, Kretschmann = 48M²/r⁶, all Riemann identities hold, and the orbit precesses as GR demands'
    when :einstein_lambda then 'VERIFIED: R_uv = 3H² g_uv - de Sitter solves the Λ-vacuum Einstein equation, sign convention pinned'
    else 'computed - structural identities hold; no closed-form oracle exists for a custom metric, and this verdict says so'
    end
  end

  def build_steps(spec, ctx, ricci, sym, kre, orb)
    steps = []
    steps << { rule: "Metric (#{spec[:label]}): ds² = #{spec[:coords].each_index.map { |i| "(#{spec[:metric][i]}) d#{GREEK[spec[:coords][i]] || spec[:coords][i]}²" }.join(' + ')}" }
    steps << { rule: "Christoffel: Γ^λ_{μν} = (∂_μ g_λν + ∂_ν g_λμ − ∂_λ g_μν) / (2 g_λλ) - #{ctx[:gamma_list].size} nonzero symbols, every derivative SYMBOLIC (parameters stay symbolic)" }
    steps << { rule: 'Riemann: R^ρ_{σμν} = ∂_μ Γ^ρ_{νσ} − ∂_ν Γ^ρ_{μσ} + Γ^ρ_{μλ}Γ^λ_{νσ} − Γ^ρ_{νλ}Γ^λ_{μσ}; Ricci by contraction' }
    steps << { rule: ricci[:note] }
    steps << { rule: sym[:note] }
    steps << { rule: kre[:note] } if kre
    steps << { rule: orb[:verification] ? orb[:verification][:verdict] : orb[:skipped] } if orb
    steps
  end

  def fmt_e(v)
    return 'inf' unless v.finite?
    v < 1e-14 ? '<1e-14' : format('%.3g', v)
  end
end


# ===== exact_arithmetic.rb =====
# Exact rational arithmetic - the gate that Gosper and Rothstein-Trager sit behind.
#
# ============================================================================
# HOW THIS DIFFERS FROM THE TWO EVALUATORS WE ALREADY HAD
# ============================================================================
# The engine can now evaluate the SAME expression tree three ways. They are not
# competing implementations - they answer three different questions, and the UI
# colour-codes them accordingly:
#
#   evaluate           (float)      AMBER  "what is it, roughly?"
#       always answers, never refuses, silently approximate.
#       0.1 + 0.2 -> 0.30000000000000004, and sin(pi) -> 1.22e-16 instead of 0.
#       Fast. Every existing feature runs on this.
#
#   evaluate_interval  (certified)  GREEN  "what bracket provably contains it?"
#       always answers, never refuses, PROVEN but inexact-by-construction:
#       it returns a range, and for a hard case that range can be wide.
#       (interval_arithmetic.rb, section 18 of the technical reference)
#
#   evaluate_exact     (exact)      PURPLE "what is it EXACTLY, or nothing"
#       <-- NEW. Returns a Ruby Rational with zero error, or REFUSES.
#       0.1 + 0.2 -> exactly 3/10. sin(0) -> exactly 0. sin(1) -> refused,
#       because it is irrational and no rational answer exists.
#
# The refusal is the point. Float answers everything and is sometimes wrong by
# 1e-16; exact answers less and is never wrong at all. Zero-testing is the
# operation that matters: "is this coefficient zero?" is a GUESS at 1e-10
# tolerance in float, and a FACT in exact arithmetic. Every decision procedure
# (Risch, Rothstein-Trager, Gosper) is built out of exact zero-tests, which is
# why none of them could be built on the float core.
#
# ============================================================================
# WHY A SEPARATE POLYNOMIAL TYPE
# ============================================================================
# polynomial.rb cannot be retrofitted: its constructor runs `coeff.to_f` on
# every coefficient, so a Rational cannot survive being stored. Its gcd also
# normalises with `scale(1.0 / lc)` - a float division. ExactPolynomial below
# is the parallel type with Rational coefficients, exact divmod, exact GCD (via
# primitive PRS, so intermediate coefficients do not explode), squarefree
# decomposition (Yun) and resultants - the last two being exactly the
# ingredients Rothstein-Trager needs.
#
# Nothing here changes existing behaviour: the float path is untouched and
# remains the default. This module only ADDS a second, switchable mode.


module ExactOps
  module_function

  # Guard against rational blow-up: exact arithmetic is exact, not free, and a
  # runaway denominator would hang rather than answer. Refusing is honest.
  MAX_BITS = 4096

  def too_big?(r)
    return true unless r.is_a?(Rational) || r.is_a?(Integer)
    r = Rational(r) unless r.is_a?(Rational)
    r.numerator.bit_length > MAX_BITS || r.denominator.bit_length > MAX_BITS
  end

  # ---- float -> exact rational -------------------------------------------
  #
  # The parser floats everything ("2" becomes 2.0), so recovering an exact
  # value means deciding what a float MEANT. Two genuinely different cases,
  # and the distinction is reported rather than hidden:
  #
  #   :exact     the float is already the rational, bit for bit. 2.0 IS 2,
  #              0.5 IS 1/2 (binary fractions are exact).
  #   :recovered the float is the nearest double to a decimal the user typed.
  #              0.1 is NOT 1/10 (it is 3602879701896397/36028797018963968),
  #              but 1/10 is unambiguously what was meant, and 1/10 is the
  #              nearest simple rational whose double IS this float.
  #
  # Anything else (an irrational-looking double with no small-denominator
  # reading) is refused rather than silently rationalised.
  def from_float(v, max_den = 10**9)
    return [nil, :not_numeric, nil] unless v.is_a?(Numeric)
    return [nil, :not_finite, nil] unless v.to_f.finite?
    f = v.to_f
    return [Rational(f.to_i, 1), :exact, nil] if f == f.to_i && f.abs < 1e15

    binary = f.to_r                      # always exact: the double's true value
    return [binary, :exact, nil] if binary.denominator <= max_den

    simple = f.rationalize(Float::EPSILON * [f.abs, 1.0].max)
    if simple.denominator <= max_den && simple.to_f == f
      [simple, :recovered, "#{f} read as #{simple} (nearest simple rational with this exact double)"]
    else
      [nil, :irrational, "#{f} has no small-denominator rational reading - refusing to invent one"]
    end
  end

  # perfect n-th root of a rational, or nil
  def exact_root(r, n)
    return nil unless r.is_a?(Rational) && n.is_a?(Integer) && n > 0
    return nil if r.negative? && n.even?
    sign = r.negative? ? -1 : 1
    a = r.abs
    rn = integer_root(a.numerator, n)
    rd = integer_root(a.denominator, n)
    return nil unless rn && rd
    Rational(sign * rn, rd)
  end

  def integer_root(n, k)
    return nil if n.negative?
    return 0 if n.zero?
    r = Integer.sqrt(n) if k == 2
    unless k == 2
      r = Integer(n**(1.0 / k) + 0.5)
      r -= 1 while r > 1 && r**k > n
      r += 1 while (r + 1)**k <= n
    end
    r**k == n ? r : nil
  end
end

# evaluate_exact sits beside evaluate and evaluate_interval on the SAME tree.
# It returns a Rational, or nil with a recorded reason - never a float.
class ExpressionNode
  # blockers: optional array; every refusal appends a human-readable reason, so
  # the UI can say WHY exactness was impossible instead of just failing.
  def evaluate_exact(env = {}, blockers = nil)
    if isleaf
      if data.is_a?(Numeric)
        v, kind, note = ExactOps.from_float(data)
        blockers << note if note && kind == :irrational && blockers
        blockers << note if note && kind == :recovered && blockers
        return v
      end
      key = data.to_s
      unless env.key?(key)
        blockers << "no exact value supplied for '#{key}'" if blockers
        return nil
      end
      ev = env[key]
      return ev if ev.is_a?(Rational)
      v, kind, note = ExactOps.from_float(ev)
      blockers << note if note && kind != :exact && blockers
      return v
    end

    l = left ? left.evaluate_exact(env, blockers) : nil
    r = right ? right.evaluate_exact(env, blockers) : nil

    case data
    when '+', '-', '*'
      return nil if l.nil? || r.nil?
      out = data == '+' ? l + r : data == '-' ? l - r : l * r
      guard(out, blockers)
    when '/'
      return nil if l.nil? || r.nil?
      if r.zero?
        blockers << 'division by exactly zero' if blockers
        return nil
      end
      guard(l / r, blockers)
    when '^'
      return nil if l.nil? || r.nil?
      if r.denominator == 1
        n = r.numerator
        if n.abs > 4096
          blockers << "exponent #{n} is too large for exact expansion" if blockers
          return nil
        end
        if l.zero? && n.negative?
          blockers << 'zero raised to a negative power' if blockers
          return nil
        end
        return guard(l**n, blockers)
      end
      # rational exponent: exact only when the root comes out exactly
      root = ExactOps.exact_root(l, r.denominator)
      if root.nil?
        blockers << "#{l}^(#{r}) is irrational (no exact #{r.denominator}-th root)" if blockers
        return nil
      end
      guard(root**r.numerator, blockers)
    when 'sqrt'
      return nil if r.nil?
      root = ExactOps.exact_root(r, 2)
      if root.nil?
        blockers << "sqrt(#{r}) is irrational" if blockers
        return nil
      end
      root
    when 'abs'
      r&.abs
    when 'exp'
      # e^0 = 1 exactly; every other power of e is transcendental
      return nil if r.nil?
      return Rational(1, 1) if r.zero?
      blockers << "exp(#{r}) is transcendental - no exact rational value" if blockers
      nil
    when 'ln'
      return nil if r.nil?
      return Rational(0, 1) if r == 1
      blockers << "ln(#{r}) is transcendental (only ln(1) = 0 is rational)" if blockers
      nil
    when 'sin', 'tan', 'sinh', 'tanh', 'arcsin', 'arctan'
      # all vanish at 0 and are irrational at every other rational point
      # (Niven / Lindemann); pi is not even representable here, since the
      # lexer substitutes it as a float literal
      return nil if r.nil?
      return Rational(0, 1) if r.zero?
      blockers << "#{data}(#{r}) is irrational for every nonzero rational argument" if blockers
      nil
    when 'cos', 'cosh'
      return nil if r.nil?
      return Rational(1, 1) if r.zero?
      blockers << "#{data}(#{r}) is irrational for every nonzero rational argument" if blockers
      nil
    else
      blockers << "'#{data}' has no exact rational evaluation" if blockers
      nil
    end
  end

  private

  def guard(v, blockers)
    return nil if v.nil?
    v = Rational(v) unless v.is_a?(Rational)
    if ExactOps.too_big?(v)
      blockers << 'intermediate rational exceeded the size budget - refusing rather than hanging' if blockers
      return nil
    end
    v
  end
end

# ============================================================================
# ExactPolynomial - Rational coefficients, exact everything.
# ============================================================================
# The parallel to polynomial.rb, but nothing is ever coerced to Float, so:
#   * "is this coefficient zero?" is a fact, not a 1e-10 judgement call
#   * gcd is exact, and uses the PRIMITIVE PRS so intermediate coefficients
#     stay bounded instead of exploding the way naive rational Euclid does
#   * squarefree decomposition (Yun) and resultants become available - these
#     are the two pieces Rothstein-Trager is built from
class ExactPolynomial
  attr_reader :coeffs   # {degree => Rational}, zero coefficients never stored

  def initialize(coeffs = {})
    @coeffs = {}
    coeffs.each do |d, c|
      r = c.is_a?(Rational) ? c : Rational(c)
      @coeffs[d.to_i] = r unless r.zero?
    end
  end

  def self.zero
    new({})
  end

  def self.one
    new({ 0 => Rational(1, 1) })
  end

  # from an array of Rationals, lowest degree first
  def self.from_a(arr)
    new(arr.each_with_index.to_h { |c, i| [i, c] })
  end

  # Build from an ExpressionNode, exactly. Returns [poly, nil] or [nil, reason].
  # Refuses (rather than approximating) anything that is not a polynomial with
  # exactly-recoverable rational coefficients.
  def self.from_expression(node, variable, blockers = nil)
    return [nil, 'empty expression'] if node.nil?
    p = build(node, variable, blockers)
    p ? [p, nil] : [nil, (blockers && blockers.last) || 'not a polynomial with exact rational coefficients']
  end

  def self.build(node, variable, blockers)
    return nil if node.nil?
    if node.isleaf
      return new({ 1 => Rational(1, 1) }) if node.data.to_s == variable
      v, kind, note = ExactOps.from_float(node.data) if node.data.is_a?(Numeric)
      if node.data.is_a?(Numeric)
        blockers << note if note && blockers
        return v ? new({ 0 => v }) : nil
      end
      blockers << "symbol '#{node.data}' is not the variable and has no exact value" if blockers
      return nil
    end
    l = node.left ? build(node.left, variable, blockers) : nil
    r = node.right ? build(node.right, variable, blockers) : nil
    case node.data
    when '+' then l && r ? l + r : nil
    when '-' then l && r ? l - r : nil
    when '*' then l && r ? l * r : nil
    when '/'
      return nil unless l && r
      unless r.degree <= 0
        blockers << 'division by a non-constant polynomial' if blockers
        return nil
      end
      return nil if r.zero?
      l.scale(Rational(1, 1) / r.coeffs[0])
    when '^'
      return nil unless l && r
      unless r.degree <= 0 && r.constant? && r.coeffs.fetch(0, Rational(0)).denominator == 1
        blockers << 'only integer exponents are polynomial' if blockers
        return nil
      end
      n = r.coeffs.fetch(0, Rational(0)).numerator
      if n.negative? || n > 64
        blockers << "exponent #{n} is not a polynomial power (or is too large)" if blockers
        return nil
      end
      out = one
      n.times { out *= l }
      out
    else
      blockers << "'#{node.data}' is not polynomial" if blockers
      nil
    end
  end

  # --- structure ---
  def degree
    @coeffs.empty? ? -1 : @coeffs.keys.max
  end

  def zero?
    @coeffs.empty?
  end

  def constant?
    degree <= 0
  end

  def lc
    @coeffs.empty? ? Rational(0, 1) : @coeffs[degree]
  end

  def [](d)
    @coeffs.fetch(d, Rational(0, 1))
  end

  def ==(other)
    other.is_a?(ExactPolynomial) && coeffs == other.coeffs
  end

  # --- exact arithmetic ---
  def +(other)
    out = @coeffs.dup
    other.coeffs.each { |d, c| out[d] = (out[d] || Rational(0, 1)) + c }
    ExactPolynomial.new(out)
  end

  def -(other)
    out = @coeffs.dup
    other.coeffs.each { |d, c| out[d] = (out[d] || Rational(0, 1)) - c }
    ExactPolynomial.new(out)
  end

  def *(other)
    out = {}
    @coeffs.each do |d1, c1|
      other.coeffs.each do |d2, c2|
        out[d1 + d2] = (out[d1 + d2] || Rational(0, 1)) + c1 * c2
      end
    end
    ExactPolynomial.new(out)
  end

  def scale(k)
    k = Rational(k) unless k.is_a?(Rational)
    ExactPolynomial.new(@coeffs.transform_values { |c| c * k })
  end

  def derivative
    ExactPolynomial.new(@coeffs.reject { |d, _| d.zero? }.to_h { |d, c| [d - 1, c * d] })
  end

  # exact long division: self = q*other + r, with deg r < deg other
  def divmod(other)
    raise ArgumentError, 'division by the zero polynomial' if other.zero?
    r = ExactPolynomial.new(@coeffs.dup)
    q = ExactPolynomial.zero
    while !r.zero? && r.degree >= other.degree
      shift = r.degree - other.degree
      factor = r.lc / other.lc
      term = ExactPolynomial.new({ shift => factor })
      q += term
      r -= term * other
    end
    [q, r]
  end

  # --- the pieces Rothstein-Trager needs ---

  # content = gcd of the integer numerators over lcm of denominators
  def content
    return Rational(0, 1) if zero?
    num = @coeffs.values.map { |c| c.numerator.abs }.reduce { |a, b| a.gcd(b) }
    den = @coeffs.values.map(&:denominator).reduce { |a, b| a.lcm(b) }
    Rational(num, den)
  end

  # divide out the content, then fix the sign so the leading coefficient is
  # positive: this is a CANONICAL form (integer coefficients, gcd 1, lc > 0),
  # where the float version could only offer "monic", i.e. lc scaled to 1.0
  def primitive_part
    return self if zero?
    c = content
    return self if c.zero?
    p = scale(Rational(1, 1) / c)
    p.lc.negative? ? p.scale(Rational(-1, 1)) : p
  end

  # Exact GCD via the primitive PRS. Naive rational Euclid is correct but its
  # intermediate coefficients blow up; taking the primitive part each round
  # keeps them small. Result is normalised primitive with positive leading
  # coefficient - a canonical form, unlike the float version's monic scaling.
  def gcd(other)
    a = primitive_part
    b = other.primitive_part
    until b.zero?
      _, r = a.divmod(b)
      a = b
      b = r.zero? ? r : r.primitive_part
    end
    a.zero? ? a : a.primitive_part
  end

  # Extended Euclid over Q[x]: returns [g, u, v] with u*self + v*other = g.
  # This is what makes QQ(alpha) a FIELD rather than just a ring: to invert an
  # element p(alpha) you solve u*p + v*m = 1 and read off u. Only possible with
  # exact arithmetic - a float remainder that never quite reaches zero would
  # leave the recursion with no terminating step.
  def ext_gcd(other)
    r0 = self
    r1 = other
    s0 = ExactPolynomial.one
    s1 = ExactPolynomial.zero
    t0 = ExactPolynomial.zero
    t1 = ExactPolynomial.one
    until r1.zero?
      q, r = r0.divmod(r1)
      r0, r1 = r1, r
      s0, s1 = s1, s0 - q * s1
      t0, t1 = t1, t0 - q * t1
    end
    # normalise so the gcd is monic (a canonical representative)
    unless r0.zero?
      inv = Rational(1, 1) / r0.lc
      r0 = r0.scale(inv)
      s0 = s0.scale(inv)
      t0 = t0.scale(inv)
    end
    [r0, s0, t0]
  end

  # Yun's algorithm: f = prod_i a_i^i with each a_i squarefree and coprime.
  # Requires characteristic 0 and exact gcd - impossible on the float core.
  def squarefree_decomposition
    return [] if zero? || constant?
    f = primitive_part
    fp = f.derivative
    a0 = f.gcd(fp)
    b, = f.divmod(a0)
    c, = fp.divmod(a0)
    d = c - b.derivative
    out = []
    i = 1
    while b.degree > 0
      ai = b.gcd(d)
      out << [i, ai] if ai.degree > 0
      bn, = b.divmod(ai)
      cn, = d.divmod(ai)
      b = bn
      d = cn - b.derivative
      i += 1
      break if i > 64
    end
    out
  end

  def squarefree?
    d = derivative
    return true if d.zero?
    gcd(d).degree <= 0
  end

  # Resultant via the Euclidean PRS with the standard bookkeeping:
  #   res(A,B) = (-1)^(deg A * deg B) * lc(B)^(deg A - deg R) * res(B, R)
  # Res(f, f') = 0 exactly when f has a repeated root - an EXACT test, where
  # the float version could only ever compare a determinant against 1e-10.
  def resultant(other)
    a = self
    b = other
    return Rational(0, 1) if a.zero? || b.zero?
    s = Rational(1, 1)
    loop do
      return s * b.lc**a.degree if b.degree.zero?
      return Rational(0, 1) if a.degree.negative? || b.degree.negative?
      _, r = a.divmod(b)
      return Rational(0, 1) if r.zero?
      s *= Rational((-1)**(a.degree * b.degree), 1) * b.lc**(a.degree - r.degree)
      a = b
      b = r
    end
  end

  # exact rational roots (rational root theorem + exact verification)
  def rational_roots
    return [] if zero? || degree < 1
    scaled = scale(@coeffs.values.map(&:denominator).reduce(1) { |a, b| a.lcm(b) })
    ints = scaled.coeffs.transform_values { |c| c.numerator }
    a0 = ints[ints.keys.min] || 0
    an = ints[ints.keys.max] || 0
    return [] if an.zero?
    trailing = a0.zero? ? 1 : a0.abs
    ps = divisors(trailing)
    qs = divisors(an.abs)
    cands = []
    ps.each { |p| qs.each { |q| cands << Rational(p, q) << Rational(-p, q) } }
    cands << Rational(0, 1) if a0.zero?
    cands.uniq.select { |c| eval_at(c).zero? }.sort
  end

  def divisors(n)
    n = n.abs
    return [1] if n <= 1
    (1..Integer.sqrt(n)).each_with_object([]) do |i, acc|
      next unless (n % i).zero?
      acc << i
      acc << n / i
    end.uniq
  end

  def eval_at(x)
    x = Rational(x) unless x.is_a?(Rational)
    @coeffs.sum(Rational(0, 1)) { |d, c| c * x**d }
  end

  def to_s(variable = 'x')
    return '0' if zero?
    @coeffs.keys.sort.reverse.map do |d|
      c = @coeffs[d]
      mag = c.abs
      cs = mag == 1 && d > 0 ? '' : (mag.denominator == 1 ? mag.numerator.to_s : "#{mag.numerator}/#{mag.denominator}")
      body = d.zero? ? cs : (d == 1 ? "#{cs}#{cs.empty? ? '' : '*'}#{variable}" : "#{cs}#{cs.empty? ? '' : '*'}#{variable}^#{d}")
      [c.negative? ? '-' : '+', body]
    end.each_with_index.map { |(sg, b), i| i.zero? ? (sg == '-' ? "-#{b}" : b) : " #{sg} #{b}" }.join
  end

  def to_pairs
    @coeffs.keys.sort.reverse.map { |d| [d, rat_str(@coeffs[d])] }
  end

  def rat_str(c)
    c.denominator == 1 ? c.numerator.to_s : "#{c.numerator}/#{c.denominator}"
  end
end


# ===== algebraic_field.rb =====
# QQ(alpha) - simple algebraic extensions of the rationals.
#
# ============================================================================
# WHAT THIS ADDS TO THE STEP BEFORE IT
# ============================================================================
# exact_arithmetic.rb gave us exact rationals - and made a point of REFUSING
# sqrt(2), because sqrt(2) is not rational and inventing a rational for it
# would be a lie. This module is the field where it no longer has to refuse.
#
#   exact (QQ)      sqrt(2)  ->  refused: "irrational"
#   algebraic QQ(a) sqrt(2)  ->  alpha, exactly, with alpha^2 = 2 EXACTLY
#
# An element is a polynomial in alpha of degree < deg(m), with Rational
# coefficients, reduced modulo the minimal polynomial m. So sqrt(2) is not
# stored as 1.4142135623730951 (which squares to 2.0000000000000004) - it is
# stored as the symbol alpha together with the rule alpha^2 = 2, and squaring
# it gives exactly 2. Every operation stays exact, including the ZERO TEST,
# which is the property every decision procedure is built on.
#
# ============================================================================
# WHY ROTHSTEIN-TRAGER NEEDS EXACTLY THIS
# ============================================================================
# RT computes  Res_x(f - c*g', g)  as a polynomial in c, takes its roots c_i,
# and returns  sum_i c_i * log(gcd(f - c_i*g', g)).  Those c_i are ALGEBRAIC,
# not rational - for 1/(x^4+1) they are not even real. So the log part lives
# over QQ(alpha), and computing that gcd means running polynomial GCD with
# coefficients in QQ(alpha). That needs division in QQ(alpha), which needs
# inverses, which needs the extended Euclid we just added to ExactPolynomial.
# This module is that field; polynomials OVER it are the next step, not this
# one, and RT itself is neither implemented nor claimed.
#
# ============================================================================
# HONESTY
# ============================================================================
# QQ[x]/(m) is a field only when m is IRREDUCIBLE. Proving irreducibility over
# QQ in general is real work, so this module states exactly what it checked:
#   * squarefree           - verified exactly (gcd(m, m') is constant)
#   * no rational roots    - verified exactly (rules out linear factors)
#   * degree <= 3          - the two checks above are then a PROOF
#   * degree >= 4          - they are not; the field is reported as ASSUMED,
#                            and a failed inverse later is reported as what it
#                            actually is: a PROOF that m was reducible.
# Norm is computed two independent ways (resultant of m with the element, and
# the determinant of the multiplication matrix) and they must agree.


class AlgebraicField
  attr_reader :min_poly, :degree, :alpha_num, :variable, :irreducible, :irreducible_note

  # min_poly: ExactPolynomial, made monic here. alpha_num: a float root, used
  # only for the numeric embedding (display + the independent cross-check).
  def initialize(min_poly, alpha_num, variable = 'a')
    raise 'the minimal polynomial must have degree >= 1' if min_poly.degree < 1
    @min_poly = min_poly.scale(Rational(1, 1) / min_poly.lc)  # monic
    @degree = @min_poly.degree
    @alpha_num = alpha_num
    @variable = variable
    @irreducible, @irreducible_note = check_irreducible
  end

  # What we can honestly say about m being irreducible (see the header).
  def check_irreducible
    sqfree = @min_poly.gcd(@min_poly.derivative).degree <= 0
    return [false, 'm is not squarefree, so QQ[x]/(m) has nilpotents and is definitely not a field'] unless sqfree
    roots = @min_poly.rational_roots
    if roots.any? && @degree > 1
      return [false, "m has the rational root #{roots.first}, so it factors - QQ[x]/(m) is not a field"]
    end
    if @degree <= 3
      [true, "PROVEN irreducible: squarefree with no rational roots, and for degree #{@degree} that is sufficient"]
    else
      [nil, "ASSUMED irreducible: squarefree with no rational roots, but for degree #{@degree} that is not a proof (it could factor into two quadratics). If an inverse ever fails, that failure is itself a proof that m factors."]
    end
  end

  def element(poly)
    AlgebraicNumber.new(self, reduce(poly))
  end

  def from_rational(r)
    element(ExactPolynomial.new({ 0 => r.is_a?(Rational) ? r : Rational(r) }))
  end

  def zero
    element(ExactPolynomial.zero)
  end

  def one
    element(ExactPolynomial.one)
  end

  # alpha itself: the generator
  def alpha
    element(ExactPolynomial.new({ 1 => Rational(1, 1) }))
  end

  def reduce(poly)
    return poly if poly.degree < @degree
    _, r = poly.divmod(@min_poly)
    r
  end

  # multiplication-by-beta matrix in the basis 1, alpha, ..., alpha^(n-1)
  def mult_matrix(beta)
    (0...@degree).map do |j|
      col = reduce(beta.poly * ExactPolynomial.new({ j => Rational(1, 1) }))
      (0...@degree).map { |i| col[i] }
    end.transpose
  end

  def to_s
    "QQ(#{@variable}) with #{@variable}^#{@degree} defined by #{@min_poly.to_s(@variable)} = 0"
  end

  # ---- known fields, for presets ----
  def self.from_min_poly_string(str, variable = 'a', alpha_num = nil)
    node = MathematicalExpression.new(str.to_s).root
    raise "could not parse '#{str}'" unless node
    p, err = ExactPolynomial.from_expression(node, variable, [])
    raise "minimal polynomial must be an exact polynomial in #{variable}: #{err}" unless p
    new(p, alpha_num || numeric_root(p), variable)
  end

  # A real root by sign-change bracketing + bisection, returning the LARGEST
  # one. m usually has several real roots (x^2-2 has both +-sqrt2) and any of
  # them generates an isomorphic field, so the exact arithmetic does not care
  # which - but the numeric embedding shown to a human should be the expected
  # one: sqrt2 not -sqrt2, phi not -1/phi. nil when there is no real root
  # (QQ(i) is perfectly usable, it just has no real embedding to display).
  def self.numeric_root(p)
    f = ->(x) { p.coeffs.sum(0.0) { |d, c| c.to_f * x**d } }
    best = nil
    x = -50.0
    step = 0.01
    prev = f.call(x)
    while x < 50.0
      x2 = x + step
      cur = f.call(x2)
      if prev == 0.0
        best = x
      elsif (prev * cur).negative?
        a = x
        b = x2
        80.times do
          mid = (a + b) / 2
          f.call(a) * f.call(mid) <= 0 ? b = mid : a = mid
        end
        best = (a + b) / 2
      end
      prev = cur
      x = x2
    end
    best
  end
end

class AlgebraicNumber
  attr_reader :field, :poly

  def initialize(field, poly)
    @field = field
    @poly = poly
  end

  def +(other)
    check!(other)
    AlgebraicNumber.new(@field, @field.reduce(@poly + other.poly))
  end

  def -(other)
    check!(other)
    AlgebraicNumber.new(@field, @field.reduce(@poly - other.poly))
  end

  def *(other)
    check!(other)
    AlgebraicNumber.new(@field, @field.reduce(@poly * other.poly))
  end

  # The interesting one. u*p + v*m = gcd; when m is irreducible and p != 0 the
  # gcd is 1, so u is p's inverse mod m. If the gcd comes back non-constant,
  # that is not a numerical wobble - it is a PROOF that m factors, and it is
  # reported as such rather than swallowed.
  def inverse
    raise ZeroDivisionError, 'zero has no inverse in a field' if zero?
    g, u, = @poly.ext_gcd(@field.min_poly)
    if g.degree.positive?
      raise "cannot invert: gcd(p, m) = #{g.to_s(@field.variable)} has positive degree, which PROVES the minimal polynomial is reducible - QQ[x]/(m) is a ring, not a field"
    end
    AlgebraicNumber.new(@field, @field.reduce(u))
  end

  def /(other)
    self * other.inverse
  end

  def **(n)
    raise ArgumentError, 'integer exponents only' unless n.is_a?(Integer)
    return inverse**(-n) if n.negative?
    out = @field.one
    base = self
    e = n
    while e.positive?
      out *= base if e.odd?
      base *= base
      e >>= 1
    end
    out
  end

  # EXACT zero test - the whole reason this module exists
  def zero?
    @poly.zero?
  end

  def ==(other)
    other.is_a?(AlgebraicNumber) && @field.equal?(other.field) && @poly == other.poly
  end

  def rational?
    @poly.degree <= 0
  end

  def to_rational
    rational? ? @poly[0] : nil
  end

  # N(beta) = product of conjugates. For monic m this is exactly Res(m, p),
  # and it is ALSO the determinant of the multiplication matrix - two
  # independent routes that must agree (checked by norm_consistent?).
  def norm
    @field.min_poly.resultant(@poly)
  end

  def norm_via_matrix
    det(@field.mult_matrix(self))
  end

  def norm_consistent?
    norm == norm_via_matrix
  end

  # trace = sum of conjugates = trace of the multiplication matrix
  def trace
    m = @field.mult_matrix(self)
    (0...@field.degree).sum(Rational(0, 1)) { |i| m[i][i] }
  end

  # exact Gaussian elimination on a Rational matrix
  def det(m)
    n = m.size
    return Rational(1, 1) if n.zero?
    a = m.map(&:dup)
    sign = 1
    d = Rational(1, 1)
    (0...n).each do |k|
      piv = (k...n).find { |i| !a[i][k].zero? }
      return Rational(0, 1) unless piv
      if piv != k
        a[k], a[piv] = a[piv], a[k]
        sign = -sign
      end
      d *= a[k][k]
      ((k + 1)...n).each do |i|
        next if a[i][k].zero?
        f = a[i][k] / a[k][k]
        (k...n).each { |j| a[i][j] -= f * a[k][j] }
      end
    end
    d * sign
  end

  # numeric embedding: only for display and the independent cross-check -
  # never fed back into the exact arithmetic
  def to_f
    r = @field.alpha_num
    return Float::NAN if r.nil?
    @poly.coeffs.sum(0.0) { |d, c| c.to_f * r**d }
  end

  def to_s
    v = @field.variable
    @poly.zero? ? '0' : @poly.to_s(v)
  end

  def check!(other)
    raise ArgumentError, 'elements come from different fields' unless other.is_a?(AlgebraicNumber) && @field.equal?(other.field)
  end
end


# ===== exact_lab.rb =====
# ExactLab - the switchable comparison surface over exact_arithmetic.rb.
#
# ============================================================================
# COLOUR CODING (carried as data, so the UI legend cannot drift out of sync
# with what the engine actually did)
# ============================================================================
#   AMBER  = float      answered, but only approximately  <- the existing path
#   GREEN  = interval   conditional outward-rounded bound <- interval_arithmetic
#   PURPLE = exact      answered with zero error          <- exact_arithmetic
#   GREY   = refused    no exact value exists, and here is why
#
# Modes are genuinely switchable and purely additive: mode 'float' reproduces
# exactly what the engine did before any of this existed, and no existing
# operation is routed through here.


module ExactLab
  module_function

  AMBER  = '#fbbf24'
  GREEN  = '#4ade80'
  PURPLE = '#a78bfa'
  CYAN   = '#22d3ee'
  GREY   = '#94a3b8'

  def run(mode:, expression:, g: nil, variable: 'x', vars: {})
    case mode.to_s
    when 'polynomial' then polynomial_lab(expression, g, variable)
    when 'algebraic'  then algebraic_lab(expression, g)
    when 'float'      then compare(expression, variable, vars, only: :float)
    when 'exact'      then compare(expression, variable, vars, only: :exact)
    else                   compare(expression, variable, vars, only: nil)
    end
  end

  # ---- mode: algebraic (QQ(alpha)) ---------------------------------------
  # expression = the minimal polynomial in 'a'; g = an element to examine,
  # also written in 'a' (blank -> alpha itself).
  def algebraic_lab(min_poly_str, elem_str)
    raise 'enter a minimal polynomial in a' if min_poly_str.nil? || min_poly_str.to_s.strip.empty?
    fld = AlgebraicField.from_min_poly_string(min_poly_str.to_s, 'a')

    es = (elem_str.nil? || elem_str.to_s.strip.empty?) ? 'a' : elem_str.to_s
    node = MathematicalExpression.new(es).root
    raise "could not parse the element '#{es}'" unless node
    ep, eerr = ExactPolynomial.from_expression(node, 'a', [])
    raise "the element must be a polynomial in a: #{eerr}" unless ep
    beta = fld.element(ep)

    # every claim below is exact; the numeric column is an INDEPENDENT oracle
    powers = (1..[fld.degree + 1, 5].min).map do |k|
      bk = beta**k
      { k: k, exact: bk.to_s, numeric: fin(bk.to_f) }
    end

    inv = nil
    inv_err = nil
    begin
      unless beta.zero?
        b1 = beta.inverse
        prod = beta * b1
        inv = { exact: b1.to_s, numeric: fin(b1.to_f), verified: prod == fld.one, product: prod.to_s }
      end
    rescue StandardError => e
      inv_err = e.message
    end

    defining = fld.min_poly.to_s('a')
    # alpha satisfies m exactly: substitute and reduce, must be exactly 0
    sub = fld.reduce(fld.min_poly)
    { mode: 'algebraic',
      field: fld.to_s, degree: fld.degree, min_poly: defining,
      alpha_numeric: fin(fld.alpha_num),
      irreducible: fld.irreducible, irreducible_note: fld.irreducible_note,
      irreducible_color: fld.irreducible == true ? GREEN : (fld.irreducible == false ? '#f87171' : AMBER),
      element: beta.to_s, element_numeric: fin(beta.to_f),
      defining_check: { zero: sub.zero?, text: sub.zero? ? 'm(α) reduces to exactly 0' : "m(α) reduced to #{sub.to_s('a')} - this should be impossible" },
      powers: powers,
      inverse: inv, inverse_error: inv_err,
      norm: rat(beta.norm), trace: rat(beta.trace),
      norm_via_matrix: rat(beta.norm_via_matrix), norm_consistent: beta.norm_consistent?,
      is_rational: beta.rational?,
      steps: algebraic_steps(fld, beta, inv, inv_err) }
  end

  def fin(v)
    return nil if v.nil?
    v.is_a?(Float) && !v.finite? ? nil : v
  end

  def algebraic_steps(fld, beta, inv, inv_err)
    steps = []
    steps << { rule: "Field: #{fld} - elements are polynomials in α of degree < #{fld.degree}, reduced mod m. α is stored as a SYMBOL plus the rule m(α)=0, never as a float." }
    steps << { rule: "Irreducibility: #{fld.irreducible_note}" }
    steps << { rule: "exact_arithmetic.rb REFUSED irrational values like √2; here √2 is α with α²=2 exactly, so squaring gives exactly 2 (float gives 2.0000000000000004)." }
    if inv
      steps << { rule: "Inverse by extended Euclid in Q[x]: u·p + v·m = 1 ⇒ p⁻¹ ≡ u (mod m). Check: p·p⁻¹ = #{inv[:product]}#{inv[:verified] ? ' — exactly 1' : ' — NOT 1, which would be a bug'}" }
    elsif inv_err
      steps << { rule: "Inverse failed: #{inv_err}" }
    end
    steps << { rule: "Norm #{rat(beta.norm)} computed two independent ways (resultant of m with the element, and the determinant of the multiplication matrix) - they #{beta.norm_consistent? ? 'agree' : 'DISAGREE, which is a bug'}. Trace #{rat(beta.trace)}." }
    steps << { rule: 'Why this matters: Rothstein-Trager takes the roots of Res_x(f − c·g′, g) as its constants c_i, and those are algebraic, not rational. They live here. Polynomials OVER this field are the next step; RT itself is not implemented.' }
    steps
  end

  # ---- mode: compare / float / exact -------------------------------------
  def compare(f_str, variable, vars, only: nil)
    raise 'enter an expression' if f_str.nil? || f_str.to_s.strip.empty?
    expr = MathematicalExpression.new(f_str.to_s)
    raise "could not parse '#{f_str}'" unless expr.root

    env_f = {}
    env_e = {}
    (vars || {}).each do |k, v|
      r = parse_exact_scalar(v)
      env_e[k.to_s] = r if r
      env_f[k.to_s] = (r ? r.to_f : v.to_f)
    end

    lanes = []

    # AMBER - the float evaluator every existing feature already uses
    if only.nil? || only == :float
      fv = begin
        expr.evaluate(env_f)
      rescue StandardError => e
        e.message
      end
      lanes << if fv.is_a?(Numeric) && fv.to_f.finite?
                 { key: 'float', label: 'float', color: AMBER, status: 'answered',
                   value: fv.to_f.to_s,
                   note: 'always answers, never refuses - and is silently approximate. This is what every other operation in the engine runs on.' }
               else
                 { key: 'float', label: 'float', color: GREY, status: 'non-finite',
                   value: fv.to_s, note: 'the float evaluator produced no usable number' }
               end
    end

    # GREEN - conditional bounds from the interval-computation pass
    if only.nil?
      begin
        iv = expr.root.evaluate_interval(env_e.transform_values { |r| x = r.to_f; [x, x] })
        lanes << { key: 'certified', label: 'interval', color: GREEN, status: 'answered',
                   value: "[#{iv[0]}, #{iv[1]}]",
                   note: 'Conditional interval bound from outward-rounded arithmetic. Transcendental operations assume the platform math-library error fits within two ULPs; unsupported functions and invalid domains are refused.' }
      rescue StandardError => e
        lanes << { key: 'certified', label: 'interval', color: GREY, status: 'refused',
                   value: '-', note: e.message }
      end
    end

    # PURPLE - exact, or an honest refusal
    if only.nil? || only == :exact
      blockers = []
      ev = expr.root.evaluate_exact(env_e, blockers)
      lanes << if ev
                 { key: 'exact', label: 'exact', color: PURPLE, status: 'answered',
                   value: rat(ev), decimal: ev.to_f.to_s,
                   note: 'zero error - not a rounded answer but the actual rational number. This is what makes an exact ZERO-TEST possible, and every decision procedure (Risch, Rothstein-Trager, Gosper) is built out of exact zero-tests.' }
               else
                 { key: 'exact', label: 'exact', color: GREY, status: 'refused',
                   value: 'no exact value',
                   note: "#{blockers.uniq.first(3).join('; ')}. Refusing beats inventing a rational that is not there." }
               end
    end

    # the punchline: did float actually agree with the truth?
    exact_lane = lanes.find { |l| l[:key] == 'exact' && l[:status] == 'answered' }
    float_lane = lanes.find { |l| l[:key] == 'float' && l[:status] == 'answered' }
    delta = nil
    if exact_lane && float_lane
      d = float_lane[:value].to_f - exact_lane[:value].to_r
      delta = { equal: d.zero?, difference: d.to_f.abs.to_s }
    end

    { mode: 'compare', expression: expr.to_readable_string, variable: variable,
      lanes: lanes, delta: delta, steps: compare_steps(lanes, delta) }
  end

  # ---- mode: polynomial ---------------------------------------------------
  def polynomial_lab(f_str, g_str, variable)
    raise 'enter a polynomial f' if f_str.nil? || f_str.to_s.strip.empty?
    fe = MathematicalExpression.new(f_str.to_s)
    raise "could not parse '#{f_str}'" unless fe.root
    fp, ferr = ExactPolynomial.from_expression(fe.root, variable, [])
    raise "f is not an exact polynomial in #{variable}: #{ferr}" unless fp

    gp = nil
    if g_str && !g_str.to_s.strip.empty?
      ge = MathematicalExpression.new(g_str.to_s)
      raise "could not parse '#{g_str}'" unless ge.root
      gp, gerr = ExactPolynomial.from_expression(ge.root, variable, [])
      raise "g is not an exact polynomial in #{variable}: #{gerr}" unless gp
    end
    # with no g supplied, f' is the interesting partner: gcd(f, f') exposes
    # repeated roots, which is exactly what squarefree decomposition needs
    partner = gp || fp.derivative
    partner_label = gp ? 'g' : "f' (derivative)"

    exact_gcd = fp.gcd(partner)
    float_gcd = float_gcd_of(fe, gp ? g_str : nil, variable)
    disagree = float_gcd && float_gcd[:degree] != exact_gcd.degree

    sqf = fp.squarefree_decomposition
    res = fp.resultant(partner)
    roots = fp.rational_roots

    { mode: 'polynomial', variable: variable,
      f: fp.to_s(variable), partner: partner.to_s(variable), partner_label: partner_label,
      gcd: { exact: exact_gcd.to_s(variable), exact_degree: exact_gcd.degree,
             exact_pairs: exact_gcd.to_pairs,
             float: float_gcd ? float_gcd[:text] : nil,
             float_degree: float_gcd ? float_gcd[:degree] : nil,
             disagree: !!disagree },
      squarefree: sqf.map { |i, p| { multiplicity: i, factor: p.to_s(variable) } },
      squarefree_ok: fp.squarefree?,
      resultant: rat(res), resultant_zero: res.zero?,
      rational_roots: roots.map { |r| rat(r) },
      steps: polynomial_steps(partner_label, exact_gcd, float_gcd, sqf, res, roots, variable, disagree) }
  end

  # the same GCD on the OLD float class, for a like-for-like comparison
  def float_gcd_of(fe, g_str, variable)
    a = Polynomial.from_expression(fe.root, variable)
    return nil unless a
    b = if g_str
          ge = MathematicalExpression.new(g_str.to_s)
          ge.root ? Polynomial.from_expression(ge.root, variable) : nil
        else
          a.derivative
        end
    return nil unless b
    gg = a.gcd(b)
    { degree: gg.degree, text: poly_text(gg, variable) }
  rescue StandardError
    nil
  end

  def poly_text(p, variable)
    return '0' if p.nil? || p.coeffs.empty?
    p.coeffs.keys.sort.reverse.map do |d|
      cs = format('%g', p.coeffs[d])
      d.zero? ? cs : (d == 1 ? "#{cs}*#{variable}" : "#{cs}*#{variable}^#{d}")
    end.join(' + ')
  end

  def parse_exact_scalar(v)
    return v if v.is_a?(Rational)
    s = v.to_s.strip
    return nil if s.empty?
    if s =~ %r{\A-?\d+\s*/\s*\d+\z}
      n, d = s.split('/').map { |t| t.strip.to_i }
      return d.zero? ? nil : Rational(n, d)
    end
    r, = ExactOps.from_float(s.to_f)
    r
  end

  def rat(r)
    return r.to_s unless r.is_a?(Rational)
    r.denominator == 1 ? r.numerator.to_s : "#{r.numerator}/#{r.denominator}"
  end

  def compare_steps(lanes, delta)
    steps = lanes.map { |l| { rule: "#{l[:label]}: #{l[:value]} - #{l[:note]}" } }
    if delta
      steps << { rule: if delta[:equal]
                         'float happened to agree exactly with the exact value here'
                       else
                         "float differs from the exact value by #{delta[:difference]} - small, but this is precisely the gap that makes a float zero-test a guess"
                       end }
    end
    steps
  end

  def polynomial_steps(partner_label, eg, fg, sqf, res, roots, variable, disagree)
    steps = []
    steps << { rule: 'Exact polynomial over Q: coefficients are Rationals, so "is this coefficient zero?" is a fact rather than a 1e-10 judgement call' }
    steps << { rule: "gcd(f, #{partner_label}) = #{eg.to_s(variable)} (degree #{eg.degree}), by primitive PRS, returned in canonical primitive form (integer coefficients, positive leading term) rather than merely monic" }
    if fg
      steps << { rule: if disagree
                         "the float Polynomial reports degree #{fg[:degree]} for the SAME gcd - structurally different, because a remainder that should be exactly 0 never lands on exactly 0.0"
                       else
                         "the float Polynomial agrees here (degree #{fg[:degree]}) - it does not always; try f = x^4 - 4*x^3/3 + 6*x^2/9 - 4*x/27 + 1/81"
                       end }
    end
    steps << { rule: sqf.empty? ? 'squarefree decomposition: f is already squarefree' : "squarefree (Yun): f = #{sqf.map { |i, p| "(#{p.to_s(variable)})#{i > 1 ? "^#{i}" : ''}" }.join(' * ')}" }
    steps << { rule: "Res(f, #{partner_label}) = #{rat(res)}#{res.zero? ? ' - exactly zero, so they share a root. An exact test, not a comparison against a tolerance.' : ''}" }
    steps << { rule: roots.empty? ? 'no rational roots (verified exactly, not by root-finding to 1e-10)' : "exact rational roots: #{roots.map { |r| rat(r) }.join(', ')}" }
    steps << { rule: 'These three - exact GCD, squarefree decomposition, resultants - are the ingredients Rothstein-Trager needs. Gosper needs the same exact GCD machinery over shifted arguments. That is why this had to come first.' }
    steps
  end
end


# ===== vector_field_ops.rb =====
# Shared grad / div / curl / Laplacian driver, used identically by web_server.rb
# and wasm_dispatch.rb so the two transports cannot drift.
#
# ============================================================================
# WHAT EACH OPERATOR TAKES AND RETURNS  (this is the whole design)
# ============================================================================
#   grad  ∇f    SCALAR -> VECTOR    (∂f/∂x₁, …, ∂f/∂xₙ)          any n
#   div   ∇·F   VECTOR -> SCALAR    Σ ∂Fᵢ/∂xᵢ                     any n
#   curl  ∇×F   VECTOR -> VECTOR    only in 3D; SCALAR in 2D       n = 2 or 3
#   lap   ∇²f   SCALAR -> SCALAR    Σ ∂²f/∂xᵢ²                    any n
#
# The signatures are the point. div and curl consume a whole vector field, so
# the caller must supply one component per variable — there is no way to get a
# divergence out of a single scalar. An earlier build tried to be helpful by
# defaulting F to ∇f, which quietly turned "divergence" into the Laplacian: a
# different operator, correctly computed, that nobody asked for. The Laplacian
# is now its own mode, and F is always exactly what the caller typed.
#
# WHY curl IS THE ONLY DIMENSION-RESTRICTED ONE
# The curl is the antisymmetric part of the derivative, which has n(n−1)/2
# independent components: 1 in 2D, 3 in 3D, 6 in 4D, 10 in 5D. Only at n = 3
# does that count coincide with n, which is the sole reason ∇×F can be called a
# vector at all. At n = 2 the single component is reported as a SCALAR, and at
# n = 1 (no components) or n ≥ 4 (a bivector) the request is refused rather than
# answered with something that is not a curl.
#
# grad, div and Laplacian are defined in every dimension including n = 1, where
# they degenerate to f′, F′ and f″. They are still worth allowing: the answer is
# right, and seeing the general formula collapse to the familiar one is useful.

require 'stringio'

module VectorFieldOps
  module_function

  MAX_DIM = 6

  # What each mode consumes. Drives both the validation below and the dialog.
  SCALAR_IN = %w[gradient laplacian].freeze
  VECTOR_IN = %w[divergence curl].freeze
  MODES = (SCALAR_IN + VECTOR_IN).freeze

  # Names the parser consumes before a variable lookup can ever happen:
  # ExpressionParser.tokenize substitutes pi and e textually, and FUNCTION_NAMES
  # lex as calls. Kept here rather than reaching into the parser so the message
  # can explain the consequence rather than just the rule.
  RESERVED = (%w[pi e] + ExpressionParser::FUNCTION_NAMES.map(&:downcase)).freeze

  # returns a JSON-ready Hash, or raises with a plain explanation
  def run(mode:, expression: nil, components: nil, variables: nil, **_ignored)
    mode = mode.to_s
    raise "unknown operation '#{mode}' — expected one of #{MODES.join(', ')}" unless MODES.include?(mode)

    vars = validate_vars(variables)
    n = vars.size

    if VECTOR_IN.include?(mode)
      list = (components || []).map { |c| c.to_s.strip }
      raise "#{mode} acts on a vector field: enter one component per variable (#{n} needed, #{list.reject(&:empty?).size} given)" \
        unless list.size == n && list.none?(&:empty?)
      comps = list.map { |s| parse!(s, "component '#{s}'") }
    end

    case mode
    when 'gradient'   then gradient(parse!(expression, 'expression'), vars)
    when 'laplacian'  then laplacian(parse!(expression, 'expression'), vars)
    when 'divergence' then divergence(comps, vars)
    when 'curl'       then curl(comps, vars, n)
    end
  end

  # ---------------------------------------------------------------- operators

  def gradient(f, vars)
    g = vars.map { |v| simplify_expr(f.derivative(v)) }
    { mode: 'gradient', dim: vars.size, variables: vars,
      heading: 'Gradient ∇f', symbol: '∇f', arity: 'scalar → vector',
      input: f.to_readable_string,
      labels: vars.map { |v| "∂f/∂#{v}" },
      components: g.map { |c| { formula: c.to_readable_string, latex: c.to_latex } },
      note: vars.size == 1 ?
        "In 1D the gradient is just the ordinary derivative f′." :
        "∇f in #{vars.size}D — one exact partial derivative per variable.",
      steps: [{ rule: "∇f = (#{vars.map { |v| "∂f/∂#{v}" }.join(', ')}), each an exact symbolic derivative" }] }
  end

  def laplacian(f, vars)
    # Simplify each first derivative before differentiating again: it keeps the
    # second-derivative trees small, which matters because the sum below is
    # recomposed through infix.
    seconds = vars.map { |v| simplify_expr(simplify_expr(f.derivative(v)).derivative(v)) }
    l = simplify_expr(sum_of(seconds))
    { mode: 'laplacian', dim: vars.size, variables: vars,
      heading: 'Laplacian ∇²f', symbol: '∇²f', arity: 'scalar → scalar',
      input: f.to_readable_string,
      terms: vars.each_with_index.map { |v, i|
        { label: "∂²f/∂#{v}²", formula: seconds[i].to_readable_string, latex: seconds[i].to_latex }
      },
      scalar: l.to_readable_string, latex: l.to_latex,
      note: vars.size == 1 ?
        'In 1D the Laplacian is just the second derivative f″.' :
        "∇²f = ∇·(∇f) — the divergence of the gradient, so it takes a scalar and returns a scalar.",
      steps: [{ rule: "∇²f = #{vars.map { |v| "∂²f/∂#{v}²" }.join(' + ')}" }] }
  end

  def divergence(comps, vars)
    # Show the partials, not just their sum. Without them a card reads
    # "F_x = 1, F_y = 1  ⟹  ∇·F = 0" and looks like an arithmetic error, when in
    # fact each component is differentiated AGAIN and a constant differentiates
    # to zero. The middle step is the whole explanation.
    partials = vars.each_with_index.map { |v, i| simplify_expr(comps[i].derivative(v)) }
    d = simplify_expr(sum_of(partials))
    { mode: 'divergence', dim: vars.size, variables: vars,
      heading: 'Divergence ∇·F', symbol: '∇·F', arity: 'vector → scalar',
      field: field_label(comps, vars),
      terms: vars.each_with_index.map { |v, i|
        { label: "∂F_#{v}/∂#{v}", formula: partials[i].to_readable_string, latex: partials[i].to_latex }
      },
      scalar: d.to_readable_string, latex: d.to_latex,
      note: vars.size == 1 ?
        'In 1D the divergence is just dF/dx.' :
        "∇·F sums one partial per variable — defined in every dimension.",
      steps: [{ rule: "∇·F = #{vars.map { |v| "∂F_#{v}/∂#{v}" }.join(' + ')}" }] }
  end

  def curl(comps, vars, n)
    case n
    when 2
      t1 = simplify_expr(comps[1].derivative(vars[0]))
      t2 = simplify_expr(comps[0].derivative(vars[1]))
      s = simplify_expr(combine([t1, t2], '-'))
      { mode: 'curl', dim: 2, variables: vars, scalar_curl: true,
        heading: 'Curl ∇×F — a scalar', symbol: '∇×F', arity: 'vector → scalar (2D)',
        field: field_label(comps, vars),
        terms: [{ label: "∂F_#{vars[1]}/∂#{vars[0]}", formula: t1.to_readable_string, latex: t1.to_latex },
                { label: "∂F_#{vars[0]}/∂#{vars[1]}", formula: t2.to_readable_string, latex: t2.to_latex }],
        scalar: s.to_readable_string, latex: s.to_latex,
        note: "In 2D the antisymmetric derivative has a single component, so the curl is a SCALAR: ∂F_#{vars[1]}/∂#{vars[0]} − ∂F_#{vars[0]}/∂#{vars[1]}.",
        steps: [{ rule: "2D scalar curl = ∂F_#{vars[1]}/∂#{vars[0]} − ∂F_#{vars[0]}/∂#{vars[1]}" }] }
    when 3
      res = VectorCalculus.curl(comps, vars)
      out = res[:components].map { |c| simplify_expr(c) }
      a, b, c = vars
      { mode: 'curl', dim: 3, variables: vars, scalar_curl: false,
        heading: 'Curl ∇×F', symbol: '∇×F', arity: 'vector → vector (3D only)',
        field: field_label(comps, vars),
        labels: vars.map { |v| "(∇×F)_#{v}" },
        components: out.map { |e| { formula: e.to_readable_string, latex: e.to_latex } },
        note: '∇×F in 3D — the one dimension where the curl is itself a vector.',
        # spelled with the ACTUAL variable names; this line used to hardcode x/y/z
        # and so described the wrong derivative whenever the axes were renamed
        steps: [{ rule: "∇×F = (∂F_#{c}/∂#{b} − ∂F_#{b}/∂#{c},  ∂F_#{a}/∂#{c} − ∂F_#{c}/∂#{a},  ∂F_#{b}/∂#{a} − ∂F_#{a}/∂#{b})" }] }
    when 1
      raise 'curl needs at least 2 variables — in 1D the antisymmetric derivative has no components at all, so there is nothing for a curl to be.'
    else
      raise "curl is a vector only in 3D (in 2D it is a scalar). In #{n}D the antisymmetric derivative has #{n * (n - 1) / 2} components and is a bivector, not a vector — refusing rather than inventing one."
    end
  end

  # ---------------------------------------------------------------- plumbing

  def validate_vars(variables)
    vars = (variables && !variables.empty? ? variables : %w[x y z]).map { |v| v.to_s.strip }
    vars = vars.reject(&:empty?)
    raise 'need at least one variable' if vars.empty?
    raise "at most #{MAX_DIM} variables" if vars.size > MAX_DIM

    # A name the parser has already spent cannot be a variable here. `pi` and `e`
    # are substituted for their numeric values at lex time, and a function name
    # parses as a call, so differentiating "with respect to e" would quietly
    # return 0 for a term the user believes is a variable — a wrong answer that
    # looks like a right one. Refuse instead.
    stolen = vars.select { |v| RESERVED.include?(v.downcase) }.uniq
    unless stolen.empty?
      raise "#{stolen.join(', ')} #{stolen.size == 1 ? 'is a' : 'are'} reserved " \
            "#{stolen.size == 1 ? 'name' : 'names'} the parser replaces before it ever sees a variable " \
            "(pi and e become numbers, function names become calls). Rename the variable — every partial with " \
            'respect to it would otherwise come back as 0.'
    end

    # Two slots called x are not two dimensions. Left unchecked, ∇·F over [x, x]
    # adds ∂F/∂x to itself and reports twice the true divergence.
    dupes = vars.tally.select { |_, k| k > 1 }.keys
    raise "repeated variable#{dupes.size == 1 ? '' : 's'}: #{dupes.join(', ')} — each variable is one dimension, so it may appear only once" unless dupes.empty?

    vars
  end

  def parse!(s, what)
    raise "missing #{what}" if s.nil? || s.to_s.strip.empty?
    e = MathematicalExpression.new(s.to_s)
    raise "could not parse #{what}" unless e.root
    e
  end

  # MathematicalExpression has no arithmetic operators, so combine by composing
  # parseable infix and re-parsing — the same trick general_relativity.rb uses.
  # to_infix is fully parenthesised, so precedence survives the round trip.
  # (It did not always: see the negative-exponent card in §3 of the technical doc.)
  def combine(exprs, op)
    parts = exprs.map { |e| "(#{e.root.to_infix})" }
    MathematicalExpression.new(parts.join(" #{op} "))
  end

  def sum_of(list)
    combine(list, '+')
  end

  def field_label(comps, vars)
    comps.each_with_index.map { |c, i| "F_#{vars[i]} = #{c.to_readable_string}" }
  end

  # the simplifier narrates to stdout; keep API responses clean
  def simplify_expr(e)
    e.use_experimental_simplification = true
    old = $stdout
    begin
      $stdout = StringIO.new
      e.simplify
    rescue StandardError
      nil
    ensure
      $stdout = old
    end
    e
  end
end


# ===== wasm_dispatch.rb =====
# In-browser endpoint dispatch for the ruby.wasm build.
#
# Engine.solve(endpoint, json_params) -> json_result_string. It mirrors the Sinatra
# routes in web_server.rb one-for-one (same engine methods, same response shapes,
# same $expressions/$next_id store — which persists in the long-lived in-page VM),
# so the existing frontend's /api/* calls work unchanged once routed here by the
# fetch shim. $stdout is suppressed per call (the engine is chatty) and every call
# is wrapped so a failure becomes a JSON {error:} rather than a thrown exception.

$expressions ||= {}
$next_id ||= 1

module Engine
  module_function

  def solve(endpoint, json_params)
    params = (JSON.parse(json_params) rescue {})
    real = $stdout
    $stdout = StringIO.new
    begin
      dispatch(endpoint.to_s, params).to_json
    rescue => e
      { error: e.message, backtrace: (e.backtrace || [])[0..5] }.to_json
    ensure
      $stdout = real
    end
  end

  def dispatch(endpoint, data)
    case endpoint
    when 'parse'
      formula = data['expression'] || data['formula']
      return { error: 'No expression provided' } if formula.nil? || formula.to_s.empty?
      expr = MathematicalExpression.new(formula, data['variables'] || {})
      id = store(expr)
      { id: id, formula: expr.to_readable_string, latex: expr.to_latex,
        tree_text: tree_text(expr), tree_json: tree_json(expr.root) }

    when 'evaluate'
      expr = fetch(data); return not_found unless expr
      result = expr.evaluate(data['variables'] || {})
      raise 'No finite real value at these inputs (outside the real domain, a pole, or numeric overflow).' unless result.is_a?(Numeric) && result.finite? && !result.is_a?(Complex)
      { result: result, formula: expr.to_readable_string }

    when 'derivative'
      expr = fetch(data); return not_found unless expr
      expr.root = ComplexOperations.to_complex_form(expr.root) if data['complex_mode']
      result = expr.derivative(data['variable'], track_steps: data.fetch('track_steps', false),
                               aggressive_simplify: data['aggressive_simplify'] || false)
      simp = polish(result, data['simplify_mode'] || 'final')
      id = store(result)
      { id: id, original: expr.to_readable_string, formula: result.to_readable_string,
        latex: result.to_latex, steps: (result.steps || []) + simp,
        tree_text: tree_text(result), tree_json: tree_json(result.root) }

    when 'integrate'
      expr = fetch(data); return not_found unless expr
      expr.root = ComplexOperations.to_complex_form(expr.root) if data['complex_mode']
      expr.use_experimental_integration = data['experimental'] || false
      result = expr.integrate(data['variable'], track_steps: data.fetch('track_steps', true),
                              aggressive_simplify: data['aggressive_simplify'] || false)
      simp = polish(result, data['simplify_mode'] || 'final')
      id = store(result)
      out = { id: id, original: expr.to_readable_string, formula: result.to_readable_string + ' + C',
              latex: result.to_latex + ' + C', steps: (result.steps || []) + simp,
              debug_logs: result.debug_logs || [], verification: result.verification,
              tree_text: tree_text(result), tree_json: tree_json(result.root) }
      out[:taylor] = TaylorSeries.expand(result.root, data['variable'], 0, 5) if data['taylor_mode'] && result.root
      out

    when 'integrate_trace'
      expr = fetch(data); return not_found unless expr
      info = expr.integrate_verbose(data['variable'] || 'x', mode: :experimental)
      result = info[:result]
      debug_logs = (ExperimentalRisch.debug_logs.dup rescue [])
      integration_steps = result.steps || []
      before = result.to_readable_string
      result.use_experimental_simplification = true
      result.simplify(track_steps: true)
      simplify_steps = result.steps || []
      id = store(result)
      techniques = []
      collect_trace_summary(info[:trace], techniques) if info[:trace]
      failed = result.root ? result.root.to_infix.include?('integral') : true
      { id: id, original: expr.to_readable_string, formula: result.to_readable_string + ' + C',
        latex: result.to_latex + ' + C', tree_json: tree_json(result.root),
        steps: integration_steps + simplify_steps, failed: failed, before_simplify: before,
        simplify_steps: simplify_steps, debug_logs: debug_logs,
        trace: { tree_text: (expr.format_trace_tree(show_all: true) rescue 'No trace'),
                 mermaid: (expr.format_trace_mermaid rescue 'graph TD'),
                 space_plot: (expr.format_trace_space_plot rescue 'No plot'),
                 techniques: techniques } }

    when 'simplify'
      expr = fetch(data); return not_found unless expr
      before = expr.to_readable_string
      expr.use_experimental_simplification = data['experimental'] || false
      expr.simplify(track_steps: true)
      { id: data['id'].to_i, before: before, formula: expr.to_readable_string, latex: expr.to_latex,
        steps: expr.steps || [], tree_text: tree_text(expr), tree_json: tree_json(expr.root) }

    when 'gradient'
      expr = fetch(data); return not_found unless expr
      result = expr.gradient(data['variables'] || [], track_steps: true)
      comps = result[:components].map { |c| c.use_experimental_simplification = true; c.simplify; { formula: c.to_readable_string, latex: c.to_latex } }
      { original: expr.to_readable_string, components: comps, steps: result[:steps] || [] }

    when 'differential'
      expr = fetch(data); return not_found unless expr
      result = expr.differential_form(data['variables'] || [], track_steps: true)
      result[:terms].each { |t| t[:coefficient].use_experimental_simplification = true; t[:coefficient].simplify }
      { original: expr.to_readable_string,
        differential: result[:terms].map { |t| "(#{t[:coefficient].to_readable_string})#{t[:differential]}" }.join(' + '),
        terms: result[:terms].map { |t| { coefficient: t[:coefficient].to_readable_string, differential: t[:differential] } },
        steps: result[:steps] || [] }

    when 'series'
      expr = fetch(data); return not_found unless expr
      r = expr.series_expand(data['variable'] || 'x', center: (data['center'] || 0).to_f,
                             order: (data['order'] || 6).to_i, mode: data['mode'] || 'auto')
      r[:original] = expr.to_readable_string
      r

    when 'definite_integral'
      expr = fetch(data); return not_found unless expr
      lo = parse_bound(data['lower']); hi = parse_bound(data['upper'])
      expr.use_experimental_integration = true
      if data['method'] == 'mc'
        mc = expr.mc_definite_integral(data['variable'] || 'x', lo, hi)
        return { error: mc[:error] } if mc[:error]
        mc[:plot] = expr.definite_plot_data(data['variable'] || 'x', lo, hi)
        return mc
      end
      # improper (semicircle at infinity) OR a full period [0, 2π] (unit circle)
      residue_ok = lo == -Float::INFINITY || hi == Float::INFINITY ||
                   (lo.abs < 1e-12 && (hi - 2 * Math::PI).abs < 1e-9)
      residue = residue_ok ? expr.try_residue_integration(expr.root, data['variable'] || 'x', lo, hi) : nil
      if residue
        { value: residue[:value], symbolic: residue[:symbolic], method: residue[:method].to_s,
          contour: residue[:contour], visualization: residue[:visualization], steps: residue[:steps] || [],
          poles: (residue[:poles] || []).map { |p| { re: p[:re].round(6), im: p[:im].round(6), mult: p[:mult] } } }
      else
        result = expr.definite_integral(data['variable'] || 'x', lo, hi, track_steps: true)
        { value: result[:value], symbolic: result[:symbolic], method: result[:method].to_s,
          steps: result[:steps] || [], antiderivative: result[:antiderivative],
          note: result[:note], divergent: result[:divergent], singularity: result[:singularity],
          plot: expr.definite_plot_data(data['variable'] || 'x', lo, hi) }
      end

    when 'lebesgue'
      expr = fetch(data); return not_found unless expr
      r = expr.lebesgue_integrate(data['variable'] || 'x', (data['lower'] || 0).to_f, (data['upper'] || 1).to_f)
      return { error: r[:error] } if r[:error]
      r[:original] = expr.to_readable_string
      r

    when 'vector_integral'
      args = { xt: data['xt'], yt: data['yt'], t0: data['t0'], t1: data['t1'],
               form: %w[arclength flux work].include?(data['form']) ? data['form'] : 'work',
               p_str: data['p'], q_str: data['q'], f_str: data['f'] }
      prm = data['param']
      if prm && prm['name'] && !prm['name'].to_s.empty?
        name = prm['name'].to_s; at = (prm['at'] || 1).to_f; from = (prm['from'] || 0.5).to_f; to = (prm['to'] || 2).to_f
        r = VectorIntegrals.line_integral(**args, extra: { name => at })
        r[:param] = { name: name, at: at, from: from, to: to }
        r[:sweep] = VectorIntegrals.sweep_line_integral(args, name, from, to, (prm['steps'] || 11).to_i)
        if prm['expected'] && !prm['expected'].to_s.empty?
          exp_expr = MathematicalExpression.new(prm['expected'])
          r[:expected] = { formula: prm['expected'],
                           values: r[:sweep].map { |pt| (exp_expr.root.evaluate(name => pt[:s]) rescue nil)&.round(6) } }
        end
        r
      else
        VectorIntegrals.line_integral(**args)
      end

    when 'surface_integral'
      solid = data['solid'] ? { type: data['solid']['type'], r: data['solid']['r'], a: data['solid']['a'],
                                b: data['solid']['b'], c: data['solid']['c'], bbox: data['solid']['bbox'] } : nil
      SurfaceIntegrals.surface_integral(xs: data['xs'], ys: data['ys'], zs: data['zs'],
                                        u0: data['u0'], u1: data['u1'], v0: data['v0'], v1: data['v1'],
                                        mode: data['mode'] || 'scalar', p_str: data['p'], q_str: data['q'],
                                        r_str: data['r'], f_str: data['f'], solid: solid,
                                        boundary_edge: data['boundary_edge'] || 'u1')

    when 'leibniz'
      LeibnizRule.moving_domain_derivative(f_str: data['f'], a_str: data['a'], b_str: data['b'], t_val: (data['t'] || 1).to_f)

    when 'leibniz_nd'
      LeibnizHigher.transport(dim: data['dim'].to_i, f_str: data['f'], axes: data['axes'] || [],
                              center: data['center'] || [], t_val: (data['t'] || 1).to_f)

    when 'reynolds'
      ReynoldsTransport.transport(f_str: data['f'], r_str: data['r'], cx_str: data['cx'] || '0', t_val: (data['t'] || 1).to_f)

    when 'vectorop'
      VectorFieldOps.run(mode: data['mode'] || 'gradient',
                         expression: data['expression'],
                         components: data['components'],
                         variables: data['variables'])

    when 'exact'
      ExactLab.run(mode: data['mode'] || 'compare', expression: data['f'], g: data['g'],
                   variable: data['variable'] || 'x', vars: data['vars'] || {})

    when 'gr'
      GeneralRelativity.analyze(preset: data['preset'] || 'schwarzschild',
                                metric: data['metric'], coords: data['coords'],
                                params: data['params'], ranges: data['ranges'], orbit: data['orbit'])

    when 'interval'
      case data['mode']
      when 'globalmin'
        IntervalArithmetic.global_min(f_str: data['f'], box: data['box'] || {},
                                      max_boxes: (data['max_boxes'] || 1500).to_i.clamp(50, 6000))
      when 'integral'
        IntervalArithmetic.certified_integral(f_str: data['f'], variable: data['variable'] || 'x',
                                              lower: data['lower'], upper: data['upper'],
                                              tol: (data['tol'] || 1e-4).to_f)
      else
        IntervalArithmetic.enclose(f_str: data['f'], box: data['box'] || {}, splits: (data['splits'] || 32).to_i)
      end

    when 'pade'
      Pade.approximate(f_str: data['f'] || data['expression'], variable: data['variable'] || 'x',
                       center: (data['center'] || 0).to_f, l: (data['l'] || 3).to_i, m: (data['m'] || 3).to_i,
                       half_width: data['half_width'] ? data['half_width'].to_f : nil)

    when 'sindy'
      Sindy.discover(system: data['system'] || 'lorenz', noise: (data['noise'] || 0).to_f,
                     threshold: data['threshold'] ? data['threshold'].to_f : nil,
                     poly_order: data['poly_order'] ? data['poly_order'].to_i : nil,
                     use_trig: data.key?('use_trig') ? data['use_trig'] : nil,
                     rhs: data['rhs'], vars: data['vars'], x0: data['x0'],
                     dt: data['dt'] ? data['dt'].to_f : nil,
                     t_end: data['t_end'] ? data['t_end'].to_f : nil)

    else
      { error: "Unknown endpoint: #{endpoint}" }
    end
  end

  # ---- helpers (mirrors web_server.rb) ----

  def store(expr)
    id = $next_id; $next_id += 1; $expressions[id] = expr; id
  end

  def fetch(data)
    $expressions[data['id'].to_i]
  end

  def not_found
    { error: 'Expression not found' }
  end

  def polish(result, mode)
    return [] if mode == 'never'
    before = result.to_readable_string
    result.use_experimental_simplification = true
    result.simplify(track_steps: true)
    after = result.to_readable_string
    before != after ? [{ rule: "Simplification: #{before} → #{after}", from: before, to: after }] : []
  end

  # "inf"/"-inf", or any expression the engine can evaluate ("2*pi", "pi/2").
  # String#to_f alone reads "2*pi" as 2.0 and "pi" as 0.0, which would integrate
  # over the wrong interval and report it as the requested one.
  def parse_bound(v)
    s = v.to_s.strip
    d = s.downcase
    return -Float::INFINITY if ['-inf', '-infinity'].include?(d)
    return Float::INFINITY if ['inf', 'infinity', '+inf'].include?(d)
    return 0.0 if s.empty?
    begin
      e = MathematicalExpression.new(s)
      if e.root
        val = e.evaluate({})
        return val.to_f if val.is_a?(Numeric) && val.to_f.finite?
      end
    rescue StandardError
      # fall through
    end
    s.to_f
  end

  def tree_text(expr)
    out = StringIO.new
    expr.visualize_tree(output: out, show_values: false)
    out.string
  rescue => e
    "Error: #{e.message}"
  end

  def collect_trace_summary(node, list)
    icon = { success: '+', fail: '-', skip: '~' }[node.status] || '?'
    list << { technique: node.technique, expression: (node.expression || '')[0..50],
              status: node.status.to_s, result: node.result ? node.result[0..60] : nil,
              reason: node.reason, depth: node.depth, icon: icon }
    node.children.each { |c| collect_trace_summary(c, list) }
  end

  def tree_json(node)
    return nil unless node
    formatted = if node.data.is_a?(Numeric)
                  if node.data.to_f == node.data.to_i.to_f
                    node.data.to_i.to_s
                  else
                    r = node.data.rationalize(1e-10)
                    (r.denominator != 1 && r.denominator <= 1000) ? "#{r.numerator}/#{r.denominator}" : node.data.to_s
                  end
                else
                  node.data.to_s
                end
    { data: formatted, isLeaf: node.isleaf, type: node.type, left: tree_json(node.left), right: tree_json(node.right) }
  end
end

